(function(){"use strict";var w=window.ScripturaJosephusWorks||(window.ScripturaJosephusWorks={});var a=w.guerra||(w.guerra={});a[4]={"work":"guerra","book":4,"title":"Φλαυίου Ἰωσήπου ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους βιβλίον δ.","chapters":{"1":[{"number":1,"text":"Ὅσοι δὲ μετὰ τὴν Ἰωταπάτων ἅλωσιν Γαλιλαῖοι Ῥωμαίων ἀφεστήκεσαν, οὗτοι τῶν ἐν Ταριχέαις ἡττηθέντων προσεχώρουν, καὶ παρέλαβον πάντα Ῥωμαῖοι τὰ φρούρια καὶ τὰς πόλεις πλὴν Γισχάλων καὶ τῶν τὸ Ἰταβύριον ὄρος κατειληφότων."},{"number":2,"text":"συνέστη δὲ τούτοις καὶ Γάμαλα πόλις Ταριχεῶν ἄντικρυς ὑπὲρ τὴν λίμνην κειμένη. τῆς δʼ Ἀγρίππα λήξεως αὕτη τε ἦν καὶ Σωγάνη καὶ Σελεύκεια, καὶ αἱ μὲν [ἐκ] τῆς Γαυλανίτιδος ἀμφότεραι· τοῦ γὰρ ἄνω καλουμένου Γαυλανᾶ μέρος ἦν ἡ Σωγάνη, τοῦ κάτω δʼ ἡ Γάμαλα· Σελεύκεια δὲ πρὸς τῇ Σεμεχωνιτῶν λίμνῃ."},{"number":3,"text":"ταύτῃ τριάκοντα μὲν εὖρος, ἑξήκοντα δὲ μῆκος στάδιοι· διατείνει δʼ αὐτῆς τὰ ἕλη μέχρι Δάφνης χωρίου τά τε ἄλλα τρυφεροῦ καὶ πηγὰς ἔχοντος, αἳ τρέφουσαι τὸν μικρὸν καλούμενον Ἰόρδανον ὑπὸ τὸν τῆς χρυσῆς βοὸς νεὼ προπέμπουσι τῷ μεγάλῳ."},{"number":4,"text":"τοὺς μὲν οὖν ἐπὶ Σωγάνην καὶ Σελεύκειαν ὑπὸ τὴν ἀρχὴν τῆς ἀποστάσεως δεξιαῖς Ἀγρίππας προσηγάγετο, Γάμαλα δʼ οὐ προσεχώρει πεποιθυῖα τῇ δυσχωρίᾳ πλέον τῶν Ἰωταπάτων."},{"number":5,"text":"τραχὺς γὰρ αὐχὴν ἀφʼ ὑψηλοῦ κατατείνων ὄρους μέσον ἐπαίρει τένοντα, μηκύνεται δὲ ἐκ τῆς ὑπεροχῆς εἰς τοὔμπροσθεν ἐκκλίνων ὅσον κατόπιν, ὡς εἰκάζεσθαι καμήλῳ τὸ σχῆμα, παρʼ ἣν ὠνόμασται τὸ τρανὸν τῆς κλήσεως οὐκ ἐξακριβούντων τῶν ἐπιχωρίων."},{"number":6,"text":"κατὰ πλευρὰ μὲν δὴ καὶ πρόσωπον εἰς φάραγγας ἀβάτους περισχίζεται, τὸ κατʼ οὐρὰν δὲ ὀλίγον ἀναφεύγει τῆς δυσχωρίας, ὅθεν ἀπήρτηται τοῦ ὄρους· καὶ τοῦτο δʼ ἐπικαρσίᾳ παρακόψαντες τάφρῳ δύσβατον οἱ ἐπιχώριοι κατεσκεύασαν."},{"number":7,"text":"πρὸς ὀρθίῳ δὲ τῇ λαγόνι δεδομημέναι πεπύκνωντο δεινῶς ἐπʼ ἀλλήλαις αἱ οἰκίαι, κρημνιζομένῃ τε ἡ πόλις ἐοικυῖα κατέτρεχεν εἰς ἑαυτὴν ἀπὸ τῆς ὀξύτητος."},{"number":8,"text":"καὶ πρὸς μεσημβρίαν μὲν ἔκλινεν, ὁ νότιος δʼ αὐτῆς ὄχθος εἰς ἄπειρον ὕψος ἀνατείνων ἄκρα τῆς πόλεως ἦν, ἀτείχιστος δὲ ὑπὲρ αὐτὴν κρημνὸς εἰς τὴν βαθυτάτην κατατείνων φάραγγα· πηγὴ δʼ ἐντὸς τοῦ τείχους, ἐφʼ ἣν τὸ ἄστυ κατέληγεν."},{"number":9,"text":"Οὕτως οὖσαν φύσει δυσμήχανον τὴν πόλιν τειχίζων ὁ Ἰώσηπος ἐποίησεν ὀχυρωτέραν ὑπονόμοις τε καὶ διώρυξιν."},{"number":10,"text":"οἱ δʼ ἐν αὐτῇ φύσει μὲν τοῦ χωρίου θαρραλεώτεροι τῶν κατὰ τὴν Ἰωταπάτην ἦσαν, πολὺ δʼ ἐλάττους μάχιμοι, καὶ τῷ τόπῳ πεποιθότες οὐδὲ πλείονας ὑπελάμβανον πεπλήρωτο γὰρ ἡ πόλις διὰ τὴν ὀχυρότητα συμφυγόντων· παρὸ καὶ τοῖς ὑπʼ Ἀγρίππα προπεμφθεῖσιν ἐπὶ τὴν πολιορκίαν ἀντεῖχεν ἐπὶ μῆνας ἑπτά."},{"number":11,"text":"Οὐεσπασιανὸς δʼ ἄρας ἀπὸ τῆς Ἀμμαθοῦς, ἔνθα πρὸ τῆς Τιβεριάδος ἐστρατοπεδεύκει· μεθερμηνευομένη δʼ Ἀμμαθοῦς θερμὰ λέγοιτʼ ἄν, ἔστι γὰρ ἐν αὐτῇ πηγὴ θερμῶν ὑδάτων πρὸς ἄκεσιν ἐπιτηδείων· ἀφικνεῖται πρὸς τὴν Γάμαλαν."},{"number":12,"text":"καὶ πᾶσαν μὲν κυκλώσασθαι φυλακῇ τὴν πόλιν οὐχ οἷός τε ἦν οὕτως διακειμένην, πρὸς δὲ τοῖς δυνατοῖς φρουροὺς καθίστησι καὶ τὸ ὑπερκείμενον ὄρος καταλαμβάνεται."},{"number":13,"text":"τειχισαμένων δὲ ὥσπερ ἔθος τῶν ταγμάτων ὑπὲρ αὐτοῦ στρατόπεδα χωμάτων ἤρχετο κατʼ οὐράν, καὶ τὸ μὲν κατʼ ἀνατολὰς αὐτῷ μέρος, ᾗπερ ὁ ἀνωτάτω τῆς πόλεως πύργος ἦν, ἐφʼ οὗ τὸ πέμπτον καὶ δέκατον τάγμα, καὶ τὸ πέμπτον μὲν κατὰ μέσην ἐξειργάζετο τὴν πόλιν, τὰς δὲ διώρυγας ἀνεπλήρου καὶ τὰς φάραγγας τὸ δέκατον."},{"number":14,"text":"κἀν τούτῳ προσελθόντα τοῖς τείχεσιν Ἀγρίππαν τὸν βασιλέα καὶ περὶ παραδόσεως τοῖς ἐφεστῶσι πειρώμενον διαλέγεσθαι βάλλει τις τῶν σφενδονητῶν κατὰ τὸν δεξιὸν ἀγκῶνα λίθῳ."},{"number":15,"text":"καὶ ὁ μὲν ὑπὸ τῶν οἰκείων θᾶττον περιεσχέθη, Ῥωμαίους δὲ ἐπήγειρεν εἰς τὴν πολιορκίαν ὀργή τε περὶ τοῦ βασιλέως καὶ περὶ σφῶν αὐτῶν δέος·"},{"number":16,"text":"οὐ γὰρ ἀπολείψειν ὠμότητος ὑπερβολὴν κατʼ ἀλλοφύλων καὶ πολεμίων τοὺς πρὸς ὁμόφυλον καὶ τῶν συμφερόντων αὐτοῖς σύμβουλον οὕτως ἀγριωθέντας."},{"number":17,"text":"Συντελεσθέντων οὖν τῶν χωμάτων θᾶττον πλήθει χειρῶν καὶ τῶν πραττομένων ἔθει προσῆγον τὰς μηχανάς."},{"number":18,"text":"οἱ δὲ περὶ τὸν Χάρητα καὶ Ἰώσηπον, οὗτοι γὰρ ἦσαν τῶν κατὰ τὴν πόλιν δυνατώτατοι, καίπερ καταπεπληγότας τοὺς ὁπλίτας τάττουσιν, ἐπειδὴ μέχρι πολλοῦ πρὸς τὴν πολιορκίαν ἀνθέξειν οὐχ ὑπελάμβανον ὕδατι καὶ τοῖς ἄλλοις ἐπιτηδείοις μὴ διαρκούμενοι."},{"number":19,"text":"παρακροτήσαντες δʼ ὅμως ἐξήγαγον ἐπὶ τὸ τεῖχος, καὶ πρὸς ὀλίγον μὲν ἀπημύναντο τοὺς προσάγοντας τὰς μηχανάς, βαλλόμενοι δὲ τοῖς καταπελτικοῖς καὶ τοῖς πετροβόλοις ἀνεχώρουν εἰς τὴν πόλιν."},{"number":20,"text":"καὶ προσάγοντες οἱ Ῥωμαῖοι τριχόθεν τοὺς κριοὺς διασείουσι μὲν τὸ τεῖχος, ὑπὲρ δὲ τῶν ἐρειφθέντων εἰσχεόμενοι μετὰ πολλοῦ σαλπίγγων ἤχου καὶ κτύπου τῶν ὅπλων αὐτοί τʼ ἐπαλαλάζοντες συνερρήγνυντο τοῖς κατὰ τὴν πόλιν."},{"number":21,"text":"οἱ δὲ τέως μὲν κατὰ τὰς πρώτας εἰσόδους ἐνιστάμενοι προσωτέρω χωρεῖν ἐκώλυον καὶ καρτερῶς τοὺς Ῥωμαίους ἀνεῖργον·"},{"number":22,"text":"βιαζόμενοι δὲ ὑπὸ πολλῶν καὶ πάντοθεν τρέπονται πρὸς τὰ ὑψηλὰ τῆς πόλεως καὶ προσκειμένοις τοῖς πολεμίοις ἐξ ὑποστροφῆς ἐπιπεσόντες συνώθουν εἰς τὸ κάταντες καὶ τῇ στενότητι καὶ δυσχωρίᾳ θλιβομένους ἀνῄρουν."},{"number":23,"text":"οἱ δὲ μήτε τοὺς κατὰ κορυφὴν ἀμύνασθαι δυνάμενοι μήτε διεκπαίειν τῶν σφετέρων πρόσω βιαζομένων ἐπὶ τὰς οἰκίας τῶν πολεμίων, πρόσγειοι γὰρ ἦσαν, ἀνέφευγον."},{"number":24,"text":"αἱ δὲ ταχέως κατηρείποντο πληρούμεναι καὶ τὸ βάρος μὴ στέγουσαι, κατέσειε δὲ πολλὰς μία τῶν ὑπʼ αὐτῆς πεσοῦσα καὶ πάλιν ἐκεῖναι τὰς ὑπʼ αὐτάς."},{"number":25,"text":"τοῦτο πλείστους διέφθειρε τῶν Ῥωμαίων· ὑπὸ γὰρ ἀμηχανίας καίτοι συνιζανούσας ὁρῶντες ἐπεπήδων ταῖς στέγαις, καὶ πολλοὶ μὲν κατεχώννυντο τοῖς ἐρειπίοις, πολλοὶ δʼ ὑποφεύγοντες μέρη τοῦ σώματος κατελαμβάνοντο, πλείστους δὲ ὁ κονιορτὸς ἄγχων ἀνῄρει."},{"number":26,"text":"συνεργίαν θεοῦ τοῦτο Γαμαλεῖς ὑπελάμβανον καὶ τῆς κατὰ σφᾶς ἀμελοῦντες βλάβης ἐπέκειντο, πρός τε τὰ στέγη τοὺς πολεμίους ἀνωθοῦντες καί τοι κατολισθάνοντας ἐν ὀξέσι τοῖς στενωποῖς καὶ ἀεὶ τοὺς πίπτοντας ὕπερθεν βάλλοντες ἔκτεινον."},{"number":27,"text":"καὶ τὰ μὲν ἐρείπια χερμάδων πλέα ἦν αὐτοῖς, σίδηρον δὲ παρεῖχον οἱ τῶν πολεμίων νεκροί· παρασπῶντες γὰρ τὰ τῶν πεσόντων ξίφη κατὰ τῶν δυσθανατούντων ἐχρῶντο."},{"number":28,"text":"πολλοὶ δʼ ἀπὸ πιπτόντων ἤδη τῶν δωμάτων σφᾶς αὐτοὺς βάλλοντες ἔθνησκον."},{"number":29,"text":"ἦν δʼ οὐδὲ τραπέντων ἡ φυγὴ ῥᾴδιος· κατὰ γὰρ ἄγνοιαν τῶν ὁδῶν καὶ παχύτητα τοῦ κονιορτοῦ μηδὲ ἀλλήλους ἐπιγινώσκοντες ἀνειλοῦντο καὶ περὶ σφᾶς ἔπιπτον."},{"number":30,"text":"Οἱ μὲν οὖν μόλις εὑρίσκοντες τὰς ἐξόδους ἀνεχώρησαν ἐκ τῆς πόλεως·"},{"number":31,"text":"Οὐεσπασιανὸς δʼ ἀεὶ προσμένων τοῖς πονουμένοις, δεινὸν γάρ τι πάθος αὐτὸν εἰσῄει κατερειπομένην ὁρῶντα περὶ τῷ στρατῷ τὴν πόλιν, ἐν λήθῃ τοῦ κατʼ αὐτὸν ἀσφαλοῦς γενόμενος λανθάνει κατὰ μικρὸν ἀνωτάτω τῆς πόλεως προελθών, ἔνθα μέσοις ἐγκαταλείπεται τοῖς κινδύνοις μετʼ ὀλίγων παντελῶς·"},{"number":32,"text":"οὐδὲ γὰρ ὁ παῖς αὐτῷ Τίτος τότε συμπαρῆν τηνικαῦτα πρὸς Μουκιανὸν εἰς Συρίαν ἀπεσταλμένος."},{"number":33,"text":"τραπῆναι μὲν οὖν οὔτε ἀσφαλὲς οὔτε πρέπον ἡγήσατο, μνησθεὶς δὲ τῶν ἀπὸ νεότητος αὐτῷ πεπονημένων καὶ τῆς ἰδίας ἀρετῆς, ὥσπερ ἔνθους γενόμενος, συνασπίζει μὲν τοὺς ἅμʼ αὐτῷ τά τε σώματα καὶ τὰς πανοπλίας,"},{"number":34,"text":"ὑφίσταται δὲ κατὰ κορυφὴν ἐπιρρέοντα τὸν πόλεμον καὶ οὔτε ἀνδρῶν πλῆθος οὔτε βελῶν ὑποπτήξας ἐπέμενε, μέχρι δαιμόνιον τὸ παράστημα τῆς ψυχῆς συννοήσαντες οἱ πολέμιοι ταῖς ὁρμαῖς ἐνέδοσαν."},{"number":35,"text":"ἀτονώτερον δὲ προσκειμένων αὐτὸς ὑπὸ πόδα ἀνεχώρει νῶτα μὴ δεικνὺς ἕως ἔξω τοῦ τείχους ἐγένετο."},{"number":36,"text":"πλεῖστοι μὲν οὖν Ῥωμαίων κατὰ ταύτην ἔπεσον τὴν μάχην, ἐν οἷς ὁ δεκαδάρχης Αἰβούτιος, ἀνὴρ οὐ μόνον ἐφʼ ἧς ἔπεσε παρατάξεως, ἀλλὰ πανταχοῦ καὶ πρότερον γενναιότατος φανεὶς καὶ πλεῖστα κακὰ Ἰουδαίους ἐργασάμενος."},{"number":37,"text":"ἑκατοντάρχης δέ τις, Γάλλος ὀνόματι, μετὰ στρατιωτῶν δέκα περισχεθεὶς ἐν τῇ ταραχῇ κατέδυ μὲν εἴς τινος οἰκίαν,"},{"number":38,"text":"τῶν δʼ ἐν αὐτῇ διαλαλούντων παρὰ δεῖπνον ὅσα κατὰ τῶν Ῥωμαίων ἢ περὶ σφῶν ὁ δῆμος ἐβουλεύετο κατακροασάμενος, ἦν δὲ αὐτός τε καὶ οἱ σὺν αὐτῷ Σύροι, νύκτωρ ἐπανίσταται καὶ πάντας ἀποσφάξας μετὰ τῶν στρατιωτῶν εἰς τοὺς Ῥωμαίους διασώζεται."},{"number":39,"text":"Οὐεσπασιανὸς δʼ ἀθυμοῦσαν τὴν στρατιὰν ἀνοίᾳ πταισμάτων καὶ διότι τέως οὐδαμοῦ τηλικαύτῃ συμφορᾷ κέχρηντο, τό γε μὴν πλέον αἰδουμένους ἐπὶ τῷ τὸν στρατηγὸν μόνον τοῖς κινδύνοις ἐγκαταλιπεῖν παρεμυθεῖτο,"},{"number":40,"text":"περὶ μὲν τοῦ καθʼ αὑτὸν ὑποστελλόμενος, ὡς μηδὲ τὴν ἀρχὴν μέμφεσθαι δοκοίη, δεῖν δὲ τὰ κοινὰ λέγων ἀνδρείως φέρειν τὴν τοῦ πολέμου φύσιν ἐννοοῦντας, ὡς οὐδαμοῦ τὸ νικᾶν ἀναιμωτὶ περιγίνεται, δαπανᾷ δʼ ἡ τύχη τι καὶ παρίσταται."},{"number":41,"text":"τοσαύτας μέντοι μυριάδας Ἰουδαίων ἀνελόντας αὐτοὺς ὀλίγην τῷ δαίμονι δεδωκέναι συμβολήν."},{"number":42,"text":"εἶναι δʼ ὥσπερ ἀπειροκάλων τὸ λίαν ἐπαίρεσθαι ταῖς εὐπραγίαις, οὕτως ἀνάνδρων τὸ καταπτήσσειν ἐν τοῖς πταίσμασιν· ὀξεῖα γὰρ ἐν ἀμφοτέροις ἡ μεταβολή, κἀκεῖνος ἄριστος ὁ κἀν τοῖς εὐτυχήμασιν νήφων, ἵνα μένῃ καὶ διʼ εὐθυμίας ἀναπαλαίων τὰ σφάλματα."},{"number":43,"text":"τὰ μέντοι συμβεβηκότα νῦν οὔτε μαλακισθέντων ὑμῶν οὔτε παρὰ τὴν τῶν Ἰουδαίων ἀρετὴν γέγονεν, ἀλλὰ κἀκείνοις τοῦ πλεονεκτῆσαι καὶ τοῦ διαμαρτεῖν ἡμῖν αἴτιον ἡ δυσχωρία."},{"number":44,"text":"καθʼ ἣν ἄν τις ὑμῶν μέμψαιτο τῆς ὁρμῆς τὸ ἀταμίευτον· ἀναφυγόντων γὰρ ἐπὶ τὰ ὑψηλὰ τῶν πολεμίων αὑτοὺς ὑποστέλλειν ἐχρῆν, καὶ μὴ κατὰ κορυφὴν ἱσταμένοις τοῖς κινδύνοις ἕπεσθαι, κρατοῦντας δὲ τῆς κάτω πόλεως κατʼ ὀλίγον προκαλεῖσθαι τοὺς ἀναφεύγοντας εἰς ἀσφαλῆ καὶ ἑδραίαν μάχην. νυνὶ δὲ ἀκρατῶς ἐπὶ τὴν νίκην ἐπειγόμενοι τῆς ἀσφαλείας ἠμελήσατε."},{"number":45,"text":"τὸ δʼ ἀπερίσκεπτον ἐν πολέμῳ καὶ τῆς ὁρμῆς μανιῶδες οὐ πρὸς Ῥωμαίων, οἳ πάντα ἐμπειρίᾳ καὶ τάξει κατορθοῦμεν, ἀλλὰ βαρβαρικόν, καὶ ᾧ μάλιστα Ἰουδαῖοι κρατοῦνται."},{"number":46,"text":"χρὴ τοίνυν ἐπὶ τὴν αὑτῶν ἀρετὴν ἀναδραμεῖν καὶ θυμοῦσθαι μᾶλλον ἢ προσαθυμεῖν τῷ παρʼ ἀξίαν πταίσματι."},{"number":47,"text":"τὴν δʼ ἀρίστην ἕκαστος ἐκ τῆς ἰδίας χειρὸς ἐπιζητείτω παραμυθίαν· οὕτω γὰρ τοῖς τε ἀπολωλόσι τιμωρήσεσθε καὶ τοὺς ἀνελόντας ἀμυνεῖσθε."},{"number":48,"text":"πειράσομαι δʼ ἐγώ, καθάπερ νῦν, ἐπὶ πάσης μάχης προάγειν τε ὑμῶν εἰς τοὺς πολεμίους καὶ τελευταῖος ἀποχωρεῖν."},{"number":49,"text":"Ὁ μὲν οὖν τοιαῦτα λέγων τὴν στρατιὰν ἀνελάμβανεν, τοῖς δὲ Γαμαλεῦσιν πρὸς ὀλίγον μὲν θαρρῆσαι τῷ κατορθώματι παρέστη παραλόγως τε συμβάντι καὶ μεγάλως,"},{"number":50,"text":"λογιζόμενοι δʼ ὕστερον ἀφῃρῆσθαι σφᾶς αὐτοὺς καὶ δεξιᾶς ἐλπίδας τό τε μὴ δύνασθαι διαφεύγειν ἐννοοῦντες, ἤδη γὰρ ἐπέλιπε τὰ ἐπιτήδεια, δεινῶς ἠθύμουν καὶ ταῖς ψυχαῖς ἀναπεπτώκεσαν."},{"number":51,"text":"οὐ μὴν εἰς τὸ δυνατὸν ἠμέλουν σωτηρίας, ἀλλὰ καὶ τὰ παραρρηχθέντα τοῦ τείχους οἱ γενναιότατοι καὶ τὰ μένοντα περισχόντες ἐφύλασσον οἱ λοιποί."},{"number":52,"text":"τῶν δὲ Ῥωμαίων ἐπιρρωννύντων τὰ χώματα καὶ πάλιν πειρωμένων προσβολῆς οἱ πολλοὶ διεδίδρασκον ἐκ τῆς πόλεως κατά τε δυσβάτων φαράγγων, ᾗπερ οὐκ ἔκειντο φυλακαί, καὶ διὰ τῶν ὑπονόμων."},{"number":53,"text":"ὅσοι γε μὴν δέει τοῦ ληφθῆναι παρέμενον, [ἐν] ἐνδείᾳ διεφθείροντο· πανταχόθεν γὰρ τροφὴ τοῖς μάχεσθαι δυναμένοις συνηθροίζετο."},{"number":54,"text":"Καὶ οἱ μὲν ἐν τοιούτοις πάθεσι διεκαρτέρουν, Οὐεσπασιανὸς δὲ πάρεργον ἐποιεῖτο τῆς πολιορκίας τοὺς τὸ Ἰταβύριον κατειληφότας ὄρος, ὅ ἐστι τοῦ μεγάλου πεδίου καὶ Σκυθοπόλεως μέσον·"},{"number":55,"text":"οὗ τὸ μὲν ὕψος ἐπὶ τριάκοντα σταδίους ἀνίσχει, μόλις προσβατὸν κατὰ τὸ προσάρκτιον κλίμα, πεδίον δʼ ἐστὶν ἡ κορυφὴ σταδίων ἓξ καὶ εἴκοσι, πᾶν τετειχισμένον."},{"number":56,"text":"ἤγειρε δὲ τοσοῦτον ὄντα τὸν περίβολον ὁ Ἰώσηπος ἐν τεσσαράκοντα ἡμέραις τῇ τε ἄλλῃ χορηγούμενος ὕλῃ κάτωθεν καὶ ὕδατι· καὶ γὰρ τοῖς ἐποίκοις μόνον ἦν ὄμβριον."},{"number":57,"text":"πολλοῦ οὖν πλήθους ἐπὶ τοῦτο συνειλεγμένου Οὐεσπασιανὸς Πλάκιδον σὺν ἱππεῦσιν ἑξακοσίοις πέμπει."},{"number":58,"text":"τούτῳ τὸ μὲν προσβαίνειν ἀμήχανον ἦν, ἐλπίδι δὲ δεξιῶν καὶ παρακλήσεως πρὸς εἰρήνην τοὺς πολλοὺς προεκαλεῖτο."},{"number":59,"text":"κατῄεσαν δὲ ἀντεπιβουλεύοντες· ὅ τε γὰρ Πλάκιδος ὡμίλει πρᾳότερον σπουδάζων αὐτοὺς ἐν τῷ πεδίῳ λαβεῖν, κἀκεῖνοι κατῄεσαν ὡς πειθόμενοι δῆθεν, ἵνα ἀφυλάκτῳ προσπέσωσιν."},{"number":60,"text":"ἐνίκα μέντοι τὸ Πλακίδου πανοῦργον· ἀρξαμένων γὰρ τῶν Ἰουδαίων μάχης φυγὴν ὑπεκρίνετο καὶ διώκοντας ἑλκύσας ἐπὶ πολὺ τοῦ πεδίου τοὺς ἱππεῖς ἐπιστρέφει, τρεψάμενος δὲ πλείστους μὲν αὐτῶν ἀναιρεῖ, τὸ δὲ λοιπὸν πλῆθος ὑποτεμόμενος εἴργει τῆς ἀνόδου."},{"number":61,"text":"καὶ οἱ μὲν τὸ Ἰταβύριον καταλιπόντες ἐπὶ Ἱεροσολύμων ἔφευγον, οἱ δὲ ἐπιχώριοι πίστεις λαβόντες, ἐπιλελοίπει δʼ αὐτοὺς ὕδωρ, τό τε ὄρος καὶ σφᾶς αὐτοὺς Πλακίδῳ παρέδοσαν."},{"number":62,"text":"Τῶν δʼ ἐπὶ τῆς Γαμάλας οἱ παραβολώτεροι μὲν φεύγοντες διελάνθανον, οἱ δʼ ἀσθενεῖς διεφθείροντο λιμῷ·"},{"number":63,"text":"τὸ μάχιμον δʼ ἀντεῖχεν τῇ πολιορκίᾳ, μέχρι δευτέρᾳ καὶ εἰκάδι μηνὸς Ὑπερβερεταίου τρεῖς τῶν ἀπὸ τοῦ πέμπτου καὶ δεκάτου τάγματος στρατιῶται περὶ τὴν ἑωθινὴν φυλακὴν ὑποδύντες τὸν προύχοντα κατὰ τούτους πύργον ὑπορύσσουσιν ἡσυχῆ."},{"number":64,"text":"τοῖς δʼ ὑπὲρ αὐτοῦ φύλαξιν οὔτε προσιόντων αἴσθησις, νὺξ γὰρ ἦν, οὔτε προσελθόντων ἐγένετο. οἱ δὲ στρατιῶται φειδόμενοι τοῦ ψόφου καὶ πέντε τοὺς κραταιοτάτους ἐκκυλίσαντες λίθους ὑποπηδῶσι."},{"number":65,"text":"κατηρείπετο δὲ ὁ πύργος ἐξαίφνης μετὰ μεγίστου ψόφου, καὶ συγκατακρημνίζονται μὲν οἱ φύλακες αὐτῷ, θορυβηθέντες δὲ οἱ κατὰ τὰς ἄλλας φυλακὰς ἔφευγον·"},{"number":66,"text":"καὶ πολλοὺς διεκπαίειν τολμῶντας οἱ Ῥωμαῖοι διέφθειραν, ἐν οἷς καὶ Ἰώσηπόν τις ὑπὲρ τὸ παρερρηγμένον τοῦ τείχους ἐκδιδράσκοντα βαλὼν ἀναιρεῖ."},{"number":67,"text":"τῶν δʼ ἀνὰ τὴν πόλιν διασεισθέντων ὑπὸ τοῦ ψόφου διαδρομή τε ἦν καὶ πτόα πολλὴ καθάπερ εἰσπεπαικότων πάντων τῶν πολεμίων."},{"number":68,"text":"ἔνθα καὶ Χάρης κατακείμενος καὶ νοσηλευόμενος ἐκλείπει πολλοῦ δέους συνεργήσαντος εἰς θάνατον τῇ νόσῳ."},{"number":69,"text":"Ῥωμαῖοί γε μὴν μεμνημένοι τοῦ προτέρου πταίσματος οὐκ εἰσέβαλλον ἕως τρίτῃ καὶ εἰκάδι τοῦ προειρημένου μηνός."},{"number":70,"text":"Τίτος δέ, ἤδη γὰρ παρῆν, ὀργῇ τῆς πληγῆς ἣν παρʼ αὐτὸν ἐπλήγησαν ἀπόντα Ῥωμαῖοι, τῶν ἱππέων ἐπιλέξας διακοσίους, πρὸς οἷς πεζοὺς , εἰσέρχεται τὴν πόλιν ἡσυχῆ."},{"number":71,"text":"καὶ παρελθόντος οἱ μὲν φύλακες αἰσθόμενοι μετὰ βοῆς ἐχώρουν ἐπὶ τὰ ὅπλα, δήλης δὲ τῆς εἰσβολῆς ταχέως καὶ τοῖς εἴσω γενομένης, οἱ μὲν ἁρπάζοντες τὰ τέκνα καὶ γυναῖκας ἐπισυρόμενοι πρὸς τὴν ἄκραν ἀνέφευγον μετὰ κωκυτοῦ καὶ βοῆς, οἱ δὲ τὸν Τίτον ὑπαντιάζοντες ἀδιαλείπτως ἔπιπτον·"},{"number":72,"text":"ὅσοι δὲ ἀπεκωλύθησαν ἐπὶ τὴν κορυφὴν ἀναδραμεῖν ὑπʼ ἀμηχανίας εἰς τὰς τῶν Ῥωμαίων φρουρὰς ἐξέπιπτον. ἄπειρος δʼ ἦν πανταχοῦ φονευομένων ὁ στόνος, καὶ τὸ αἷμα πᾶσαν ἐπέκλυζε τὴν πόλιν κατὰ πρανοῦς χεόμενον."},{"number":73,"text":"πρὸς δὲ τοὺς ἀναφεύγοντας εἰς τὴν ἄκραν ἐπεβοήθει Οὐεσπασιανὸς πᾶσαν εἰσαγαγὼν τὴν δύναμιν."},{"number":74,"text":"ἦν δʼ ἥ τε κορυφὴ πάντοθεν πετρώδης καὶ δύσβατος, εἰς ἄπειρον ὕψος ἐπηρμένη, καὶ πανταχόθεν † τοῦ βάθους κατέγεμεν περιειλημμένη κρημνοῖς κατέτεμνόν τε."},{"number":75,"text":"ἐνταῦθα τοὺς προσβαίνοντας οἱ Ἰουδαῖοι τοῖς τε ἄλλοις βέλεσι καὶ πέτρας κατακυλινδοῦντες ἐκάκουν· αὐτοὶ δὲ διʼ ὕψος ἦσαν δυσέφικτοι βέλει."},{"number":76,"text":"γίνεται δὲ πρὸς ἀπώλειαν αὐτῶν ἄντικρυς θύελλα δαιμόνιος, ἣ τὰ μὲν Ῥωμαίων ἔφερεν εἰς αὐτοὺς βέλη, τὰ δὲ αὐτῶν ἀνέστρεφεν καὶ πλάγια παρέσυρεν."},{"number":77,"text":"οὔτε δὲ τοῖς ὑποκρήμνοις ἐφίστασθαι διὰ τὴν βίαν ἐδύναντο τοῦ πνεύματος μηδὲν ἑδραῖον ἔχοντες, οὔτε τοὺς προσβαίνοντας καθορᾶν."},{"number":78,"text":"ἐπαναβαίνουσι δὲ Ῥωμαῖοι, καὶ περισχόντες οὓς μὲν ἀμυνομένους ἔφθανον, οὓς δὲ χεῖρας προΐσχοντας· ἐτόνου δὲ τὸν θυμὸν αὐτοῖς ἐπὶ πάντας ἡ μνήμη τῶν ἐπὶ τῆς πρώτης εἰσβολῆς ἀπολωλότων."},{"number":79,"text":"ἀπογινώσκοντες δὲ τὴν σωτηρίαν πανταχόθεν οἱ πολλοὶ περισχόμενοι τέκνα καὶ γυναῖκας αὑτούς τε κατεκρήμνιζον εἰς τὴν φάραγγα· βαθυτάτη δʼ αὕτη κατὰ τὴν ἄκραν ὑπορώρυκτο."},{"number":80,"text":"συνέβη δὲ τὴν Ῥωμαίων ὀργὴν τῆς εἰς ἑαυτοὺς ἀπονοίας τῶν ἁλόντων πρᾳοτέραν φανῆναι· τετρακισχίλιοι μέν γε ὑπὸ τούτων ἐσφάγησαν, οἱ δὲ ῥίψαντες ἑαυτοὺς ὑπὲρ πεντακισχιλίους εὑρέθησαν."},{"number":81,"text":"διεσώθη δὲ πλὴν δύο γυναικῶν οὐδείς· τῆς Φιλίππου δὲ ἦσαν ἀδελφῆς θυγατέρες αὗται, αὐτὸς δὲ ὁ Φίλιππος Ἰακίμου τινὸς ἀνδρὸς ἐπισήμου, τετραρχήσαντος Ἀγρίππᾳ τῷ βασιλεῖ."},{"number":82,"text":"διεσώθησαν δὲ τὰς παρὰ τὴν ἅλωσιν ὀργὰς Ῥωμαίων λαθοῦσαι· τότε γὰρ οὐδὲ νηπίων ἐφείδοντο, πολλὰ δʼ ἑκάστοτε ἁρπάζοντες ἐσφενδόνων ἀπὸ τῆς ἄκρας."},{"number":83,"text":"Γάμαλα μὲν οὕτως ἑάλω τρίτῃ καὶ εἰκάδι μηνὸς Ὑπερβερεταίου τῆς ἀποστάσεως ἀρξαμένης Γορπιαίου μηνὸς τετάρτῃ καὶ εἰκάδι."}],"2":[{"number":84,"text":"Μόνη δὲ Γίσχαλα πολίχνη τῆς Γαλιλαίας ἀχείρωτος κατελείπετο, τοῦ μὲν πλήθους εἰρηνικὰ φρονοῦντος, καὶ γὰρ ἦσαν τὸ πλέον γεωργοὶ καὶ ταῖς ἀπὸ τῶν καρπῶν ἐλπίσιν ἀεὶ προσανέχοντες, παρεισεφθαρμένου δʼ αὐτοῖς οὐκ ὀλίγου λῃστρικοῦ τάγματος, ᾧ τινες καὶ τοῦ πολιτικοῦ συνενόσουν."},{"number":85,"text":"ἐνῆγε δὲ τούτους εἰς τὴν ἀπόστασιν καὶ συνεκρότει Ληΐου τινὸς υἱὸς Ἰωάννης, γόης ἀνὴρ καὶ ποικιλώτατος τὸ ἦθος, πρόχειρος μὲν ἐλπίσαι μεγάλα, δεινὸς δὲ τῶν ἐλπισθέντων περιγενέσθαι παντί τε ὢν δῆλος ἀγαπᾶν τὸν πόλεμον εἰς δυναστείας ἐπίθεσιν."},{"number":86,"text":"ὑπὸ τούτῳ τὸ στασιῶδες ἐν τοῖς Γισχάλοις ἐτέτακτο, διʼ οὓς τυχὸν καὶ πρεσβευσάμενον περὶ παραδόσεως τὸ δημοτικὸν ἐν πολέμου μοίρᾳ τὴν Ῥωμαίων ἔφοδον ἐξεδέχετο."},{"number":87,"text":"Οὐεσπασιανὸς δὲ ἐπὶ μὲν τούτους Τίτον ἐκπέμπει σὺν χιλίοις ἱππεῦσιν, τὸ δέκατον δὲ τάγμα ἀπαίρει εἰς Σκυθόπολιν."},{"number":88,"text":"αὐτὸς δὲ σὺν δυσὶ τοῖς λοιποῖς ἐπανῆλθεν εἰς Καισάρειαν, τοῦ τε συνεχοῦς καμάτου διδοὺς ἀνάπαυσιν αὐτοῖς καὶ διʼ εὐθηνίαν τῶν πόλεων τά τε σώματα καὶ τὸ πρόθυμον ὑποθρέψειν οἰόμενος ἐπὶ τοὺς μέλλοντας ἀγῶνας·"},{"number":89,"text":"οὐ γὰρ ὀλίγον αὐτῷ πόνον ἑώρα περὶ τοῖς Ἱεροσολύμοις λειπόμενον, ἅτε δὴ βασιλείου μὲν οὔσης τῆς πόλεως καὶ προανεχούσης ὅλου τοῦ ἔθνους, συρρεόντων δὲ εἰς αὐτὴν τῶν ἐκ τοῦ πολέμου διαδιδρασκόντων."},{"number":90,"text":"τό γε μὴν φύσει τε ὀχυρὸν αὐτῆς καὶ διὰ κατασκευὴν τειχῶν ἀγωνίαν οὐ τὴν τυχοῦσαν ἐνεποίει· τὰ δὲ φρονήματα τῶν ἀνδρῶν καὶ τὰς τόλμας δυσμεταχειρίστους καὶ δίχα τειχῶν ὑπελάμβανεν."},{"number":91,"text":"διὸ δὴ τοὺς στρατιώτας καθάπερ ἀθλητὰς προήσκει τῶν ἀγώνων."},{"number":92,"text":"Τίτῳ δὲ προσιππασαμένῳ τοῖς Γισχάλοις εὐπετὲς μὲν ἦν ἐξ ἐφόδου τὴν πόλιν ἑλεῖν, εἰδὼς δέ, εἰ βίᾳ ληφθείη, διαφθαρησόμενον ὑπὸ τῶν στρατιωτῶν ἀνέδην τὸ πλῆθος, ἦν δʼ αὐτῷ κόρος ἤδη φόνων καὶ διʼ οἴκτου τὸ πλέον ἀκρίτως συναπολλύμενον τοῖς αἰτίοις, ἐβούλετο μᾶλλον ὁμολογίαις παραστήσασθαι τὴν πόλιν."},{"number":93,"text":"καὶ δὴ τοῦ τείχους ἀνδρῶν καταγέμοντος, οἳ τὸ πλέον ἦσαν ἐκ τοῦ διεφθαρμένου τάγματος, θαυμάζειν ἔφη πρὸς αὐτούς, τίνι πεποιθότες πάσης ἑαλωκυίας πόλεως μόνοι τὰ Ῥωμαίων ὅπλα μένουσιν,"},{"number":94,"text":"ἑωρακότες μὲν ὀχυρωτέρας πολλῷ πόλεις ὑπὸ μίαν προσβολὴν κατεστραμμένας, ἐν ἀσφαλείᾳ δὲ τῶν ἰδίων κτημάτων ἀπολαύοντας ὅσοι ταῖς Ῥωμαίων δεξιαῖς ἐπίστευσαν, ἃς καὶ νῦν προτείνειν αὐτοῖς μηδὲν μνησικακῶν τῆς αὐθαδείας."},{"number":95,"text":"εἶναι γὰρ συγγνωστὸν ἐλευθερίας ἐλπίδα, μηκέτι μέντοι τὴν ἐν τοῖς ἀδυνάτοις ἐπιμονήν·"},{"number":96,"text":"εἰ γὰρ οὐ πεισθήσονται λόγοις φιλανθρώποις καὶ δεξιαῖς πίστεως, πειράσειν αὐτοὺς ἀφειδῆ τὰ ὅπλα, καὶ ὅσον οὐδέπω † γνωσθήσεσθαι πιεζόμενον τοῖς Ῥωμαίων μηχανήμασιν τὸ τεῖχος, ᾧ πεποιθότες ἐπιδείκνυνται μόνοι Γαλιλαίων, ὅτι εἰσὶν αὐθάδεις αἰχμάλωτοι."},{"number":97,"text":"Πρὸς ταῦτα τῶν μὲν δημοτικῶν οὐ μόνον οὐκ ἀποκρίνεσθαί τινι μετῆν, ἀλλʼ οὐδʼ ἐπὶ τὸ τεῖχος ἀναβῆναι· προδιείληπτο γὰρ ἅπαν τοῖς λῃστρικοῖς, καὶ φύλακες τῶν πυλῶν ἦσαν, ὡς μή τινες ἢ προέλθοιεν ἐπὶ τὰς σπονδὰς ἢ δέξαιντό τινας τῶν ἱππέων εἰς τὴν πόλιν·"},{"number":98,"text":"ὁ δʼ Ἰωάννης αὐτός τε ἀγαπᾶν ἔφη τὰς προκλήσεις καὶ τοὺς ἀπειθοῦντας ἢ πείσειν ἢ συναναγκάσειν·"},{"number":99,"text":"δεῖν μέντοι τὴν ἡμέραν αὐτὸν ἐκείνην, ἑβδομὰς γὰρ ἦν, χαρίσασθαι τῷ Ἰουδαίων νόμῳ, καθʼ ἣν ὥσπερ ὅπλα κινεῖν αὐτοῖς, οὕτω καὶ τὸ συντίθεσθαι περὶ εἰρήνης ἀθέμιτον."},{"number":100,"text":"οὐκ ἀγνοεῖν δὲ οὐδὲ Ῥωμαίους, ὡς ἀργὴ πάντων αὐτοῖς ἐστιν ἡ τῆς ἑβδομάδος περίοδος, ἔν τε τῷ παραβαίνειν αὐτὴν οὐχ ἧττον ἀσεβεῖν τῶν βιασθέντων τὸν βιασάμενον. φέρειν δʼ ἐκείνῳ μὲν οὐδεμίαν βλάβην τὰ τῆς ὑπερθέσεως·"},{"number":101,"text":"τί γὰρ ἄν τις ἐν νυκτὶ βουλεύσαιτο δρασμοῦ πλέον ἐξὸν περιστρατοπεδεύσαντα παραφυλάξαι;"},{"number":102,"text":"μέγα δὲ κέρδος αὐτοῖς τὸ μηδὲν παραβῆναι τῶν πατρίων ἐθῶν. πρέπει δὲ τῷ παρὰ προσδοκίαν εἰρήνην χαριζομένῳ τοῖς σωζομένοις τηρεῖν καὶ τοὺς νόμους.-->"},{"number":103,"text":"τοιούτοις ἐσοφίζετο τὸν Τίτον, οὐ τοσοῦτον τῆς ἑβδομάδος στοχαζόμενος, ὅσον τῆς αὑτοῦ σωτηρίας· ἐδεδοίκει δὲ ἐγκαταληφθῆναι παραχρῆμα τῆς πόλεως ἁλούσης ἐν νυκτὶ καὶ φυγῇ τὰς ἐλπίδας ἔχων τοῦ βίου."},{"number":104,"text":"θεοῦ δʼ ἦν ἔργον ἄρα τοῦ σώζοντος τὸν Ἰωάννην ἐπὶ τὸν τῶν Ἱεροσολύμων ὄλεθρον τὸ μὴ μόνον πεισθῆναι Τίτον τῇ σκήψει τῆς ὑπερθέσεως, ἀλλὰ καὶ τῆς πόλεως πορρωτέρω στρατοπεδεύσασθαι πρὸς Κυδασοῖς·"},{"number":105,"text":"μεσόγειος δέ ἐστι Τυρίων κώμη καρτερά, διὰ μίσους ἀεὶ καὶ πολέμου Γαλιλαίοις, ἔχουσα πλῆθός τε οἰκητόρων καὶ τὴν ὀχυρότητα τῆς πρὸς τὸ ἔθνος διαφορᾶς ἐφόδια."},{"number":106,"text":"Νυκτὸς δʼ ὁ Ἰωάννης ὡς οὐδεμίαν περὶ τῇ πόλει Ῥωμαίων ἑώρα φυλακήν, τὸν καιρὸν ἁρπασάμενος οὐ μόνον τοὺς περὶ αὐτὸν ὁπλίτας ἀλλὰ καὶ τῶν ἀργοτέρων συχνοὺς ἅμα ταῖς γενεαῖς ἀναλαβὼν ἐπὶ Ἱεροσολύμων ἔφευγε."},{"number":107,"text":"μέχρι μὲν οὖν εἴκοσι σταδίων οἷόν τε ἦν συνεξαγαγεῖν γυναικῶν καὶ παιδίων ὄχλον ἀνθρώπῳ κατασπερχομένῳ τοῖς ὑπὲρ αἰχμαλωσίας καὶ τοῦ ζῆν φόβοις, περαιτέρω δὲ προκόπτοντος ἀπελείποντο, καὶ δειναὶ τῶν ἐωμένων ἦσαν ὀλοφύρσεις·"},{"number":108,"text":"ὅσον γὰρ ἕκαστος τῶν οἰκείων ἐγίνετο πορρωτέρω, τοσοῦτον ἐγγὺς ὑπελάμβανεν εἶναι τῶν πολεμίων, παρεῖναί τε ἤδη τοὺς αἰχμαλωτισομένους δοκοῦντες ἐπτόηντο, καὶ πρὸς τὸν ἀλλήλων ἐκ τοῦ δρόμου ψόφον ἐπεστρέφοντο καθάπερ ἤδη παρόντων οὓς ἔφευγον·"},{"number":109,"text":"ἀνοδίαις τʼ ἐνέπιπτον οἱ πολλοί, καὶ περὶ τὴν λεωφόρον ἡ τῶν φθανόντων ἔρις συνέτριβεν τοὺς πολλούς."},{"number":110,"text":"οἰκτρὸς δὲ γυναικῶν καὶ παιδίων ὄλεθρος ἦν, καί τινες πρὸς ἀνακλήσεις ἀνδρῶν τε καὶ συγγενῶν ἐθάρσησαν μετὰ κωκυτῶν ἱκετεύουσαι περιμένειν."},{"number":111,"text":"ἀλλʼ ἐνίκα τὸ Ἰωάννου παρακέλευσμα σώζειν ἑαυτοὺς ἐμβοῶντος καὶ καταφεύγειν ἔνθα καὶ περὶ τῶν ἀπολειπομένων ἀμυνοῦνται Ῥωμαίους ἂν ἁρπαγῶσι. τὸ μὲν οὖν τῶν διαδιδρασκόντων πλῆθος ὡς ἕκαστος ἰσχύος εἶχεν ἢ τάχους ἐσκέδαστο."},{"number":112,"text":"Τίτος δὲ μεθʼ ἡμέραν ἐπὶ τὰς συνθήκας πρὸς τὸ τεῖχος παρῆν."},{"number":113,"text":"ἀνοίγει δʼ αὐτῷ τὰς πύλας ὁ δῆμος, καὶ μετὰ τῶν γενεῶν προελθόντες ἀνευφήμουν ὡς εὐεργέτην καὶ φρουρᾶς ἐλευθερώσαντα τὴν πόλιν·"},{"number":114,"text":"ἐδήλουν γὰρ ἅμα τὴν τοῦ Ἰωάννου φυγὴν καὶ παρεκάλουν φείσασθαί τε αὐτῶν καὶ παρελθόντα τοὺς ὑπολειπομένους τῶν νεωτεριζόντων κολάσαι."},{"number":115,"text":"ὁ δὲ τὰς τοῦ δήμου δεήσεις ἐν δευτέρῳ θέμενος μοῖραν ἔπεμπε τῶν ἱππέων Ἰωάννην διώξουσαν, οἳ τὸν μὲν οὐ καταλαμβάνουσιν, ἔφθη γὰρ εἰς Ἱεροσόλυμα διαφυγών, τῶν δὲ συναπαράντων ἀποκτείνουσι μὲν εἰς ἑξακισχιλίους, γύναια δὲ καὶ παιδία τρισχιλίων ὀλίγον ἀποδέοντα περιελάσαντες ἀνήγαγον."},{"number":116,"text":"ὁ δὲ Τίτος ἤχθετο μὲν ἐπὶ τῷ μὴ παραχρῆμα τιμωρήσασθαι τὸν Ἰωάννην τῆς ἀπάτης, ἱκανὸν δὲ ἀστοχήσαντι τῷ θυμῷ παραμύθιον ἔχων τὸ πλῆθος τῶν αἰχμαλώτων καὶ τοὺς διεφθαρμένους εἰσῄει τε ἀνευφημούμενος εἰς τὴν πόλιν,"},{"number":117,"text":"καὶ τοῖς στρατιώταις ὀλίγον τοῦ τείχους παρασπάσαι κελεύσας νόμῳ καταλήψεως ἀπειλαῖς μᾶλλον ἢ κολάσει τοὺς ταράσσοντας τὴν πόλιν ἀνέστελλε·"},{"number":118,"text":"πολλοὺς γὰρ ἂν καὶ διὰ τὰ οἰκεῖα μίση καὶ διαφορὰς ἰδίας ἐνδείξασθαι τοὺς ἀναιτίους, εἰ διακρίνοι τοὺς τιμωρίας ἀξίους· ἄμεινον δʼ εἶναι μετέωρον ἐν φόβῳ τὸν αἴτιον καταλιπεῖν ἤ τινα τῶν οὐκ ἀξίων αὐτῷ συναπολεῖν·"},{"number":119,"text":"τὸν μὲν γὰρ ἴσως καὶ σωφρονῆσαι δέει κολάσεως τὴν ἐπὶ τοῖς παρῳχηκόσι συγγνώμην αἰδούμενον, ἀδιόρθωτον δὲ τὴν ἐπὶ τοῖς παραναλωθεῖσι τιμωρίαν εἶναι."},{"number":120,"text":"φρουρᾷ μέντοι τὴν πόλιν ἠσφαλίσατο, διʼ ἧς τούς τε νεωτερίζοντας ἐφέξειν καὶ τοὺς εἰρηνικὰ φρονοῦντας θαρραλεωτέρους καταλείψειν ἔμελλεν. Γαλιλαία μὲν οὖν οὕτως ἑάλω πᾶσα, πολλοῖς ἱδρῶσι προγυμνάσασα Ῥωμαίους ἐπὶ τὰ Ἱεροσόλυμα."}],"3":[{"number":121,"text":"Πρὸς δὲ τὴν εἴσοδον τοῦ Ἰωάννου ὁ πᾶς δῆμος ἐξεκέχυτο, καὶ περὶ ἕκαστον τῶν συμπεφευγότων μυρίος ὅμιλος συνηθροισμένοι τὰς ἔξωθεν συμφορὰς ἀνεπυνθάνοντο."},{"number":122,"text":"τῶν δὲ τὸ μὲν ἆσθμα θερμὸν ἔτι κοπτόμενον ἐδήλου τὴν ἀνάγκην, ἠλαζονεύοντο δὲ κἀν κακοῖς, οὐ πεφευγέναι Ῥωμαίους φάσκοντες, ἀλλʼ ἥκειν πολεμήσοντες αὐτοὺς ἐξ ἀσφαλοῦς·"},{"number":123,"text":"ἀλογίστων γὰρ εἶναι καὶ ἀχρήστων παραβόλως προκινδυνεύειν περὶ Γίσχαλα καὶ πολίχνας ἀσθενεῖς, δέον τὰ ὅπλα καὶ τὰς ἀκμὰς ταμιεύεσθαι τῇ μητροπόλει καὶ συμφυλάσσειν."},{"number":124,"text":"ἔνθα δὴ παρεδήλουν τὴν ἅλωσιν τῶν Γισχάλων, καὶ τὴν λεγομένην εὐσχημόνως ὑποχώρησιν αὐτῶν οἱ πολλοὶ δρασμὸν ἐνενόουν."},{"number":125,"text":"ὡς μέντοι τὰ περὶ τοὺς αἰχμαλωτισθέντας ἠκούσθη, σύγχυσις οὐ μετρία κατέσχε τὸν δῆμον, καὶ μεγάλα τῆς ἑαυτῶν ἁλώσεως συνελογίζοντο τὰ τεκμήρια."},{"number":126,"text":"Ἰωάννης δʼ ἐπὶ μὲν τοῖς καταληφθεῖσιν ἧττον ἠρυθρία, περιιὼν δʼ ἑκάστους ἐπὶ τὸν πόλεμον ἐνῆγεν ταῖς ἐλπίσιν, τὰ μὲν Ῥωμαίων ἀσθενῆ κατασκευάζων, τὴν δʼ οἰκείαν δύναμιν ἐξαίρων,"},{"number":127,"text":"καὶ κατειρωνευόμενος τῆς τῶν ἀπείρων ἀγνοίας, ὡς οὐδʼ ἂν πτερὰ λαβόντες ὑπερβαῖέν ποτε Ῥωμαῖοι τὸ Ἱεροσολύμων τεῖχος οἱ περὶ ταῖς Γαλιλαίων κώμαις κακοπαθοῦντες καὶ πρὸς τοῖς ἐκεῖ τείχεσι κατατρίψαντες τὰς μηχανάς."},{"number":128,"text":"Τούτοις τὸ πολὺ τῶν νέων προσδιεφθείρετο καὶ πρὸς [μὲν] τὸν πόλεμον ἦρτο, τῶν δὲ σωφρονούντων καὶ γηραιῶν οὐκ ἦν ὅστις οὐ τὰ μέλλοντα προορώμενος ὡς ἤδη τῆς πόλεως οἰχομένης ἐπένθει."},{"number":129,"text":"ὁ μὲν οὖν δῆμος ἦν ἐν τοιαύτῃ συγχύσει, προδιέστη δὲ τὸ κατὰ τὴν χώραν πλῆθος τῆς ἐν Ἱεροσολύμοις στάσεως."},{"number":130,"text":"ὁ μὲν γὰρ Τίτος ἀπὸ Γισχάλων εἰς Καισάρειαν, Οὐεσπασιανὸς δὲ ἀπὸ Καισαρείας εἰς Ἰάμνειαν καὶ Ἄζωτον ἀφικόμενος παρίσταταί τε αὐτὰς καὶ φρουροὺς ἐγκαταστήσας ὑπέστρεψε πολὺ πλῆθος ἐπαγόμενος τῶν ἐπὶ δεξιᾷ προσκεχωρηκότων."},{"number":131,"text":"ἐκινεῖτο δʼ ἐν ἑκάστῃ πόλει ταραχὴ καὶ πόλεμος ἐμφύλιος, ὅσον τε ἀπὸ Ῥωμαίων ἀνέπνεον εἰς ἀλλήλους τὰς χεῖρας ἐπέστρεφον. ἦν δὲ τῶν ἐρώντων τοῦ πολέμου πρὸς τοὺς ἐπιθυμοῦντας εἰρήνης ἔρις χαλεπή."},{"number":132,"text":"καὶ πρῶτον μὲν ἐν οἰκίαις ἥπτετο τῶν ὁμονοούντων πάλαι τὸ φιλόνεικον, ἔπειτα ἀφηνιάζοντες ἀλλήλων οἱ φίλτατοι [λαοὶ] καὶ συνιὼν ἕκαστος πρὸς τοὺς τὰ αὐτὰ προαιρουμένους ἤδη κατὰ πλῆθος ἀντετάσσοντο."},{"number":133,"text":"καὶ στάσις μὲν ἦν πανταχοῦ, τὸ νεωτερίζον δὲ καὶ τῶν ὅπλων ἐπιθυμοῦν ἐπεκράτει νεότητι καὶ τόλμῃ γηραιῶν καὶ σωφρόνων."},{"number":134,"text":"ἐτράποντο δὲ πρῶτον μὲν εἰς ἁρπαγὰς ἕκαστοι τῶν ἐπιχωρίων, ἔπειτα συντασσόμενοι κατὰ λόχους ἐπὶ λῃστείαν τῶν κατὰ τὴν χώραν, ὡς ὠμότητος καὶ παρανομίας ἕνεκεν αὐτοῖς μηδὲν Ῥωμαίων τοὺς ὁμοφύλους διαφέρειν καὶ πολὺ τοῖς πορθουμένοις κουφοτέραν δοκεῖν τὴν ὑπὸ Ῥωμαίοις ἅλωσιν."},{"number":135,"text":"Οἱ φρουροὶ δὲ τῶν πόλεων τὰ μὲν ὄκνῳ τοῦ κακοπαθεῖν, τὰ δὲ μίσει τοῦ ἔθνους οὐδὲν ἢ μικρὰ προσήμυνον τοῖς κακουμένοις, μέχρι κόρῳ τῶν κατὰ τὴν χώραν ἁρπαγῶν ἀθροισθέντες οἱ τῶν πανταχοῦ συνταγμάτων ἀρχιλῃσταὶ καὶ γενόμενοι πονηρίας στῖφος εἰς τὰ Ἱεροσόλυμα παρεισφθείρονται,"},{"number":136,"text":"πόλιν ἀστρατήγητον καὶ πατρίῳ μὲν ἔθει πᾶν ἀπαρατηρήτως δεχομένην τὸ ὁμόφυλον, τότε δʼ οἰομένων ἁπάντων τοὺς ἐπιχεομένους πάντας ἀπʼ εὐνοίας ἥκειν συμμάχους."},{"number":137,"text":"ὃ δὴ καὶ δίχα τῆς στάσεως ὕστερον ἐβάπτισεν τὴν πόλιν· πλήθει γὰρ ἀχρήστῳ καὶ ἀργῷ προεξαναλώθη τὰ τοῖς μαχίμοις διαρκεῖν δυνάμενα, καὶ πρὸς τῷ πολέμῳ στάσιν τε ἑαυτοῖς καὶ λιμὸν ἐπικατεσκεύασαν."},{"number":138,"text":"Ἄλλοι τε ἀπὸ τῆς χώρας λῃσταὶ παρελθόντες εἰς τὴν πόλιν καὶ τοὺς ἔνδον προσλαβόντες χαλεπωτέρους οὐδὲν ἔτι τῶν δεινῶν παρίεσαν·"},{"number":139,"text":"οἵ γε οὐ μόνον ἁρπαγαῖς καὶ λωποδυσίαις τὴν τόλμαν ἐμέτρουν, ἀλλὰ καὶ μέχρι φόνων ἐχώρουν, οὐ νυκτὸς ἢ λαθραίως ἢ ἐπὶ τοὺς τυχόντας, ἀλλὰ φανερῶς καὶ μεθʼ ἡμέραν καὶ τῶν ἐπισημοτάτων καταρχόμενοι."},{"number":140,"text":"πρῶτον μὲν γὰρ Ἀντίπαν, ἄνδρα τοῦ βασιλικοῦ γένους καὶ τῶν κατὰ τὴν πόλιν δυνατωτάτων, ὡς καὶ τοὺς δημοσίους θησαυροὺς πεπιστεῦσθαι, συλλαβόντες εἷρξαν·"},{"number":141,"text":"ἐπὶ τούτῳ Ληουίαν τινὰ τῶν ἐπισήμων καὶ Συφὰν υἱὸν Ἀρεγέτου, βασιλικὸν δʼ ἦν καὶ τούτων τὸ γένος, πρὸς δὲ τοὺς κατὰ τὴν χώραν προύχειν δοκοῦντας."},{"number":142,"text":"δεινὴ δὲ κατάπληξις εἶχε τὸν δῆμον, καὶ καθάπερ κατειλημμένης τῆς πόλεως πολέμῳ τὴν καθʼ αὑτὸν ἕκαστος σωτηρίαν ἠγάπα."},{"number":143,"text":"Τοῖς δʼ οὐκ ἀπέχρη τὰ δεσμὰ τῶν συνειλημμένων, οὐδὲ ἀσφαλὲς ᾤοντο τὸ μέχρι πολλοῦ δυνατοὺς ἄνδρας οὕτω φυλάσσειν·"},{"number":144,"text":"ἱκανοὺς μὲν γὰρ εἶναι καὶ τοὺς οἴκους αὐτῶν πρὸς ἄμυναν οὐκ ὀλιγάνδρους ὄντας, οὐ μὴν ἀλλὰ καὶ τὸν δῆμον ἐπαναστήσεσθαι τάχα κινηθέντα πρὸς τὴν παρανομίαν."},{"number":145,"text":"δόξαν οὖν ἀναιρεῖν αὐτοὺς Ἰωάννην τινὰ πέμπουσιν τὸν ἐξ αὐτῶν εἰς φόνους προχειρότατον· Δορκάδος οὗτος ἐκαλεῖτο παῖς κατὰ τὴν ἐπιχώριον γλῶσσαν· ᾧ δέκα συνελθόντες εἰς τὴν εἱρκτὴν ξιφήρεις ἀποσφάττουσιν τοὺς συνειλημμένους."},{"number":146,"text":"παρανομήματι δʼ ἐν τηλικούτῳ μεγάλως ἀπεψεύδοντο καὶ προφάσεις [ἀνέπλαττον]· διαλεχθῆναι γὰρ αὐτοὺς Ῥωμαίοις περὶ παραδόσεως τῶν Ἱεροσολύμων, καὶ προδότας ἀνῃρηκέναι τῆς κοινῆς ἐλευθερίας ἔφασκον, καθόλου τʼ ἐπηλαζονεύοντο τοῖς τολμήμασιν ὡς εὐεργέται καὶ σωτῆρες τῆς πόλεως γεγενημένοι."},{"number":147,"text":"Συνέβη δὲ εἰς τοσοῦτον τὸν μὲν δῆμον ταπεινότητος καὶ δέους, ἐκείνους δὲ ἀπονοίας προελθεῖν, ὡς ἐπʼ αὐτοῖς εἶναι καὶ τὰς χειροτονίας τῶν ἀρχιερέων."},{"number":148,"text":"ἄκυρα γοῦν τὰ γένη ποιήσαντες, ἐξ ὧν κατὰ διαδοχὰς οἱ ἀρχιερεῖς ἀπεδείκνυντο, καθίστασαν ἀσήμους καὶ ἀγενεῖς, ἵνʼ ἔχοιεν συνεργοὺς τῶν ἀσεβημάτων·"},{"number":149,"text":"τοῖς γὰρ παρʼ ἀξίαν ἐπιτυχοῦσι τῆς ἀνωτάτω τιμῆς ὑπακούειν ἦν ἀνάγκη τοῖς παρασχοῦσι."},{"number":150,"text":"συνέκρουον δὲ καὶ τοὺς ἐν τέλει ποικίλαις ἐπινοίαις καὶ λογοποιίαις, καιρὸν ἑαυτοῖς ἐν ταῖς πρὸς ἀλλήλους τῶν κωλυόντων φιλονεικίαις ποιούμενοι, μέχρι τῶν εἰς ἀνθρώπους ὑπερεμπλησθέντες ἀδικημάτων ἐπὶ τὸ θεῖον μετήνεγκαν τὴν ὕβριν καὶ μεμιασμένοις τοῖς ποσὶ παρῄεσαν εἰς τὸ ἅγιον."},{"number":151,"text":"Ἐπανισταμένου τε αὐτοῖς ἤδη τοῦ πλήθους, ἐνῆγε γὰρ ὁ γεραίτατος τῶν ἀρχιερέων Ἄνανος, ἀνὴρ σωφρονέστατος καὶ τάχα ἂν διασώσας τὴν πόλιν, εἰ τὰς τῶν ἐπιβούλων χεῖρας ἐξέφυγεν, οἱ δὲ τὸν νεὼν τοῦ θεοῦ φρούριον αὑτοῖς καὶ τῶν ἀπὸ τοῦ δήμου ταραχῶν ποιοῦνται καταφυγήν, καὶ τυραννεῖον ἦν αὐτοῖς τὸ ἅγιον. παρεκίρνατο δὲ τοῖς δεινοῖς εἰρωνεία,"},{"number":152,"text":"τὸ τῶν ἐνεργουμένων ἀλγεινότερον·"},{"number":153,"text":"ἀποπειρώμενοι γὰρ τῆς τοῦ δήμου καταπλήξεως καὶ τὴν αὑτῶν δοκιμάζοντες ἰσχὺν κληρωτοὺς ἐπεχείρησαν ποιεῖν τοὺς ἀρχιερεῖς οὔσης, ὡς ἔφαμεν, κατὰ γένος αὐτῶν τῆς διαδοχῆς."},{"number":154,"text":"ἦν δὲ πρόσχημα μὲν τῆς ἐπιβουλῆς ἔθος ἀρχαῖον, ἐπειδὴ καὶ πάλαι κληρωτὴν ἔφασαν εἶναι τὴν ἀρχιερωσύνην, τὸ δὲ ἀληθὲς τοῦ βεβαιοτέρου [νόμου] κατάλυσις καὶ τέχνη πρὸς δυναστείαν τὰς ἀρχὰς διʼ αὑτῶν καθισταμένοις."},{"number":155,"text":"Καὶ δὴ μεταπεμψάμενοι μίαν τῶν ἀρχιερατικῶν φυλήν, Ἐνιάχιν καλεῖται, διεκλήρουν ἀρχιερέα, λαγχάνει δʼ ἀπὸ τύχης ὁ μάλιστα διαδείξας αὐτῶν τὴν παρανομίαν, Φαννί τις ὄνομα, υἱὸς Σαμουήλου κώμης Ἀφθίας, ἀνὴρ οὐ μόνον οὐκ ἐξ ἀρχιερέων, ἀλλʼ οὐδʼ ἐπιστάμενος σαφῶς τί ποτʼ ἦν ἀρχιερωσύνη διʼ ἀγροικίαν."},{"number":156,"text":"ἀπὸ γοῦν τῆς χώρας αὐτὸν ἄκοντα σύραντες ὥσπερ ἐπὶ σκηνῆς ἀλλοτρίῳ κατεκόσμουν προσωπείῳ τήν τʼ ἐσθῆτα περιτιθέντες τὴν ἱερὰν καὶ τὸ τί δεῖ ποιεῖν ἐπὶ καιροῦ διδάσκοντες."},{"number":157,"text":"χλεύη δʼ ἦν ἐκείνοις καὶ παιδιὰ τὸ τηλικοῦτον ἀσέβημα, τοῖς δʼ ἄλλοις ἱερεῦσιν ἐπιθεωμένοις πόρρωθεν παιζόμενον τὸν νόμον δακρύειν ἐπῄει καὶ κατέστενον τὴν τῶν ἱερῶν τιμῶν κατάλυσιν."},{"number":158,"text":"Ταύτην τὴν τόλμαν αὐτῶν οὐκ ἤνεγκεν ὁ δῆμος, ἀλλʼ ὥσπερ ἐπὶ τυραννίδος κατάλυσιν ὥρμηντο πάντες·"},{"number":159,"text":"καὶ γὰρ οἱ προύχειν αὐτῶν δοκοῦντες, Γωρίων τε υἱὸς Ἰωσήπου καὶ ὁ Γαμαλιήλου Συμεών, παρεκρότουν ἔν τε ταῖς ἐκκλησίαις ἀθρόους καὶ κατʼ ἰδίαν περιιόντες ἕκαστον ἤδη ποτὲ τίσασθαι τοὺς λυμεῶνας τῆς ἐλευθερίας καὶ καθᾶραι τῶν μιαιφόνων τὸ ἅγιον,"},{"number":160,"text":"οἵ τε δοκιμώτατοι τῶν ἀρχιερέων, Γαμάλα μὲν υἱὸς Ἰησοῦς Ἀνάνου δὲ Ἄνανος, πολλὰ τὸν δῆμον εἰς νωθείαν κατονειδίζοντες ἐν ταῖς συνόδοις ἐπήγειρον τοῖς ζηλωταῖς·"},{"number":161,"text":"τοῦτο γὰρ αὑτοὺς ἐκάλεσαν ὡς ἐπʼ ἀγαθοῖς ἐπιτηδεύμασιν ἀλλʼ οὐχὶ ζηλώσαντες τὰ κάκιστα τῶν ἔργων [καὶ] ὑπερβαλλόμενοι."},{"number":162,"text":"Καὶ δὴ συνελθόντος τοῦ πλήθους εἰς ἐκκλησίαν καὶ πάντων ἀγανακτούντων μὲν ἐπὶ τῇ καταλήψει τῶν ἁγίων ταῖς τε ἁρπαγαῖς καὶ τοῖς πεφονευμένοις, οὔπω δὲ πρὸς τὴν ἄμυναν ὡρμημένων τῷ δυσεπιχειρήτους, ὅπερ ἦν, τοὺς ζηλωτὰς ὑπολαμβάνειν, καταστὰς ἐν μέσοις ὁ Ἄνανος καὶ πολλάκις εἰς τὸν ναὸν ἀπιδὼν ἐμπλήσας τε τοὺς ὀφθαλμοὺς δακρύων"},{"number":163,"text":"ἦ καλόν γε, εἶπεν, ἦν ἐμοὶ τεθνάναι πρὶν ἐπιδεῖν τὸν οἶκον τοῦ θεοῦ τοσούτοις ἄγεσι καταγέμοντα καὶ τὰς ἀβάτους καὶ ἁγίας χώρας ποσὶ μιαιφόνων στενοχωρουμένας."},{"number":164,"text":"ἀλλὰ περικείμενος τὴν ἀρχιερατικὴν ἐσθῆτα καὶ τὸ τιμιώτατον καλούμενος τῶν σεβασμίων ὀνομάτων, ζῶ καὶ φιλοψυχῶ, μηδʼ ὑπὲρ τοὐμοῦ γήρως ὑπομένων εὐκλεῆ θάνατον † εἰ δεῖ μὴ μόνος εἰμὶ καὶ καθάπερ ἐν ἐρημίᾳ τὴν ἐμαυτοῦ ψυχὴν ἐπιδώσω μόνην ὑπὲρ τοῦ θεοῦ."},{"number":165,"text":"τί γὰρ καὶ δεῖ ζῆν ἐν δήμῳ συμφορῶν ἀναισθητοῦντι καὶ παρʼ οἷς ἀπόλωλεν ἡ τῶν ἐν χερσὶ παθῶν ἀντίληψις; ἁρπαζόμενοι γοῦν ἀνέχεσθε καὶ τυπτόμενοι σιωπᾶτε, καὶ τοῖς φονευομένοις οὐδʼ ἐπιστένει τις ἀναφανδόν."},{"number":166,"text":"ὢ τῆς πικρᾶς τυραννίδος. τί [δὲ] μέμφομαι τοὺς τυράννους; μὴ γὰρ οὐκ ἐτράφησαν ὑφʼ ὑμῶν καὶ τῆς ὑμετέρας ἀνεξικακίας;"},{"number":167,"text":"μὴ γὰρ οὐχ ὑμεῖς περιιδόντες τοὺς πρώτους συνισταμένους, ἔτι δʼ ἦσαν ὀλίγοι, πλείους ἐποιήσατε τῇ σιωπῇ καὶ καθοπλιζομένων ἠρεμοῦντες καθʼ ἑαυτῶν ἐπεστρέψατε τὰ ὅπλα,"},{"number":168,"text":"δέον τὰς πρώτας αὐτῶν ἐπικόπτειν ὁρμάς, ὅτε λοιδορίαις καθήπτοντο τῶν συγγενῶν, ὑμεῖς δὲ ἀμελήσαντες ἐφʼ ἁρπαγὰς παρωξύνατε τοὺς ἀλιτηρίους, καὶ πορθουμένων οἴκων λόγος ἦν οὐδείς· τοιγαροῦν αὐτοὺς ἥρπαζον τοὺς δεσπότας, καὶ συρομένοις διὰ μέσης τῆς πόλεως οὐδεὶς ἐπήμυνεν."},{"number":169,"text":"οἱ δὲ καὶ δεσμοῖς ᾐκίσαντο τοὺς ὑφʼ ὑμῶν προδοθέντας, ἐῶ λέγειν πόσους καὶ ποδαπούς· ἀλλʼ ἀκαταιτιάτοις ἀκρίτοις οὐδεὶς ἐβοήθησε τοῖς δεδεμένοις."},{"number":170,"text":"ἀκόλουθον ἦν ἐπιδεῖν τοὺς αὐτοὺς φονευομένους. ἐπείδομεν καὶ τοῦτο καθάπερ ἐξ ἀγέλης ζῴων ἀλόγων ἑλκομένου τοῦ κρατιστεύοντος ἀεὶ θύματος, οὐδὲ φωνήν τις ἀφῆκεν οὐχ ὅπως ἐκίνησε τὴν δεξιάν."},{"number":171,"text":"φέρετε δὴ [τοίνυν], φέρετε πατούμενα βλέποντες τὰ ἅγια καὶ πάντας ὑποθέντες αὐτοὶ τοῖς ἀνοσίοις τοὺς τῶν τολμημάτων βαθμοὺς μὴ βαρύνεσθε τὴν ὑπεροχήν· καὶ γὰρ νῦν πάντως ἂν ἐπὶ μεῖζον προύκοψαν, εἴ τι τῶν ἁγίων καταλῦσαι μεῖζον εἶχον."},{"number":172,"text":"κεκράτηται μὲν οὖν τὸ ὀχυρώτατον τῆς πόλεως· λεγέσθω γὰρ νῦν τὸ ἱερὸν ὡς ἄκρα τις ἢ φρούριον· ἔχοντες δʼ ἐπιτετειχισμένην τυραννίδα τοσαύτην καὶ τοὺς ἐχθροὺς ὑπὲρ κορυφὴν βλέποντες, τί βουλεύεσθε καὶ τίσι τὰς γνώμας προσθάλπετε;"},{"number":173,"text":"Ῥωμαίους ἄρα περιμενεῖτε, ἵνʼ ἡμῶν βοηθήσωσι τοῖς ἁγίοις; ἔχει μὲν οὕτως τὰ πράγματα τῇ πόλει, καὶ πρὸς τοσοῦτον ἥκομεν συμφορῶν, ἵνα ἡμᾶς ἐλεήσωσι καὶ πολέμιοι."},{"number":174,"text":"οὐκ ἐξαναστήσεσθε, ὦ τλημονέστατοι, καὶ πρὸς τὰς πληγὰς ἐπιστραφέντες, ὃ κἀπὶ τῶν θηρίων ἔστιν ἰδεῖν, τοὺς τύπτοντας ἀμυνεῖσθε; οὐκ ἀναμνήσεσθε τῶν ἰδίων ἕκαστος συμφορῶν οὐδὲ ἃ πεπόνθατε πρὸ ὀφθαλμῶν θέμενοι τὰς ψυχὰς ἐπʼ αὐτοὺς θήξετε πρὸς τὴν ἄμυναν;"},{"number":175,"text":"ἀπόλωλεν ἄρα παρʼ ὑμῖν τὸ τιμιώτατον τῶν παθῶν καὶ φυσικώτατον, ἐλευθερίας ἐπιθυμία, φιλόδουλοι δὲ καὶ φιλοδέσποτοι γεγόναμεν ὥσπερ ἐκ προγόνων τὸ ὑποτάσσεσθαι παραλαβόντες."},{"number":176,"text":"ἀλλʼ ἐκεῖνοί γε πολλοὺς καὶ μεγάλους ὑπὲρ τῆς αὐτονομίας πολέμους διήνεγκαν καὶ οὔτε τῆς Αἰγυπτίων οὔτε τῆς Μήδων δυναστείας ἡττήθησαν ὑπὲρ τοῦ μὴ ποιεῖν τὸ κελευόμενον."},{"number":177,"text":"καὶ τί δεῖ τὰ τῶν προγόνων λέγειν; ἀλλʼ ὁ νῦν πρὸς Ῥωμαίους πόλεμος, ἐῶ διελέγχειν πότερον λυσιτελὴς ὢν καὶ σύμφορος ἢ τοὐναντίον, τίνα δʼ οὖν ἔχει πρόφασιν;"},{"number":178,"text":"οὐ τὴν ἐλευθερίαν; εἶτα τοὺς τῆς οἰκουμένης δεσπότας μὴ φέροντες τῶν ὁμοφύλων τυράννων ἀνεξόμεθα;"},{"number":179,"text":"καίτοι τὸ μὲν τοῖς ἔξωθεν ὑπακούειν ἀνενέγκαι τις ἂν εἰς τὴν ἅπαξ ἡττήσασαν τύχην, τὸ δὲ τοῖς οἰκείοις εἴκειν πονηροῖς ἀγεννῶν ἐστι καὶ προαιρουμένων."},{"number":180,"text":"ἐπειδὴ δὲ ἅπαξ ἐμνήσθην Ῥωμαίων, οὐκ ἀποκρύψομαι πρὸς ὑμᾶς εἰπεῖν ὃ μεταξὺ τῶν λόγων ἐμπεσὸν ἐπέστρεψε τὴν διάνοιαν, ὅτι κἂν ἁλῶμεν ὑπʼ ἐκείνοις, ἀπείη δὲ ἡ πεῖρα τοῦ λόγου, χαλεπώτερον οὐδὲν παθεῖν ἔχομεν ὧν ἡμᾶς διατεθείκασιν οὗτοι."},{"number":181,"text":"πῶς δὲ οὐ δακρύων ἄξιον ἐκείνων μὲν ἐν τῷ ἱερῷ καὶ ἀναθήματα βλέπειν, τῶν δὲ ὁμοφύλων τὰ σκῦλα σεσυληκότων καὶ ἀνελόντων τὴν τῆς μητροπόλεως εὐγένειαν, καὶ πεφονευμένους ἄνδρας ὧν ἀπέσχοντο ἂν κἀκεῖνοι κρατήσαντες;"},{"number":182,"text":"καὶ Ῥωμαίους μὲν μηδέποτε ὑπερβῆναι τὸν ὅρον τῶν βεβήλων μηδὲ παραβῆναί τι τῶν ἱερῶν ἐθῶν, πεφρικέναι δὲ πόρρωθεν ὁρῶντας τοὺς τῶν ἁγίων περιβόλους,"},{"number":183,"text":"γενηθέντας δέ τινας ἐν τῇδε τῇ χώρᾳ καὶ τραφέντας ὑπὸ τοῖς ἡμετέροις ἔθεσι καὶ Ἰουδαίους καλουμένους ἐμπεριπατεῖν μέσοις τοῖς ἁγίοις θερμὰς ἔτι τὰς χεῖρας ἐξ ὁμοφύλων ἔχοντας φόνων;"},{"number":184,"text":"εἶτά τις δέδοικεν τὸν ἔξωθεν πόλεμον καὶ τοὺς ἐν συγκρίσει πολλῷ τῶν οἰκείων ἡμῖν μετριωτέρους; καὶ γὰρ ἄν, εἰ ἐτύμους δεῖ τοῖς πράγμασι τὰς κλήσεις ἐφαρμόζειν, τάχα ἂν εὕροι τις Ῥωμαίους μὲν ἡμῖν βεβαιωτὰς τῶν νόμων, πολεμίους δὲ τοὺς ἔνδον."},{"number":185,"text":"ἀλλʼ ὅτι μὲν ἐξώλεις οἱ ἐπίβουλοι τῆς ἐλευθερίας, καὶ πρὸς ἃ δεδράκασιν οὐκ ἄν τις ἐπινοήσειεν δίκην ἀξίαν κατʼ αὐτῶν, οἶμαι πάντας ἥκειν πεπεισμένους οἴκοθεν καὶ πρὸ τῶν ἐμῶν λόγων παρωξύνθαι τοῖς ἔργοις ἐπʼ αὐτούς, ἃ πεπόνθατε."},{"number":186,"text":"καταπλήσσονται δʼ ἴσως οἱ πολλοὶ τό τε πλῆθος αὐτῶν καὶ τὴν τόλμαν, ἔτι δὲ καὶ τὴν ἐκ τοῦ τόπου πλεονεξίαν."},{"number":187,"text":"ταῦτα δʼ ὥσπερ συνέστη διὰ τὴν ὑμετέραν ἀμέλειαν, καὶ νῦν αὐξηθήσεται πλέον ὑπερθεμένων· καὶ γὰρ τὸ πλῆθος αὐτοῖς ἐπιτρέφεται καθʼ ἡμέραν παντὸς πονηροῦ πρὸς τοὺς ὁμοίους αὐτομολοῦντος,"},{"number":188,"text":"καὶ τὴν τόλμαν ἐξάπτει μέχρι νῦν μηδὲν ἐμπόδιον, τῷ τε τόπῳ καθύπερθεν ὄντες χρήσαιντο καὶ μετὰ παρασκευῆς, ἂν ἡμεῖς χρόνον δῶμεν."},{"number":189,"text":"πιστεύσατε δὲ ὡς, ἐὰν προσβαίνωμεν ἐπʼ αὐτούς, ἔσονται τῇ συνειδήσει ταπεινότεροι, καὶ τὸ πλεονέκτημα τοῦ ὕψους ὁ λογισμὸς ἀπολεῖ."},{"number":190,"text":"τάχα τὸ θεῖον ὑβρισμένον ἀναστρέψει κατʼ αὐτῶν τὰ βαλλόμενα, καὶ τοῖς σφετέροις διαφθαρήσονται βέλεσιν οἱ δυσσεβεῖς. μόνον ὀφθῶμεν αὐτοῖς, καὶ καταλέλυνται."},{"number":191,"text":"καλὸν δέ, κἂν προσῇ τις κίνδυνος, ἀποθνήσκειν πρὸς τοῖς ἱεροῖς πυλῶσι καὶ τὴν ψυχὴν εἰ καὶ μὴ πρὸ παίδων ἢ γυναικῶν, ἀλλʼ ὑπὲρ τοῦ θεοῦ καὶ τῶν ἁγίων προέσθαι."},{"number":192,"text":"προστήσομαι δʼ ἐγὼ γνώμῃ τε καὶ χειρί, καὶ οὔτε ἐπίνοιά τις ὑμῖν λείψει πρὸς ἀσφάλειαν ἐξ ἡμῶν οὔτε τοῦ σώματος ὄψεσθε φειδόμενον."},{"number":193,"text":"Τούτοις ὁ Ἄνανος παρακροτεῖ τὸ πλῆθος ἐπὶ τοὺς ζηλωτάς, οὐκ ἀγνοῶν μὲν ὡς εἶεν ἤδη δυσκατάλυτοι πλήθει τε καὶ νεότητι καὶ παραστήματι ψυχῆς, τὸ πλέον δὲ συνειδήσει τῶν εἰργασμένων· οὐ γὰρ ἐνδώσειν αὐτοὺς εἰς ἐσχάτην συγγνώμην ἐφʼ οἷς ἔδρασαν ἐλπίσαντας·"},{"number":194,"text":"ὅμως δὲ πᾶν ὁτιοῦν παθεῖν προῃρεῖτο μᾶλλον ἢ περιιδεῖν ἐν τοιαύτῃ τὰ πράγματα συγχύσει."},{"number":195,"text":"τὸ δὲ πλῆθος ἄγειν αὐτοὺς ἐβόα καθʼ ὧν παρεκάλει, καὶ προκινδυνεύειν ἕκαστος ἦν ἑτοιμότατος."},{"number":196,"text":"Ἐν ὅσῳ δὲ ὁ Ἄνανος κατέλεγέ τε καὶ συνέτασσε τοὺς ἐπιτηδείους πρὸς μάχην, οἱ ζηλωταὶ πυνθανόμενοι τὴν ἐπιχείρησιν, παρῆσαν γὰρ οἱ ἀγγέλλοντες αὐτοῖς πάντα τὰ παρὰ τοῦ δήμου, παροξύνονται κἀκ τοῦ ἱεροῦ προπηδῶντες ἀθρόοι τε καὶ κατὰ λόχους οὐδενὸς ἐφείδοντο τῶν προστυγχανόντων."},{"number":197,"text":"ἀθροίζεται δὲ ὑπʼ Ἀνάνου ταχέως τὸ δημοτικόν, πλήθει μὲν ὑπερέχον, ὅπλοις δὲ καὶ τῷ μὴ συγκεκροτῆσθαι λειπόμενον τῶν ζηλωτῶν."},{"number":198,"text":"τὸ πρόθυμον δὲ παρʼ ἑκατέροις ἀνεπλήρου τὰ λείποντα, τῶν μὲν ἀπὸ τῆς πόλεως ἀνειληφότων ὀργὴν ἰσχυροτέραν τῶν ὅπλων, τῶν δὲ ἀπὸ τοῦ ἱεροῦ τόλμαν παντὸς πλήθους ὑπερέχουσαν·"},{"number":199,"text":"καὶ οἱ μὲν ἀοίκητον ὑπολαμβάνοντες αὑτοῖς τὴν πόλιν εἰ μὴ τοὺς λῃστὰς ἐκκόψειαν αὐτῆς, οἱ ζηλωταὶ δὲ εἰ μὴ κρατοῖεν οὐκ ἔστιν ἧστινος ὑστερήσειν τιμωρίας,"},{"number":200,"text":"συνερρήγνυντο στρατηγούμενοι τοῖς πάθεσι, τὸ μὲν πρῶτον κατὰ τὴν πόλιν καὶ πρὸ τοῦ ἱεροῦ λίθοις βάλλοντες ἀλλήλους καὶ πόρρωθεν διακοντιζόμενοι, κατὰ δὲ τὰς τροπὰς οἱ κρατοῦντες ἐχρῶντο τοῖς ξίφεσι· καὶ πολὺς ἦν ἑκατέρων φόνος, τραυματίαι τε ἐγίνοντο συχνοί."},{"number":201,"text":"καὶ τοὺς μὲν ἀπὸ τοῦ δήμου διεκόμιζον εἰς τὰς οἰκίας οἱ προσήκοντες, ὁ δὲ βληθεὶς τῶν ζηλωτῶν εἰς τὸ ἱερὸν ἀνῄει καθαιμάσσων τὸ θεῖον ἔδαφος· καὶ μόνον ἄν τις εἴποι τὸ ἐκείνων αἷμα μιᾶναι τὰ ἅγια."},{"number":202,"text":"κατὰ μὲν οὖν τὰς συμβολὰς ἐκτρέχοντες ἀεὶ περιῆσαν οἱ λῃστρικοί, τεθυμωμένοι δὲ οἱ δημοτικοὶ καὶ πλείους ἀεὶ γινόμενοι, κακίζοντες τοὺς ἐνδιδόντας καὶ μὴ διδόντες τοῖς τρεπομένοις ἀναχώρησιν οἱ κατόπιν βιαζόμενοι, πᾶν μὲν ἐπιστρέφουσι τὸ σφέτερον εἰς τοὺς ὑπεναντίους·"},{"number":203,"text":"κἀκείνων μηκέτʼ ἀντεχόντων τῇ βίᾳ, κατὰ μικρὸν δʼ ἀναχωρούντων εἰς τὸ ἱερὸν συνεισπίπτουσιν οἱ περὶ τὸν Ἄνανον."},{"number":204,"text":"τοῖς δὲ κατάπληξις ἐμπίπτει στερομένοις τοῦ πρώτου περιβόλου, καὶ καταφυγόντες εἰς τὸ ἐνδοτέρω ταχέως ἀποκλείουσι τὰς πύλας."},{"number":205,"text":"τῷ δʼ Ἀνάνῳ προσβαλεῖν μὲν οὐκ ἐδόκει τοῖς ἱεροῖς πυλῶσιν ἄλλως τε κἀκείνων βαλλόντων ἄνωθεν, ἀθέμιτον δʼ ἡγεῖτο, κἂν κρατήσῃ, μὴ προηγνευκὸς εἰσαγαγεῖν τὸ πλῆθος·"},{"number":206,"text":"διακληρώσας δʼ ἐκ πάντων εἰς ἑξακισχιλίους ὁπλίτας καθίστησιν ἐπὶ ταῖς στοαῖς φρουρούς·"},{"number":207,"text":"διεδέχοντο δὲ ἄλλοι τούτους, καὶ παντὶ μὲν ἀνάγκη παρεῖναι πρὸς τὴν φυλακὴν ἐκ περιόδου, πολλοὶ δὲ τῶν ἐν ἀξιώμασιν ἐφεθέντες ὑπὸ τῶν ἄρχειν δοκούντων μισθούμενοι πενιχροτέρους ἀνθʼ ἑαυτῶν ἐπὶ τὴν φρουρὰν ἔπεμπον."},{"number":208,"text":"Γίνεται δὲ τούτοις πᾶσιν ὀλέθρου παραίτιος Ἰωάννης, ὃν ἔφαμεν ἀπὸ Γισχάλων διαδρᾶναι, δολιώτατος ἀνὴρ καὶ δεινὸν ἔρωτα τυραννίδος ἐν τῇ ψυχῇ περιφέρων, ὃς πόρρωθεν ἐπεβούλευε τοῖς πράγμασιν."},{"number":209,"text":"καὶ δὴ τότε τὰ τοῦ δήμου φρονεῖν ὑποκρινόμενος συμπεριῄει μὲν τῷ Ἀνάνῳ βουλευομένῳ σὺν τοῖς δυνατοῖς μεθʼ ἡμέραν καὶ νύκτωρ ἐπιόντι τὰς φυλακάς, διήγγελλε δὲ τὰ ἀπόρρητα τοῖς ζηλωταῖς, καὶ πᾶν σκέμμα τοῦ δήμου πρὶν καλῶς βουλευθῆναι παρὰ τοῖς ἐχθροῖς ἐγινώσκετο διʼ αὐτοῦ."},{"number":210,"text":"μηχανώμενος δὲ τὸ μὴ διʼ ὑποψίας ἐλθεῖν ἀμέτροις ἐχρῆτο ταῖς θεραπείαις εἰς τόν τε Ἄνανον καὶ τοὺς τοῦ δήμου προεστῶτας."},{"number":211,"text":"ἐχώρει δʼ εἰς τοὐναντίον αὐτῷ τὸ φιλότιμον· διὰ γὰρ τὰς ἀλόγους κολακείας μᾶλλον ὑπωπτεύετο, καὶ τὸ πανταχοῦ παρεῖναι μὴ καλούμενον ἔμφασιν προδοσίας τῶν ἀπορρήτων παρεῖχε."},{"number":212,"text":"συνεώρων μὲν γὰρ αἰσθανομένους ἅπαντα τοὺς ἐχθροὺς τῶν παρʼ αὐτοῖς βουλευμάτων, πιθανώτερος δʼ οὐδεὶς ἦν Ἰωάννου πρὸς ὑποψίας τοῦ διαγγέλλειν."},{"number":213,"text":"ἀποσκευάσασθαι μὲν οὖν αὐτὸν οὐκ ἦν ῥᾴδιον ὄντα δυνατὸν ἐκ πονηρίας καὶ ἄλλως οὐ τῶν ἀσήμων ὑπεζωσμένον τε πολλοὺς τῶν συνεδρευόντων τοῖς ὅπλοις, ἐδόκει δὲ αὐτὸν ὅρκοις πιστώσασθαι πρὸς εὔνοιαν."},{"number":214,"text":"ὤμνυε δʼ ὁ Ἰωάννης ἑτοίμως εὐνοήσειν τε τῷ δήμῳ καὶ μήτε βουλήν τινα μήτε πρᾶξιν προδώσειν τοῖς ἐχθροῖς, συγκαταλύσειν δὲ τοὺς ἐπιτιθεμένους καὶ χειρὶ καὶ γνώμῃ."},{"number":215,"text":"οἱ δὲ περὶ τὸν Ἄνανον πιστεύσαντες τοῖς ὅρκοις ἤδη χωρὶς ὑπονοίας εἰς τὰς συμβουλίας αὐτὸν παρελάμβανον, καὶ δὴ καὶ πρεσβευτὴν εἰσπέμπουσι πρὸς τοὺς ζηλωτὰς περὶ διαλύσεων· ἦν γὰρ αὐτοῖς σπουδὴ τὸ παρʼ αὐτοῖς μὴ μιᾶναι τὸ ἱερὸν μηδέ τινα τῶν ὁμοφύλων ἐν αὐτῷ πεσεῖν."},{"number":216,"text":"Ὁ δʼ ὥσπερ τοῖς ζηλωταῖς ὑπὲρ εὐνοίας ὀμόσας καὶ οὐ κατʼ αὐτῶν, παρελθὼν εἴσω καὶ καταστὰς εἰς μέσους πολλάκις μὲν ἔφη κινδυνεῦσαι διʼ αὐτούς, ἵνα μηδὲν ἀγνοήσωσι τῶν ἀπορρήτων, ὅσα κατʼ αὐτῶν οἱ περὶ τὸν Ἄνανον ἐβουλεύσαντο·"},{"number":217,"text":"νῦν δὲ τὸν μέγιστον ἀναρριπτεῖν κίνδυνον σὺν πᾶσιν αὐτοῖς, εἰ μή τις προσγένοιτο βοήθεια δαιμόνιος."},{"number":218,"text":"οὐ γὰρ ἔτι μέλλειν Ἄνανον, ἀλλὰ πείσαντα μὲν τὸν δῆμον πεπομφέναι πρέσβεις πρὸς Οὐεσπασιανόν, ἵνʼ ἐλθὼν κατὰ τάχος παραλάβῃ τὴν πόλιν, ἁγνείαν δὲ παρηγγελκέναι κατʼ αὐτῶν εἰς τὴν ἑξῆς ἡμέραν, ἵνʼ ἢ κατὰ θρησκείαν εἰσελθόντες ἢ καὶ βιασάμενοι συμμίξωσιν αὐτοῖς."},{"number":219,"text":"οὐχ ὁρᾶν δὲ μέχρι τίνος ἢ τὴν φρουρὰν οἴσουσιν ἢ παρατάξονται πρὸς τοσούτους. προσετίθει δʼ ὡς αὐτὸς εἰσπεμφθείη κατὰ θεοῦ πρόνοιαν ὡς πρεσβευτὴς περὶ διαλύσεων· τὸν γὰρ Ἄνανον ταύτας αὐτοῖς προτείνειν, ὅπως ἀνυποπτοτέροις ἐπέλθῃ."},{"number":220,"text":"δεῖν οὖν ἢ τῷ λόγῳ τοῦ ζῆν τοὺς φρουροῦντας ἱκετεύειν ἢ πορίζεσθαί τινα παρὰ τῶν ἔξωθεν ἐπικουρίαν·"},{"number":221,"text":"τοὺς δὲ θαλπομένους ἐλπίδι συγγνώμης εἰ κρατηθεῖεν, ἐπιλελῆσθαι τῶν ἰδίων τολμημάτων ἢ νομίζειν ἅμα τῷ μετανοεῖν τοὺς δεδρακότας εὐθέως ὀφείλειν διηλλάχθαι καὶ τοὺς παθόντας."},{"number":222,"text":"ἀλλὰ τῶν μὲν ἀδικησάντων διὰ μίσους πολλάκις γίνεσθαι καὶ τὴν μεταμέλειαν, τοῖς ἀδικηθεῖσι δὲ τὰς ὀργὰς ἐπʼ ἐξουσίας χαλεπωτέρας·"},{"number":223,"text":"ἐφεδρεύειν δέ γε ἐκείνοις φίλους καὶ συγγενεῖς τῶν ἀπολωλότων καὶ δῆμον τοσοῦτον ὑπὲρ καταλύσεως νόμων καὶ δικαστηρίων τεθυμωμένον, ὅπου κἂν ᾖ τι μέρος τὸ ἐλεοῦν, ὑπὸ πλείονος ἂν αὐτὸ τοῦ διαγανακτοῦντος ἀφανισθῆναι."}],"4":[{"number":224,"text":"Τοιαῦτα μὲν ἐποίκιλλεν ἀθρόως δεδισσόμενος, καὶ τὴν ἔξωθεν βοήθειαν ἀναφανδὸν μὲν οὐκ ἐθάρρει λέγειν, ᾐνίσσετο δὲ τοὺς Ἰδουμαίους· ἵνα δὲ καὶ τοὺς ἡγεμόνας τῶν ζηλωτῶν ἰδίᾳ παροξύνῃ, τὸν Ἄνανον εἴς τε ὠμότητα διέβαλλε καὶ ἀπειλεῖν ἐκείνοις ἐξαιρέτως ἔλεγεν."},{"number":225,"text":"ἦσαν δὲ Ἐλεάζαρος μὲν υἱὸς Γίωνος, ὃς δὴ καὶ πιθανώτατος ἐδόκει τῶν ἐν αὐτοῖς νοῆσαί τε τὰ δέοντα καὶ τὰ νοηθέντα πρᾶξαι, Ζαχαρίας δέ τις υἱὸς Ἀμφικάλλει, γένος ἐκ τῶν ἱερέων ἑκάτερος."},{"number":226,"text":"οὗτοι πρὸς ταῖς κοιναῖς τὰς ἰδίας καθʼ ἑαυτῶν ἀπειλὰς ἀκούσαντες, ἔτι δʼ ὡς οἱ περὶ τὸν Ἄνανον δυναστείαν αὑτοῖς περιποιούμενοι Ῥωμαίους ἐπικαλοῖντο, καὶ γὰρ τοῦτο Ἰωάννης προσεψεύσατο, μέχρι πολλοῦ μὲν ἠποροῦντο, τί χρὴ πράττειν εἰς ὀξὺν οὕτως καιρὸν συνεωσμένους·"},{"number":227,"text":"παρεσκευάσθαι μὲν γὰρ τὸν δῆμον ἐπιχειρεῖν αὐτοῖς οὐκ εἰς μακράν, αὐτῶν δὲ τὸ σύντομον τῆς ἐπιβουλῆς ὑποτετμῆσθαι τὰς ἔξωθεν ἐπικουρίας· πάντα γὰρ ἂν φθῆναι παθεῖν πρὶν καὶ πυθέσθαι τινὰ τῶν συμμάχων."},{"number":228,"text":"ἔδοξε δʼ ὅμως ἐπικαλεῖσθαι τοὺς Ἰδουμαίους, καὶ γράψαντες ἐπιστολὴν σύντομον, ὡς Ἄνανος μὲν προδιδοίη Ῥωμαίοις τὴν μητρόπολιν ἐξαπατήσας τὸν δῆμον, αὐτοὶ δʼ ὑπὲρ τῆς ἐλευθερίας ἀποστάντες ἐν τῷ ἱερῷ φρουροῖντο,"},{"number":229,"text":"ὀλίγος δʼ ἔτι χρόνος αὐτοῖς βραβεύοι τὴν σωτηρίαν, εἰ δὲ μὴ βοηθήσουσιν ἐκεῖνοι κατὰ τάχος, αὐτοὶ μὲν ὑπʼ Ἀνάνῳ τε καὶ τοῖς ἐχθροῖς, ἡ πόλις δʼ ὑπὸ Ῥωμαίους φθάσει γενομένη. τὰ δὲ πολλὰ τοῖς ἀγγέλοις ἐνετέλλοντο πρὸς τοὺς ἄρχοντας τῶν Ἰδουμαίων διαλέγεσθαι."},{"number":230,"text":"προεβλήθησαν δὲ ἐπὶ τὴν ἀγγελίαν δύο τῶν δραστηρίων ἀνδρῶν εἰπεῖν τε ἱκανοὶ καὶ πεῖσαι περὶ πραγμάτων, τὸ δὲ τούτων χρησιμώτερον, ὠκύτητι ποδῶν διαφέροντες·"},{"number":231,"text":"τοὺς μὲν γὰρ Ἰδουμαίους αὐτόθεν ᾔδεισαν πεισθησομένους, ἅτε θορυβῶδες καὶ ἄτακτον ἔθνος αἰεί τε μετέωρον πρὸς τὰ κινήματα καὶ μεταβολαῖς χαῖρον, πρὸς ὀλίγην τε κολακείαν τῶν δεομένων τὰ ὅπλα κινοῦν καὶ καθάπερ εἰς ἑορτὴν εἰς τὰς παρατάξεις ἐπειγόμενον."},{"number":232,"text":"ἔδει δὲ τάχους εἰς τὴν ἀγγελίαν· εἰς ὃ μηδὲν ἐλλείποντες προθυμίας οἱ πεμφθέντες, ἐκαλεῖτο δʼ αὐτῶν Ἀνανίας ἑκάτερος, καὶ δὴ πρὸς τοὺς ἄρχοντας τῶν Ἰδουμαίων παρῆσαν."},{"number":233,"text":"Οἱ δὲ πρὸς τὴν ἐπιστολὴν καὶ τὰ ῥηθέντα παρὰ τῶν ἀφιγμένων ἐκπλαγέντες, ὥσπερ ἐμμανεῖς περιέθεόν τε τὸ ἔθνος καὶ διεκήρυσσον τὴν στρατείαν."},{"number":234,"text":"ἤθροιστο δʼ ἡ πληθὺς τάχιον τοῦ παραγγέλματος, καὶ πάντες ὡς ἐπʼ ἐλευθερίᾳ τῆς μητροπόλεως ἥρπαζον τὰ ὅπλα."},{"number":235,"text":"συνταχθέντες δὲ εἰς δύο μυριάδας παραγίνονται πρὸς τὰ Ἱεροσόλυμα, χρώμενοι τέσσαρσιν ἡγεμόσιν Ἰωάννῃ τε καὶ Ἰακώβῳ παιδὶ Σωσᾶ, πρὸς δὲ τούτοις ἦν Σίμων υἱὸς Θακήου καὶ Φινέας Κλουσώθ."},{"number":236,"text":"Τὸν δὲ Ἄνανον ἡ μὲν ἔξοδος τῶν ἀγγέλων ὥσπερ καὶ τοὺς φρουροὺς ἔλαθεν, ἡ δʼ ἔφοδος τῶν Ἰδουμαίων οὐκέτι· προγνοὺς γὰρ ἀπέκλειέ τε τὰς πύλας αὐτοῖς καὶ διὰ φυλακῆς εἶχε τὰ τείχη."},{"number":237,"text":"καθάπαν γε μὴν αὐτοὺς ἐκπολεμεῖν οὐκ ἔδοξεν, ἀλλὰ λόγοις πείθειν πρὸ τῶν ὅπλων."},{"number":238,"text":"στὰς οὖν ἐπὶ τὸν ἄντικρυς αὐτῶν πύργον ὁ μετὰ Ἄνανον γεραίτατος τῶν ἀρχιερέων Ἰησοῦς, πολλῶν ἔφη καὶ ποικίλων τὴν πόλιν κατεσχηκότων θορύβων ἐν οὐδενὶ θαυμάσαι τὴν τύχην οὕτως, ὡς τῷ συμπράττειν τοῖς πονηροῖς καὶ τὰ παράδοξα·"},{"number":239,"text":"παρεῖναι γοῦν ὑμᾶς ἀνθρώποις ἐξωλεστάτοις μετὰ τοσαύτης προθυμίας ἐπαμυνοῦντας καθʼ ἡμῶν, μεθʼ ὅσης εἰκὸς ἦν ἐλθεῖν οὐδὲ τῆς μητροπόλεως καλούσης ἐπὶ βαρβάρους."},{"number":240,"text":"καὶ εἰ μὲν ἑώρων τὴν σύνταξιν ὑμῶν ἐξ ὁμοίων τοῖς καλέσασιν ἀνδρῶν, οὐκ ἂν ἄλογον τὴν ὁρμὴν ὑπελάμβανον· οὐδὲν γὰρ οὕτως συνίστησι τὰς εὐνοίας ὡς τρόπων συγγένεια· νῦν δʼ, εἰ μέν τις αὐτοὺς ἐξετάζοι καθʼ ἕνα, μυρίων ἕκαστος εὑρεθήσεται θανάτων ἄξιος."},{"number":241,"text":"τὰ γὰρ θύματα καὶ καθάρματα τῆς πόλεως ὅλης, κατασωτευσάμενα τὰς ἰδίας οὐσίας καὶ προγυμνάσαντα τὴν ἀπόνοιαν ἐν ταῖς πέριξ κώμαις τε καὶ πόλεσι, τελευταῖα λεληθότως παρεισέρρευσαν εἰς τὴν ἱερὰν πόλιν,"},{"number":242,"text":"λῃσταὶ διʼ ὑπερβολὴν ἀσεβημάτων μιαίνοντες καὶ τὸ ἀβέβηλον ἔδαφος, οὓς ὁρᾶν ἔστι νῦν ἀδεεῖς ἐμμεθυσκομένους τοῖς ἁγίοις καὶ τὰ σκῦλα τῶν πεφονευμένων καταναλίσκοντας εἰς τὰς ἀπλήστους γαστέρας."},{"number":243,"text":"τὸ δʼ ὑμέτερον πλῆθος καὶ τὸν κόσμον τῶν ὅπλων ὁρᾶν ἔστιν οἷος ἔπρεπεν καλούσης μὲν τῆς μητροπόλεως κοινῷ βουλευτηρίῳ, συμμάχους δὲ κατʼ ἀλλοφύλων. τί ἂν οὖν εἴποι τοῦτό τις ἢ τύχης ἐπήρειαν, ὅταν λογάσι πονηροῖς αὔτανδρον ἔθνος ὁρᾷ συνασπίζον [αὐτοῖς];"},{"number":244,"text":"μέχρι πολλοῦ μὲν ἀπορῶ, τί δή ποτε καὶ τὸ κινῆσαν ὑμᾶς οὕτω ταχέως ἐγένετο· μὴ γὰρ ἂν δίχα μεγάλης αἰτίας ἀναλαβεῖν τὰς πανοπλίας ὑπὲρ λῃστῶν καὶ κατὰ δήμου συγγενοῦς·"},{"number":245,"text":"ἐπεὶ δὲ ἠκούσαμεν Ῥωμαίους καὶ προδοσίαν, ταῦτα γὰρ ὑμῶν ἐθορύβουν τινὲς ἀρτίως, καὶ τῆς μητροπόλεως ἐπʼ ἐλευθερώσει παρεῖναι, πλέον τῶν ἄλλων τολμημάτων ἐθαυμάσαμεν τοὺς ἀλιτηρίους τῆς περὶ τοῦτο ψευδοῦς ἐπινοίας·"},{"number":246,"text":"ἄνδρας γὰρ φύσει φιλελευθέρους καὶ διὰ τοῦτο μάλιστα τοῖς ἔξωθεν πολεμίοις μάχεσθαι παρεσκευασμένους οὐκ ἐνῆν ἄλλως ἐξαγριῶσαι καθʼ ἡμῶν ἢ λογοποιήσαντας προδοσίαν τῆς ποθουμένης ἐλευθερίας."},{"number":247,"text":"ἀλλʼ ὑμᾶς γε χρὴ σκέπτεσθαι τούς τε διαβάλλοντας καὶ καθʼ ὧν, συνάγειν τε τὴν ἀλήθειαν οὐκ ἐκ τῶν ἐπιπλάστων λόγων ἀλλʼ ἐκ τῶν κοινῶν πραγμάτων."},{"number":248,"text":"τί γὰρ δὴ καὶ παθόντες ἂν ἡμεῖς Ῥωμαίοις προσπωλοῖμεν ἑαυτοὺς νῦν, παρὸν ἢ μηδὲ ἀποστῆναι τὸ πρῶτον ἢ προσχωρῆσαι ταχέως ἀποστάντας ὄντων ἔτι τῶν πέριξ ἀπορθήτων;"},{"number":249,"text":"νῦν μὲν γὰρ οὐδὲ βουλομένοις διαλύσασθαι ῥᾴδιον, ὅτε Ῥωμαίους μὲν ὑπερόπτας πεποίηκεν ὑποχείριος ἡ Γαλιλαία, φέρει δʼ αἰσχύνην ἡμῖν θανάτου χαλεπωτέραν τὸ θεραπεύειν αὐτοὺς ὄντας ἤδη πλησίον."},{"number":250,"text":"καὶ ἐγὼ καθʼ ἑαυτὸν μὲν ἂν εἰρήνην προτιμήσαιμι θανάτου, πολεμούμενος δʼ ἅπαξ καὶ συμβαλὼν θάνατον εὐκλεᾶ τοῦ ζῆν αἰχμάλωτος."},{"number":251,"text":"πότερον δέ φασιν ἡμᾶς τοὺς τοῦ δήμου προεστῶτας πέμψαι κρύφα πρὸς Ῥωμαίους ἢ καὶ τὸν δῆμον κοινῇ ψηφισάμενον;"},{"number":252,"text":"εἰ μὲν ἡμᾶς, εἰπάτωσαν τοὺς πεμφθέντας φίλους, τοὺς διακονήσαντας τὴν προδοσίαν οἰκέτας. ἐφωράθη τις ἀπιών; ἀνακομιζόμενος ἑάλω;"},{"number":253,"text":"γραμμάτων γεγόνασιν ἐγκρατεῖς; πῶς δὲ τοὺς μὲν τοσούτους πολίτας ἐλάθομεν, οἷς κατὰ πᾶσαν ὥραν συναναστρεφόμεθα, τοῖς δὲ ὀλίγοις καὶ φρουρουμένοις καὶ μηδʼ εἰς τὴν πόλιν ἐκ τοῦ ἱεροῦ προελθεῖν δυναμένοις ἐγνώσθη τὰ κατὰ τὴν χώραν λαθραίως ἐνεργούμενα;"},{"number":254,"text":"νῦν δʼ ἔγνωσαν, ὅτε δεῖ δοῦναι δίκας τῶν τετολμημένων, ἕως δʼ ἦσαν ἀδεεῖς αὐτοί, προδότης ἡμῶν οὐδεὶς ὑπωπτεύετο;"},{"number":255,"text":"εἰ δʼ ἐπὶ τὸν δῆμον ἀναφέρουσι τὴν αἰτίαν, ἐν φανερῷ δήπουθεν ἐβουλεύσαντο, οὐδεὶς ἀπεστάτει τῆς ἐκκλησίας, ὥστε τάχιον ἂν τῆς μηνύσεως ἔσπευσεν ἡ φήμη πρὸς ὑμᾶς φανερωτέρα."},{"number":256,"text":"τί δέ; οὐχὶ καὶ πρέσβεις ἔδει πέμπειν ψηφισαμένους τὰς διαλύσεις; καὶ τίς ὁ χειροτονηθείς; εἰπάτωσαν."},{"number":257,"text":"ἀλλὰ τοῦτο μὲν δυσθανατούντων καὶ πλησίον οὔσας τὰς τιμωρίας διακρουομένων σκῆψίς ἐστιν· εἰ γὰρ δὴ καὶ προδοθῆναι τὴν πόλιν εἵμαρτο, μόνους ἂν τολμῆσαι καὶ τοῦτο τοὺς διαβάλλοντας, ὧν τοῖς τολμήμασιν ἓν μόνον [κακὸν] λείπει, προδοσία."},{"number":258,"text":"χρὴ δὲ ὑμᾶς, ἐπειδήπερ ἅπαξ πάρεστε μετὰ τῶν ὅπλων, τὸ μὲν δικαιότατον, ἀμύνειν τῇ μητροπόλει καὶ συνεξαιρεῖν τοὺς τὰ δικαστήρια καταλύσαντας τυράννους, οἳ πατήσαντες τοὺς νόμους ἐπὶ τοῖς αὐτῶν ξίφεσι πεποίηνται τὰς κρίσεις."},{"number":259,"text":"ἄνδρας γοῦν ἀκαταιτιάτους τῶν ἐπιφανῶν ἐκ μέσης τῆς ἀγορᾶς ἁρπάσαντες δεσμοῖς τε προῃκίσαντο καὶ μηδὲ φωνῆς μηδʼ ἱκεσίας ἀνασχόμενοι διέφθειραν."},{"number":260,"text":"ἔξεστιν δʼ ὑμῖν παρελθοῦσιν εἴσω μὴ πολέμου νόμῳ θεάσασθαι τὰ τεκμήρια τῶν λεγομένων, οἴκους ἠρημωμένους ταῖς ἐκείνων ἁρπαγαῖς καὶ γύναια καὶ γενεὰς τῶν ἀπεσφαγμένων μελανειμονούσας, κωκυτὸν δὲ καὶ θρῆνον ἀνὰ τὴν πόλιν ὅλην· οὐδεὶς γάρ ἐστιν, ὃς οὐ γέγευται τῆς τῶν ἀνοσίων καταδρομῆς·"},{"number":261,"text":"οἵ γε ἐπὶ τοσοῦτον ἐξώκειλαν ἀπονοίας, ὥστε μὴ μόνον ἐκ τῆς χώρας καὶ τῶν ἔξωθεν πόλεων ἐπὶ τὸ πρόσωπον καὶ τὴν κεφαλὴν ὅλου τοῦ ἔθνους μετενεγκεῖν τὴν λῃστρικὴν τόλμαν, ἀλλὰ καὶ ἀπὸ τῆς πόλεως ἐπὶ τὸ ἱερόν."},{"number":262,"text":"ὁρμητήριον γοῦν αὐτοῖς τοῦτο καὶ καταφυγὴ ταμιεῖόν τε τῶν ἐφʼ ἡμᾶς παρασκευῶν γέγονεν, ὁ δʼ ὑπὸ τῆς οἰκουμένης προσκυνούμενος χῶρος καὶ τοῖς ἀπὸ περάτων γῆς ἀλλοφύλοις ἀκοῇ τετιμημένος παρὰ τῶν γενηθέντων ἐνθάδε θηρίων καταπατεῖται·"},{"number":263,"text":"νεανιεύονταί τε ἐν ταῖς ἀπογνώσεσιν ἤδη δήμους τε δήμοις καὶ πόλεσι πόλεις συγκρούειν καὶ κατὰ τῶν σπλάγχνων τῶν ἰδίων τὸ ἔθνος στρατολογεῖν."},{"number":264,"text":"ἀνθʼ ὧν τὸ μὲν κάλλιστον καὶ πρέπον, ὡς ἔφην, ὑμῖν συνεξαιρεῖν τοὺς ἀλιτηρίους καὶ ὑπὲρ αὐτῆς τῆς ἀπάτης ἀμυνομένους, ὅτι συμμάχους ἐτόλμησαν καλεῖν οὓς ἔδει τιμωροὺς δεδιέναι·"},{"number":265,"text":"εἰ δὲ αἰδεῖσθε τὰς τῶν τοιούτων ἐπικλήσεις, ἀλλά τοι πάρεστι θεμένοις τὰ ὅπλα καὶ παρελθοῦσιν εἰς τὴν πόλιν σχήματι συγγενῶν ἀναλαβεῖν τὸ μέσον συμμάχων τε καὶ πολεμίων ὄνομα δικαστὰς γενομένους."},{"number":266,"text":"καίτοι λογίσασθε, πόσον κερδήσουσιν ἐφʼ ὁμολογουμένοις καὶ τηλικούτοις κρινόμενοι παρʼ ὑμῖν οἱ τοῖς ἀκαταιτιάτοις μηδὲ λόγου μεταδόντες· λαμβανέτωσαν δʼ οὖν ταύτην ἐκ τῆς ὑμετέρας ἀφίξεως τὴν χάριν."},{"number":267,"text":"εἰ δʼ οὔτε συναγανακτεῖν ἡμῖν οὔτε κρίνεσθαι δεῖ, τρίτον ἐστὶ καταλιπεῖν ἑκατέρους καὶ μήτε ταῖς ἡμετέραις ἐπιβαίνειν συμφοραῖς μήτε τοῖς ἐπιβούλοις τῆς μητροπόλεως συνέρχεσθαι."},{"number":268,"text":"εἰ γὰρ καὶ τὰ μάλιστα Ῥωμαίοις ὑποπτεύετε διειλέχθαι τινάς, παρατηρεῖν ἔξεστι τὰς ἐφόδους, κἄν τι τῶν διαβεβλημένων ἔργῳ διακαλύπτηται, τότε φρουρεῖν τὴν μητρόπολιν ἐλθόντας κολάζειν τε τοὺς αἰτίους πεφωραμένους· οὐ γὰρ ἂν ὑμᾶς φθάσειαν οἱ πολέμιοι τῇ πόλει προσῳκημένους."},{"number":269,"text":"εἰ δʼ οὐδὲν ὑμῖν τούτων εὔγνωμον ἢ μέτριον δοκεῖ, μὴ θαυμάζετε τὰ κλεῖθρα τῶν πυλῶν, ἕως ἂν φέρητε τὰ ὅπλα."},{"number":270,"text":"Τοιαῦτα μὲν ὁ Ἰησοῦς ἔλεγε· τῶν δὲ Ἰδουμαίων οὔτε τὸ πλῆθος προσεῖχεν, ἀλλὰ τεθύμωτο μὴ τυχὸν ἑτοίμης τῆς εἰσόδου, καὶ διηγανάκτουν οἱ στρατηγοὶ πρὸς ἀπόθεσιν τῶν ὅπλων αἰχμαλωσίαν ἡγούμενοι τὸ κελευόντων τινῶν αὐτὰ ῥῖψαι."},{"number":271,"text":"Σίμων δὲ υἱὸς Κααθὰ τῶν ἡγεμόνων εἷς, μόλις τῶν οἰκείων καταστείλας τὸν θόρυβον καὶ στὰς εἰς ἐπήκοον τοῖς ἀρχιερεῦσιν,"},{"number":272,"text":"οὐκέτι θαυμάζειν ἔφη φρουρουμένων ἐν τῷ ἱερῷ τῶν προμάχων τῆς ἐλευθερίας, εἴ γε καὶ τῷ ἔθνει κλείουσί τινες ἤδη τὴν κοινὴν πόλιν,"},{"number":273,"text":"καὶ Ῥωμαίους μὲν εἰσδέχεσθαι παρασκευάζονται τάχα καὶ στεφανώσαντες τὰς πύλας, Ἰδουμαίοις δὲ ἀπὸ τῶν πύργων διαλέγονται καὶ τὰ ὑπὲρ τῆς ἐλευθερίας ὅπλα κελεύουσι ῥῖψαι,"},{"number":274,"text":"μὴ πιστεύοντες δὲ τοῖς συγγενέσι τὴν τῆς μητροπόλεως φυλακὴν τοὺς αὐτοὺς δικαστὰς ποιοῦνται τῶν διαφόρων, καὶ κατηγοροῦντές τινων ὡς ἀποκτείνειαν ἀκρίτους, αὐτοὶ καταδικάζοιεν ὅλου τοῦ ἔθνους ἀτιμίαν·"},{"number":275,"text":"τὴν γοῦν ἅπασι τοῖς ἀλλοφύλοις ἀναπεπταμένην εἰς θρησκείαν πόλιν τοῖς οἰκείοις νῦν ἀποτετείχισθε."},{"number":276,"text":"πάνυ γὰρ ἐπὶ σφαγὰς ἐσπεύδομεν καὶ τὸν κατὰ τῶν ὁμοφύλων πόλεμον οἱ διὰ τοῦτο ταχύναντες, ἵνʼ ὑμᾶς τηρήσωμεν ἐλευθέρους."},{"number":277,"text":"τοιαῦτα μέντοι καὶ πρὸς τῶν φρουρουμένων ἠδίκησθε, καὶ πιθανὰς οὕτως ὑποψίας οἶμαι κατʼ ἐκείνων συνελέξατε."},{"number":278,"text":"ἔπειτα τῶν ἔνδον φρουρᾷ κρατοῦντες ὅσοι κήδονται τῶν κοινῶν πραγμάτων, καὶ τοῖς συγγενεστάτοις ἔθνεσιν ἀθρόοις ἀποκλείσαντες μὲν τὴν πόλιν ὑβριστικὰ δʼ οὕτως προστάγματα κελεύοντες, τυραννεῖσθαι λέγετε καὶ τὸ τῆς δυναστείας ὄνομα τοῖς ὑφʼ ὑμῶν τυραννουμένοις περιάπτετε."},{"number":279,"text":"τίς ἂν ἐνέγκαι τὴν εἰρωνείαν τῶν λόγων ἀφορῶν εἰς τὴν ἐναντιότητα τῶν πραγμάτων; εἰ μὴ καὶ νῦν ὑμᾶς ἀποκλείουσιν Ἰδουμαῖοι τῆς μητροπόλεως, οὓς αὐτοὶ τῶν πατρίων ἱερῶν εἴργετε."},{"number":280,"text":"μέμψαιτʼ ἂν εἰκότως τις τοὺς ἐν τῷ ἱερῷ πολιορκουμένους, ὅτι θαρσήσαντες τοὺς προδότας κολάζειν, οὓς ὑμεῖς ἄνδρας ἐπισήμους καὶ ἀκαταιτιάτους λέγετε διὰ τὴν κοινωνίαν, οὐκ ἀφʼ ὑμῶν ἤρξαντο καὶ τὰ καιριώτατα τῆς προδοσίας μέρη προαπέκοψαν."},{"number":281,"text":"ἀλλʼ εἰ κἀκεῖνοι τῆς χρείας ἐγένοντο μαλακώτεροι, τηρήσομεν Ἰδουμαῖοι τὸν οἶκον τοῦ θεοῦ καὶ τῆς κοινῆς πατρίδος προπολεμήσομεν ἅμα τούς τε ἔξωθεν ἐπιόντας καὶ τοὺς ἔνδον προδιδόντας ἀμυνόμενοι πολεμίους."},{"number":282,"text":"ἐνθάδε πρὸ τῶν τειχῶν μενοῦμεν ἐν τοῖς ὅπλοις, ἕως ἂν Ῥωμαῖοι κάμωσι προσέχοντες ὑμῖν ἢ ὑμεῖς ἐλεύθερα φρονήσαντες μεταβάλησθε.-->"},{"number":283,"text":"Τούτοις τὸ μὲν τῶν Ἰδουμαίων ἐπεβόα πλῆθος, ὁ δὲ Ἰησοῦς ἀθυμῶν ἀνεχώρει τοὺς μὲν Ἰδουμαίους μηδὲν φρονοῦντας ὁρῶν μέτριον, διχόθεν δὲ τὴν πόλιν πολεμουμένην."},{"number":284,"text":"ἦν δὲ οὐδὲ τοῖς Ἰδουμαίοις ἐν ἠρεμίᾳ τὰ φρονήματα· καὶ γὰρ τεθύμωντο πρὸς τὴν ὕβριν εἰρχθέντες τῆς πόλεως καὶ τὰ τῶν ζηλωτῶν ἰσχυρὰ δοκοῦντες ὡς οὐδὲν ἐπαμύνοντας ἑώρων, ἠποροῦντο καὶ μετενόουν πολλοὶ τὴν ἄφιξιν."},{"number":285,"text":"ἡ δὲ αἰδὼς τοῦ τέλεον ἀπράκτους ὑποστρέφειν ἐνίκα τὴν μεταμέλειαν, ὥστε μένειν αὐτόθι πρὸ τοῦ τείχους κακῶς αὐλιζομένους·"},{"number":286,"text":"διὰ γὰρ τῆς νυκτὸς ἀμήχανος ἐκρήγνυται χειμὼν ἄνεμοί τε βίαιοι σὺν ὄμβροις λαβροτάτοις καὶ συνεχεῖς ἀστραπαὶ βρονταί τε φρικώδεις καὶ μυκήματα σειομένης τῆς γῆς ἐξαίσια."},{"number":287,"text":"πρόδηλον δὲ ἦν ἐπʼ ἀνθρώπων ὀλέθρῳ τὸ κατάστημα τῶν ὅλων συγκεχυμένον, καὶ οὐχὶ μικροῦ τις ἂν εἰκάσαι συμπτώματος τὰ τέρατα."},{"number":288,"text":"Μία δὲ τοῖς Ἰδουμαίοις καὶ τοῖς ἐν τῇ πόλει παρέστη δόξα, τοῖς μὲν ὀργίζεσθαι τὸν θεὸν ἐπὶ τῇ στρατείᾳ καὶ οὐκ ἂν διαφυγεῖν ἐπενεγκόντας ὅπλα τῇ μητροπόλει, τοῖς δὲ περὶ τὸν Ἄνανον νενικηκέναι χωρὶς παρατάξεως καὶ τὸν θεὸν ὑπὲρ αὐτῶν στρατηγεῖν."},{"number":289,"text":"κακοὶ δʼ ἦσαν ἄρα τῶν μελλόντων στοχασταὶ καὶ κατεμαντεύοντο τῶν ἐχθρῶν ἃ τοῖς ἰδίοις αὐτῶν ἐπῄει παθεῖν."},{"number":290,"text":"οἱ μὲν γὰρ Ἰδουμαῖοι συσπειραθέντες τοῖς σώμασιν ἀλλήλους ἀντέθαλπον καὶ τοὺς θυρεοὺς ὑπὲρ κεφαλῆς συμφράξαντες ἧττον ἐκακοῦντο τοῖς ὑετοῖς,"},{"number":291,"text":"οἱ δὲ ζηλωταὶ μᾶλλον τοῦ καθʼ αὑτοὺς κινδύνου ὑπὲρ ἐκείνων ἐβασανίζοντο καὶ συνελθόντες ἐσκόπουν, εἴ τινα μηχανὴν αὐτοῖς ἀμύνης ἐπινοήσειαν."},{"number":292,"text":"τοῖς μὲν οὖν θερμοτέροις ἐδόκει μετὰ τῶν ὅπλων βιάζεσθαι τοὺς παραφυλάσσοντας, ἔπειτα δʼ εἰσπεσόντας εἰς μέσον τῆς πόλεως ἀναφανδὸν ἀνοίγειν τοῖς συμμάχοις τὰς πύλας·"},{"number":293,"text":"τούς τε γὰρ φύλακας εἴξειν πρὸς τὸ ἀδόκητον αὐτῶν τεταραγμένους ἄλλως τε καὶ τοὺς πλείονας [αὐτῶν] ὄντας ἀνόπλους καὶ πολέμων ἀπείρους, καὶ τῶν κατὰ τὴν πόλιν δυσσύνακτον ἔσεσθαι τὸ πλῆθος κατειλημένον ὑπὸ τοῦ χειμῶνος εἰς τὰς οἰκίας."},{"number":294,"text":"εἰ δὲ καί τις γένοιτο κίνδυνος, πρέπειν αὐτοῖς πᾶν ὁτιοῦν παθεῖν ἢ περιιδεῖν τοσοῦτον πλῆθος διʼ αὐτοὺς αἰσχρῶς ἀπολλύμενον."},{"number":295,"text":"οἱ δὲ συνετώτεροι βιάζεσθαι μὲν ἀπεγίνωσκον ὁρῶντες οὐ μόνον τὴν αὐτῶν φρουρὰν πληθύουσαν ἀλλὰ καὶ τὸ τῆς πόλεως τεῖχος διὰ τοὺς Ἰδουμαίους ἐπιμελῶς φυλασσόμενον,"},{"number":296,"text":"ᾤοντό τε πανταχοῦ τὸν Ἄνανον παρεῖναι καὶ κατὰ πᾶσαν ὥραν ἐπισκέπτεσθαι τὰς φυλακάς·"},{"number":297,"text":"ὃ δὴ ταῖς μὲν ἄλλαις νυξὶν οὕτως εἶχεν, ἀνείθη δὲ κατʼ ἐκείνην, οὐ κατὰ τὴν Ἀνάνου ῥᾳθυμίαν, ἀλλʼ ὡς αὐτὸς ἐκεῖνος ἀπόλοιτο καὶ τὸ πλῆθος τῶν φυλάκων στρατηγούσης τῆς εἱμαρμένης,"},{"number":298,"text":"ἣ δὴ καὶ τότε τῆς νυκτὸς προκοπτούσης καὶ τοῦ χειμῶνος ἐπακμάζοντος κοιμίζει μὲν τοὺς ἐπὶ τῇ στοᾷ φρουρούς, τοῖς δὲ ζηλωταῖς ἐπίνοιαν ἐμβάλλει τῶν ἱερῶν αἴροντας πριόνων ἐκτεμεῖν τοὺς μοχλοὺς τῶν πυλῶν."},{"number":299,"text":"συνήργησε δʼ αὐτοῖς πρὸς τὸ μὴ κατακουσθῆναι τὸν ψόφον ὅ τε τῶν ἀνέμων ἦχος καὶ τὸ τῶν βροντῶν ἐπάλληλον."},{"number":300,"text":"Διαλανθάνοντες δὲ ἐκ τοῦ ἱεροῦ παραγίνονται πρὸς τὸ τεῖχος καὶ τοῖς αὐτοῖς πρίοσι χρώμενοι τὴν κατὰ τοὺς Ἰδουμαίους ἀνοίγουσι πύλην."},{"number":301,"text":"τοῖς δὲ τὸ μὲν πρῶτον ἐμπίπτει ταραχὴ τοὺς περὶ τὸν Ἄνανον ἐπιχειρεῖν οἰηθεῖσι, καὶ πᾶς ἐπὶ τοῦ ξίφους ἔσχε τὴν δεξιὰν ὡς ἀμυνούμενος· ταχέως δὲ γνωρίζοντες τοὺς ἥκοντας εἰσῄεσαν."},{"number":302,"text":"εἰ μὲν οὖν ἐτράποντο περὶ τὴν πόλιν, οὐδὲν ἐκώλυσεν ἂν ἀπολωλέναι τὸν δῆμον αὔτανδρον· οὕτως εἶχον ὀργῆς· νῦν δὲ πρώτους τοὺς ζηλωτὰς σπεύδοντες τῆς φρουρᾶς ἐξελέσθαι, δεομένων πολλὰ καὶ τῶν εἰσδεξαμένων μὴ περιιδεῖν διʼ οὓς ἦλθον ἐν μέσοις τοῖς δεινοῖς μηδʼ αὐτοῖς χαλεπώτερον ἐπισεῖσαι τὸν κίνδυνον·"},{"number":303,"text":"τῶν μὲν γὰρ φρουρῶν ἁλόντων ῥᾴδιον αὐτοῖς εἶναι χωρεῖν ἐπὶ τὴν πόλιν, εἰ δʼ ἅπαξ ταύτην προκινήσειαν, οὐκ ἂν ἔτι ἐκείνων κρατῆσαι·"},{"number":304,"text":"πρὸς γὰρ τὴν αἴσθησιν συντάξεσθαι αὐτοὺς καὶ τὰς ἀνόδους ἀποφράξειν·"}],"5":[{"number":305,"text":"Συνεδόκει ταῦτα τοῖς Ἰδουμαίοις, καὶ διὰ τῆς πόλεως ἀνέβαινον πρὸς τὸ ἱερόν, μετέωροί τε οἱ ζηλωταὶ τὴν ἄφιξιν αὐτῶν ἐκαραδόκουν. καὶ παριόντων εἴσω καὶ αὐτοὶ θαρροῦντες προῄεσαν ἐκ τοῦ ἐνδοτέρου ἱεροῦ."},{"number":306,"text":"μιγέντες δὲ τοῖς Ἰδουμαίοις προσέβαλλον ταῖς φυλακαῖς, καὶ τινὰς μὲν τῶν προκοιτούντων ἀπέσφαξαν κοιμωμένους, πρὸς δὲ τὴν τῶν ἐγρηγορότων βοὴν διανέστη πᾶν τὸ πλῆθος καὶ μετʼ ἐκπλήξεως ἁρπάζοντες τὰ ὅπλα πρὸς τὴν ἄμυναν ἐχώρουν."},{"number":307,"text":"ἕως μὲν οὖν μόνους τοὺς ζηλωτὰς ἐπιχειρεῖν ὑπελάμβανον, ἐθάρρουν ὡς τῷ πλήθει περιεσόμενοι, κατιδόντες δὲ ἔξωθεν ἐπιχεομένους ἄλλους ᾔσθοντο τὴν εἰσβολὴν τῶν Ἰδουμαίων,"},{"number":308,"text":"καὶ τὸ μὲν πλέον αὐτῶν ἅμα ταῖς ψυχαῖς κατέβαλλε τὰ ὅπλα καὶ πρὸς οἰμωγαῖς ἦν, φραξάμενοι δὲ ὀλίγοι τῶν νέων γενναίως ἐδέχοντο τοὺς Ἰδουμαίους καὶ μέχρι πολλοῦ τὴν ἀργοτέραν πληθὺν ἔσκεπον."},{"number":309,"text":"οἱ δὲ κραυγῇ διεσήμαινον τοῖς κατὰ τὴν πόλιν τὰς συμφοράς, κἀκείνων ἀμῦναι μὲν οὐδεὶς ἐτόλμησεν, ὡς ἔμαθον εἰσπεπαικότας τοὺς Ἰδουμαίους, ἀργὰ δʼ ἀντεβόων καὶ ἀντωλοφύροντο, καὶ πολὺς κωκυτὸς γυναικῶν ἠγείρετο κινδυνεύοντος ἑκάστῃ τινὸς τῶν φυλάκων."},{"number":310,"text":"οἱ δὲ ζηλωταὶ τοῖς Ἰδουμαίοις συνεπηλάλαζον καὶ τὴν ἐκ πάντων βοὴν ὁ χειμὼν ἐποίει φοβερωτέραν. ἐφείδοντό τε οὐδενὸς Ἰδουμαῖοι φύσει τε ὠμότατοι φονεύειν ὄντες καὶ τῷ χειμῶνι κεκακωμένοι κατὰ τῶν ἀποκλεισάντων ἐχρῶντο τοῖς θυμοῖς·"},{"number":311,"text":"ἦσαν δʼ ὅμοιοι τοῖς ἱκετεύουσι καὶ τοῖς ἀμυνομένοις καὶ πολλοὺς τήν τε συγγένειαν ἀναμιμνήσκοντας καὶ δεομένους τοῦ κοινοῦ ἱεροῦ λαβεῖν αἰδῶ διήλαυνον τοῖς ξίφεσιν."},{"number":312,"text":"ἦν δὲ φυγῆς μὲν οὐδεὶς τόπος οὐδὲ σωτηρίας ἐλπίς, συνωθούμενοι δὲ περὶ ἀλλήλους κατεκόπτοντο, καὶ τὸ πλέον ἐκβιαζόμενοι. ὡς οὐκέτʼ ἦν ὑποχωρήσεως τόπος ἐπῄεσαν δὲ οἱ φονεύοντες, ὑπʼ ἀμηχανίας κατεκρήμνιζον ἑαυτοὺς εἰς τὴν πόλιν, οἰκτρότερον ἔμοιγε δοκεῖν οὗ διέφευγον ὀλέθρου τὸν αὐθαίρετον ὑπομένοντες."},{"number":313,"text":"ἐπεκλύσθη δὲ τὸ ἔξωθεν ἱερὸν πᾶν αἵματι, καὶ νεκροὺς ὀκτακισχιλίους πεντακοσίους ἡ ἡμέρα κατελάμβανεν."},{"number":314,"text":"Οὐκ ἐκορέσθησαν δὲ τούτοις οἱ θυμοὶ τῶν Ἰδουμαίων, ἀλλʼ ἐπὶ τὴν πόλιν τραπόμενοι πᾶσαν μὲν οἰκίαν διήρπαζον, ἔκτεινον δὲ τὸν περιτυχόντα."},{"number":315,"text":"καὶ τὸ μὲν ἄλλο πλῆθος αὐτοῖς ἐδόκει παρανάλωμα, τοὺς δὲ ἀρχιερεῖς ἀνεζήτουν, καὶ κατʼ ἐκείνων ἦν τοῖς πλείστοις ἡ φορά."},{"number":316,"text":"ταχέως δʼ ἁλόντες διεφθείροντο, καὶ τοῖς νεκροῖς αὐτῶν ἐπιστάντες τὸν μὲν Ἄνανον τῆς πρὸς τὸν δῆμον εὐνοίας."},{"number":317,"text":"τὸν δὲ Ἰησοῦν τῶν ἀπὸ τοῦ τείχους λόγων ἐπέσκωπτον. προῆλθον δὲ εἰς τοσοῦτον ἀσεβείας ὥστε καὶ ἀτάφους ῥῖψαι, καίτοι τοσαύτην Ἰουδαίων περὶ τὰς ταφὰς πρόνοιαν ποιουμένων, ὥστε καὶ τοὺς ἐκ καταδίκης ἀνεσταυρωμένους πρὸ δύντος ἡλίου καθελεῖν τε καὶ θάπτειν."},{"number":318,"text":"οὐκ ἂν ἁμάρτοιμι δʼ εἰπὼν ἁλώσεως ἄρξαι τῇ πόλει τὸν Ἀνάνου θάνατον, καὶ ἀπʼ ἐκείνης τῆς ἡμέρας ἀνατραπῆναι τὸ τεῖχος καὶ διαφθαρῆναι τὰ πράγματα Ἰουδαίοις, ἐν ᾗ τὸν ἀρχιερέα καὶ ἡγεμόνα τῆς ἰδίας σωτηρίας αὐτῶν ἐπὶ μέσης τῆς πόλεως εἶδον ἀπεσφαγμένον."},{"number":319,"text":"ἦν γὰρ δὴ τά τε ἄλλα σεμνὸς ἁνὴρ καὶ δικαιότατος. καὶ παρὰ τὸν ὄγκον τῆς τε εὐγενείας καὶ τῆς ἀξίας καὶ ἧς εἶχε τιμῆς ἠγαπηκὼς τὸ ἰσότιμον καὶ πρὸς τοὺς ταπεινοτάτους, φιλελεύθερός τε ἐκτόπως καὶ δημοκρατίας ἐραστής,"},{"number":320,"text":"πρό τε τῶν ἰδίων λυσιτελῶν τὸ κοινῇ συμφέρον ἀεὶ τιθέμενος καὶ περὶ παντὸς ποιούμενος τὴν εἰρήνην· ἄμαχα γὰρ ᾔδει τὰ Ῥωμαίων· προσκοπούμενος δʼ ὑπʼ ἀνάγκης καὶ τὰ κατὰ τὸν πόλεμον, ὅπως, εἰ μὴ διαλύσαιντο Ἰουδαῖοι, δεξιῶς διαφέροιντο."},{"number":321,"text":"καθόλου δʼ εἰπεῖν, ζῶντος Ἀνάνου πάντως ἂν διελύθησαν· δεινὸς γὰρ ἦν εἰπεῖν τε καὶ πεῖσαι τὸν δῆμον, ἤδη δὲ ἐχειροῦτο καὶ τοὺς ἐμποδίζοντας· ἢ πολεμοῦντες πλείστην ἂν τριβὴν Ῥωμαίοις παρέσχον ὑπὸ τοιούτῳ στρατηγῷ."},{"number":322,"text":"παρέζευκτο δʼ αὐτῷ καὶ ὁ Ἰησοῦς, αὐτοῦ μὲν λειπόμενος κατὰ σύγκρισιν, προύχων δὲ τῶν ἄλλων."},{"number":323,"text":"ἀλλʼ οἶμαι κατακρίνας ὁ θεὸς ὡς μεμιασμένης τῆς πόλεως ἀπώλειαν καὶ πυρὶ βουλόμενος ἐκκαθαρθῆναι τὰ ἅγια τοὺς ἀντεχομένους αὐτῶν καὶ φιλοστοργοῦντας περιέκοπτεν."},{"number":324,"text":"οἱ δὲ πρὸ ὀλίγου τὴν ἱερὰν ἐσθῆτα περικείμενοι καὶ τῆς κοσμικῆς θρησκείας κατάρχοντες προσκυνούμενοί τε τοῖς ἐκ τῆς οἰκουμένης παραβάλλουσιν εἰς τὴν πόλιν, ἐρριμμένοι γυμνοὶ βορὰ κυνῶν καὶ θηρίων ἐβλέποντο."},{"number":325,"text":"αὐτὴν ἐπʼ ἐκείνοις στενάξαι τοῖς ἀνδράσι δοκῶ τὴν ἀρετήν, ὀλοφυρομένην ὅτι τοσοῦτον ἥττητο τῆς κακίας. ἀλλὰ [γὰρ] τὸ μὲν Ἀνάνου καὶ Ἰησοῦ τέλος τοιοῦτον ἀπέβη."},{"number":326,"text":"Μετὰ δʼ ἐκείνους οἵ τε ζηλωταὶ καὶ τῶν Ἰδουμαίων τὸ πλῆθος τὸν λαὸν ὥσπερ ἀνοσίων ζῴων ἀγέλην ἐπιόντες ἔσφαζον."},{"number":327,"text":"καὶ τὸ μὲν εἰκαῖον ἐφʼ οὗ καταληφθείη τόπου διεφθείρετο, τοὺς δὲ εὐγενεῖς καὶ νέους συλλαμβάνοντες εἰς εἱρκτὴν κατέκλειον δεδεμένους, κατʼ ἐλπίδα τοῦ προσθήσεσθαί τινας αὐτοῖς τὴν ἀναίρεσιν ὑπερτιθέμενοι."},{"number":328,"text":"προσέσχε δʼ οὐδείς, ἀλλὰ πάντες τοῦ τάξασθαι μετὰ τῶν πονηρῶν κατὰ τῆς πατρίδος προείλοντο τὸν θάνατον."},{"number":329,"text":"δεινὰς δὲ τῆς ἀρνήσεως αἰκίας ὑπέμενον μαστιγούμενοί τε καὶ στρεβλούμενοι, μετὰ δὲ τὸ μηκέτʼ ἀρκεῖν τὸ σῶμα ταῖς βασάνοις μόλις ἠξιοῦντο τοῦ ξίφους."},{"number":330,"text":"οἱ συλληφθέντες δὲ μεθʼ ἡμέραν ἀνῃροῦντο νύκτωρ, καὶ τοὺς νεκροὺς ἐκφοροῦντες ἔρριπτον, ὡς ἑτέροις εἴη δεσμώταις τόπος."},{"number":331,"text":"ἦν δὲ τοσαύτη τοῦ δήμου κατάπληξις, ὡς μηδένα τολμῆσαι μήτε κλαίειν φανερῶς τὸν προσήκοντα νεκρὸν μήτε θάπτειν, ἀλλὰ λαθραῖα μὲν ἦν αὐτῶν κατακεκλεισμένων τὰ δάκρυα καὶ μετὰ περισκέψεως, μή τις ἐπακούσῃ τῶν ἐχθρῶν, ἔστενον·"},{"number":332,"text":"ἴσα γὰρ τοῖς πενθουμένοις ὁ πενθήσας εὐθὺς ἔπασχε· νύκτωρ δὲ κόνιν αἴροντες χεροῖν ὀλίγην ἐπερρίπτουν τοῖς σώμασι, καὶ μεθʼ ἡμέραν εἴ τις παράβολος."},{"number":333,"text":"μύριοι καὶ δισχίλιοι τῶν εὐγενῶν νέων οὕτως διεφθάρησαν."},{"number":334,"text":"Οἱ δὲ ἤδη διαμεμισηκότες τὸ φονεύειν ἀνέδην εἰρωνεύοντο δικαστήρια καὶ κρίσεις."},{"number":335,"text":"καὶ δή τινα τῶν ἐπιφανεστάτων ἀποκτείνειν προθέμενοι Ζαχαρίαν υἱὸν Βάρεις· παρώξυνε δὲ αὐτοὺς τὸ λίαν τἀνδρὸς μισοπόνηρον καὶ φιλελεύθερον, ἦν δὲ καὶ πλούσιος, ὥστε μὴ μόνον ἐλπίζειν τὴν ἁρπαγὴν τῆς οὐσίας, ἀλλὰ καὶ προσαποσκευάσεσθαι δυνατὸν ἄνθρωπον εἰς τὴν αὐτῶν κατάλυσιν·"},{"number":336,"text":"συγκαλοῦσι μὲν ἐξ ἐπιτάγματος ἑβδομήκοντα τῶν ἐν τέλει δημοτῶν εἰς τὸ ἱερόν, περιθέντες δʼ αὐτοῖς ὥσπερ ἐπὶ σκηνῆς σχῆμα δικαστῶν ἔρημον ἐξουσίας τοῦ Ζαχαρίου κατηγόρουν, ὡς ἐνδιδοίη τὰ πράγματα Ῥωμαίοις καὶ περὶ προδοσίας διαπέμψαιτο πρὸς Οὐεσπασιανόν."},{"number":337,"text":"ἦν δὲ οὔτʼ ἔλεγχός τις τῶν κατηγορουμένων οὔτε τεκμήριον, ἀλλʼ αὐτοὶ πεπεῖσθαι καλῶς ἔφασαν καὶ τοῦτʼ εἶναι πίστιν τῆς ἀληθείας ἠξίουν."},{"number":338,"text":"ὅ γε μὴν Ζαχαρίας συνιδὼν μηδεμίαν αὐτῷ καταλειπομένην σωτηρίας ἐλπίδα, κεκλῆσθαι γὰρ κατʼ ἐνέδραν εἰς εἱρκτήν, οὐκ ἐπὶ δικαστήριον, ἐποιήσατο τὴν τοῦ ζῆν ἀπόγνωσιν οὐκ ἀπαρρησίαστον, ἀλλὰ καταστὰς τὸ μὲν πιθανὸν τῶν κατηγορημένων διεχλεύασε καὶ διὰ βραχέων ἀπελύσατο τὰς ἐπιφερομένας αἰτίας."},{"number":339,"text":"ἔπειτα δὲ τὸν λόγον εἰς τοὺς κατηγόρους ἀποστρέψας ἑξῆς πάσας αὐτῶν διεξῄει τὰς παρανομίας καὶ πολλὰ περὶ τῆς συγχύσεως κατωλοφύρατο τῶν πραγμάτων."},{"number":340,"text":"οἱ ζηλωταὶ δʼ ἐθορύβουν καὶ μόλις τῶν ξιφῶν ἀπεκράτουν, τὸ σχῆμα καὶ τὴν εἰρωνείαν τοῦ δικαστηρίου μέχρι τέλους παῖξαι προαιρούμενοι, καὶ ἄλλως πειράσαι θέλοντες τοὺς δικαστάς, εἰ παρὰ τὸν αὐτῶν κίνδυνον μνησθήσονται τοῦ δικαίου."},{"number":341,"text":"φέρουσι δὲ οἱ ἑβδομήκοντα τῷ κρινομένῳ τὰς ψήφους ἅπαντες καὶ σὺν αὐτῷ προείλοντο τεθνάναι μᾶλλον ἢ τῆς ἀναιρέσεως αὐτοῦ λαβεῖν τὴν ἐπιγραφήν."},{"number":342,"text":"ἤρθη δὲ βοὴ τῶν ζηλωτῶν πρὸς τὴν ἀπόλυσιν, καὶ πάντων μὲν ἦν ἀγανάκτησις ἐπὶ τοῖς δικασταῖς ὡς μὴ συνιεῖσι τὴν εἰρωνείαν τῆς δοθείσης αὐτοῖς ἐξουσίας,"},{"number":343,"text":"δύο δὲ τολμηρότατοι προσπεσόντες ἐν μέσῳ τῷ ἱερῷ διαφθείρουσι τὸν Ζαχαρίαν καὶ πεσόντι ἐπιχλευάσαντες ἔφασαν καὶ παρʼ ἡμῶν τὴν ψῆφον ἔχεις καὶ βεβαιοτέραν ἀπόλυσιν ῥίπτουσί τε αὐτὸν [εὐθέως] ἀπὸ τοῦ ἱεροῦ κατὰ τῆς ὑποκειμένης φάραγγος."},{"number":344,"text":"τοὺς δὲ δικαστὰς πρὸς ὕβριν ἀπεστραμμένοις τοῖς ξίφεσι τύπτοντες ἐξέωσαν τοῦ περιβόλου, διʼ ἓν τοῦτο φεισάμενοι τῆς σφαγῆς αὐτῶν, ἵνα σκεδασθέντες ἀνὰ τὴν πόλιν ἄγγελοι πᾶσι τῆς δουλείας γένωνται."},{"number":345,"text":"Τοῖς δὲ Ἰδουμαίοις ἤδη τῆς παρουσίας μετέμελε καὶ προσίστατο τὰ πραττόμενα."},{"number":346,"text":"συναγαγὼν δὲ αὐτούς τις ἀπὸ τῶν ζηλωτῶν κατʼ ἰδίαν ἐλθὼν ἐνεδείκνυτο τὰ συμπαρανομηθέντα τοῖς καλέσασι καὶ τὸ κατὰ τῆς μητροπόλεως διεξῄει·"},{"number":347,"text":"παρατάσσεσθαι μὲν γὰρ ὡς ὑπὸ τῶν ἀρχιερέων προδιδομένης Ῥωμαίοις τῆς μητροπόλεως, εὑρηκέναι δὲ προδοσίας μὲν τεκμήριον οὐδέν, τοὺς δʼ ἐκείνην ὑποκρινομένους φυλάττεσθαι καὶ πολέμου καὶ τυραννίδος ἔργα τολμῶντας."},{"number":348,"text":"προσήκειν μὲν οὖν αὐτοῖς διακωλύειν ἀπʼ ἀρχῆς· ἐπειδὴ δὲ ἅπαξ εἰς κοινωνίαν ἐμφυλίου φόνου προέπεσον, ὅρον γοῦν ἐπιθεῖναι τοῖς ἁμαρτήμασι καὶ μὴ παραμένειν χορηγοῦντας ἰσχὺν τοῖς καταλύουσι τὰ πάτρια."},{"number":349,"text":"καὶ γὰρ εἴ τινες χαλεπαίνουσι τὸ κλεισθῆναι τὰς πύλας καὶ μὴ δοθῆναι μετὰ τῶν ὅπλων αὐτοῖς ἑτοίμην τὴν εἴσοδον, ἀλλὰ τοὺς εἴρξαντας τετιμωρῆσθαι· καὶ τεθνάναι μὲν Ἄνανον, διεφθάρθαι δὲ ἐπὶ μιᾶς νυκτὸς ὀλίγου δεῖν πάντα τὸν δῆμον·"},{"number":350,"text":"ἐφʼ οἷς τῶν μὲν οἰκείων πολλοὺς αἰσθάνεσθαι μετανοοῦντας, τῶν ἐπικαλεσαμένων δὲ ὁρᾶν ἄμετρον τὴν ὠμότητα μηδὲ διʼ οὓς ἐσώθησαν αἰδουμένων·"},{"number":351,"text":"ἐν ὄμμασι γοῦν τῶν συμμάχων τὰ αἴσχιστα τολμᾶν, καὶ τὰς ἐκείνων παρανομίας Ἰδουμαίοις προσάπτεσθαι, μέχρις ἂν μήτε κωλύῃ τις μήτε χωρίζηται τῶν δρωμένων."},{"number":352,"text":"δεῖν οὖν, ἐπειδὴ διαβολὴ μὲν πέφηνε τὰ τῆς προδοσίας, ἔφοδος δὲ Ῥωμαίων οὐδεμία προσδοκᾶται, δυναστεία δʼ ἐπιτετείχισται τῇ πόλει δυσκατάλυτος, αὐτοὺς ἀναχωρεῖν ἐπʼ οἴκου καὶ τῷ μὴ κοινωνεῖν τοῖς φαύλοις ἁπάντων ἀπολογήσασθαι πέρι, ὧν φενακισθέντες μετάσχοιεν."}],"6":[{"number":353,"text":"Τούτοις πεισθέντες οἱ Ἰδουμαῖοι πρῶτον μὲν λύουσι τοὺς ἐν τοῖς δεσμωτηρίοις περὶ δισχιλίους δημότας, οἳ παραχρῆμα φυγόντες ἐκ τῆς πόλεως ἀφικνοῦνται πρὸς Σίμωνα, περὶ οὗ μικρὸν ὕστερον ἐροῦμεν· ἔπειτα ἐκ τῶν Ἱεροσολύμων ἀνεχώρησαν ἐπʼ οἴκου."},{"number":354,"text":"καὶ συνέβη τὸν χωρισμὸν αὐτῶν γενέσθαι παράδοξον ἀμφοτέροις· ὅ τε γὰρ δῆμος ἀγνοῶν τὴν μετάνοιαν ἀνεθάρσησε πρὸς ὀλίγον ὡς ἐχθρῶν κεκουφισμένος,"},{"number":355,"text":"οἵ τε ζηλωταὶ μᾶλλον ἐπανέστησαν, οὐχ ὡς ὑπὸ συμμάχων καταλειφθέντες, ἀλλʼ ἀπηλλαγμένοι τῶν δυσωπούντων καὶ διατρεπόντων παρανομεῖν."},{"number":356,"text":"οὐκέτι γοῦν μέλλησις ἢ σκέψις ἦν τῶν ἀδικημάτων, ἀλλʼ ὀξυτάταις μὲν ἐχρῶντο ταῖς ἐπινοίαις εἰς ἕκαστα, τὰ δοχθέντα δὲ τάχιον καὶ τῆς ἐπινοίας ἐνήργουν."},{"number":357,"text":"μάλιστα δʼ ἐπʼ ἀνδρείαν τε καὶ εὐγένειαν ἐφόνων, τὴν μὲν φθόνῳ λυμαινόμενοι, τὸ δὲ γενναῖον δέει· μόνην γὰρ αὐτῶν ἀσφάλειαν ὑπελάμβανον τὸ μηδένα τῶν δυνατῶν καταλιπεῖν."},{"number":358,"text":"ἀνῃρέθη γοῦν σὺν πολλοῖς ἑτέροις καὶ Γουρίων, ἀξιώματι μὲν καὶ γένει προύχων, δημοκρατικὸς δὲ καὶ φρονήματος ἐλευθερίου μεστός, εἰ καί τις ἕτερος Ἰουδαίων· ἀπώλεσε δὲ αὐτὸν ἡ παρρησία μάλιστα πρὸς τοῖς ἄλλοις πλεονεκτήμασιν."},{"number":359,"text":"οὐδʼ ὁ Περαΐτης Νίγερ αὐτῶν τὰς χεῖρας διέφυγεν, ἀνὴρ ἄριστος ἐν τοῖς πρὸς Ῥωμαίους πολέμοις γενόμενος· ὃς καὶ βοῶν πολλάκις τάς τε ὠτειλὰς ἐπιδεικνὺς διὰ μέσης ἐσύρετο τῆς πόλεως."},{"number":360,"text":"ἐπεὶ δὲ ἔξω τῶν πυλῶν ἦκτο, τὴν σωτηρίαν ἀπογνοὺς περὶ ταφῆς ἱκέτευεν· οἱ δὲ προαπειλήσαντες ἧς ἐπεθύμει μάλιστα γῆς μὴ μεταδώσειν αὐτῷ, τὸν φόνον ἐνήργουν."},{"number":361,"text":"ἀναιρούμενος δὲ ὁ Νίγερ τιμωροὺς Ῥωμαίους αὐτοῖς ἐπηράσατο λιμόν τε καὶ λοιμὸν ἐπὶ τῷ πολέμῳ καὶ πρὸς ἅπασι τὰς ἀλλήλων χεῖρας·"},{"number":362,"text":"ἃ δὴ πάντα κατὰ τῶν ἀσεβῶν ἐκύρωσεν ὁ θεός, καὶ τὸ δικαιότατον, ὅτι γεύσασθαι τῆς ἀλλήλων ἀπονοίας ἔμελλον οὐκ εἰς μακρὰν στασιάσαντες."},{"number":363,"text":"Νίγερ μὲν οὖν ἀνῃρημένος τοὺς περὶ τῆς καταλύσεως αὐτῶν φόβους ἐπεκούφισε, τοῦ λαοῦ δὲ μέρος οὐδὲν ἦν, ᾧ μὴ πρὸς ἀπώλειαν ἐπενοεῖτο πρόφασις."},{"number":364,"text":"τὸ μὲν γὰρ αὐτῶν διενεχθέν τινι πάλαι διέφθαρτο, τὸ δὲ μὴ προσκροῦσαν κατʼ εἰρήνην ἐπικαίρους ἐλάμβανε τὰς αἰτίας· καὶ ὁ μὲν μηδʼ ὅλως αὐτοῖς προσιὼν ὡς ὑπερήφανος, ὁ προσιὼν δὲ μετὰ παρρησίας ὡς καταφρονῶν, ὁ θεραπεύων δʼ ὡς ἐπίβουλος ὑπωπτεύετο."},{"number":365,"text":"μία δὲ ἦν τῶν τε μεγίστων καὶ μετριωτάτων ἐγκλημάτων τιμωρία θάνατος· καὶ διέφυγεν οὐδείς, εἰ μὴ σφόδρα τις ἦν ταπεινὸς ἢ διʼ ἀγένειαν ἢ διὰ τύχην."},{"number":366,"text":"Ῥωμαίων δὲ οἱ μὲν ἄλλοι πάντες ἡγεμόνες ἕρμαιον ἡγούμενοι τὴν στάσιν τῶν πολεμίων ὥρμηντο πρὸς τὴν πόλιν καὶ τὸν Οὐεσπασιανὸν ἤπειγον ὡς ἂν ὄντα κύριον τῶν ὅλων, φάμενοι πρόνοιαν θεοῦ σύμμαχον σφίσι τῷ τετράφθαι τοὺς ἐχθροὺς κατʼ ἀλλήλων·"},{"number":367,"text":"εἶναι μέντοι τὴν ῥοπὴν ὀξεῖαν, καὶ ταχέως Ἰουδαίους ὁμονοήσειν [ἡμῖν] ἢ κοπιάσαντας ἐν τοῖς ἐμφυλίοις κακοῖς ἢ μετανοήσαντας."},{"number":368,"text":"Οὐεσπασιανὸς δὲ πλεῖστον αὐτοὺς ἔφη τοῦ δέοντος ἁμαρτάνειν, ὥσπερ ἐν θεάτρῳ χειρῶν τε καὶ ὅπλων ἐπίδειξιν ποιήσασθαι γλιχομένους οὐκ ἀκίνδυνον, ἀλλὰ μὴ τὸ συμφέρον καὶ τἀσφαλὲς σκοποῦντας."},{"number":369,"text":"εἰ μὲν γὰρ εὐθέως ὁρμήσειεν ἐπὶ τὴν πόλιν, αἴτιος ὁμονοίας ἔσεσθαι τοῖς πολεμίοις καὶ τὴν ἰσχὺν αὐτῶν ἀκμάζουσαν ἐφʼ ἑαυτὸν ἐπιστρέψειν· εἰ δὲ περιμείνειεν, ὀλιγωτέροις χρήσεσθαι δαπανηθεῖσιν ἐν τῇ στάσει."},{"number":370,"text":"στρατηγεῖν μὲν γὰρ ἄμεινον αὐτοῦ τὸν θεὸν ἀπονητὶ Ῥωμαίοις παραδιδόντα Ἰουδαίους καὶ τὴν νίκην ἀκινδύνως τῇ στρατιᾷ χαριζόμενον·"},{"number":371,"text":"ὥστε χρῆναι διαφθειρομένων χερσὶν οἰκείαις τῶν ἐχθρῶν καὶ τῷ μεγίστῳ κακῷ στάσει χρωμένων θεατὰς μᾶλλον αὐτοὺς ἀποκαθῆσθαι τῶν κινδύνων ἢ θανατῶσιν ἀνθρώποις καὶ λελυσσηκόσιν κατʼ ἀλλήλων χεῖρα μίσγειν."},{"number":372,"text":"εἰ δέ τις οἴεται τὴν δόξαν τῆς νίκης ἑωλοτέραν ἔσεσθαι δίχα μάχης, γνώτω τοῦ διὰ τῶν ὅπλων σφαλεροῦ τὸ μετὰ ἡσυχίας κατόρθωμα λυσιτελέστερον·"},{"number":373,"text":"καὶ γὰρ οὐχ ἧττον εὐκλεεῖς οἴεσθαι χρὴ τῶν κατὰ χεῖρα λαμπρῶν τοὺς ἐγκρατείᾳ καὶ συνέσει τὰ ἴσα πράξαντας. ἅμα μέντοι μειουμένων τῶν πολεμίων καὶ τὴν αὑτοῦ στρατιὰν ἀναληφθεῖσαν ἐκ τῶν συνεχῶν πόνων ἐρρωμενέστερον ἄξειν."},{"number":374,"text":"ἄλλως τε καὶ τῶν στοχαζομένων τῆς περὶ τὴν νίκην λαμπρότητος οὐ τοῦτον εἶναι τὸν καιρόν·"},{"number":375,"text":"οὐ γὰρ περὶ κατασκευὴν ὅπλων ἢ τειχῶν οὐδὲ περὶ συλλογὴν ἐπικούρων Ἰουδαίους ἀσχολεῖσθαι, καὶ τὴν ὑπέρθεσιν ἔσεσθαι κατὰ τῶν διδόντων, ἀλλʼ ἐμφυλίῳ πολέμῳ καὶ διχονοίᾳ τραχηλιζομένους καθʼ ἡμέραν οἰκτρότερα πάσχειν ὧν ἂν ἐπελθόντες αὐτοὶ διαθεῖεν αὐτοὺς ἁλόντας."},{"number":376,"text":"εἴτʼ οὖν τἀσφαλές τις σκοποίη, χρῆναι τοὺς ὑφʼ ἑαυτῶν ἀναλισκομένους ἐᾶν, εἴτε τὸ εὐκλεέστερον τοῦ κατορθώματος, οὐ δεῖν τοῖς οἴκοι νοσοῦσιν ἐπιχειρεῖν· ῥηθήσεσθαι γὰρ εὐλόγως οὐκ αὐτῶν τὴν νίκην ἀλλὰ τῆς στάσεως."},{"number":377,"text":"Ταῦτα Οὐεσπασιανῷ λέγοντι συνῄνουν οἱ ἡγεμόνες, καὶ παραχρῆμα τὸ στρατηγικὸν τῆς γνώμης ἀνεφαίνετο· πολλοὶ γοῦν καθʼ ἡμέραν ηὐτομόλουν τοὺς ζηλωτὰς διαδιδράσκοντες."},{"number":378,"text":"χαλεπὴ δʼ ἦν ἡ φυγὴ φρουραῖς διειληφότων τὰς διεξόδους πάσας καὶ τὸν ὁπωσοῦν ἐν αὐταῖς ἁλισκόμενον ὡς πρὸς Ῥωμαίους ἀπιόντα διαχρωμένων."},{"number":379,"text":"ὅ γε μὴν χρήματα δοὺς ἐξηφίετο καὶ μόνος ἦν ὁ μὴ διδοὺς προδότης, ὥστε κατελείπετο τῶν εὐπόρων τὴν φυγὴν ὠνουμένων μόνους ἐναποσφάττεσθαι τοὺς πένητας."},{"number":380,"text":"νεκροὶ δὲ κατὰ τὰς λεωφόρους πάσας ἐσωρεύοντο παμπληθεῖς, καὶ πολλοὶ τῶν ὁρμωμένων αὐτομολεῖν πάλιν τὴν ἔνδον ἀπώλειαν ᾑροῦντο· τὸν γὰρ ἐπὶ τῆς πατρίδος θάνατον ἐλπὶς ταφῆς ἐποίει δοκεῖν μετριώτερον."},{"number":381,"text":"οἱ δὲ εἰς τοσοῦτον ὠμότητος ἐξώκειλαν, ὡς μήτε τοῖς ἔνδον ἀναιρουμένοις μήτε τοῖς ἀνὰ τὰς ὁδοὺς μεταδοῦναι γῆς,"},{"number":382,"text":"ἀλλὰ καθάπερ συνθήκας πεποιημένοι τοῖς τῆς πατρίδος συγκαταλῦσαι καὶ τοὺς τῆς φύσεως νόμους ἅμα τε τοῖς εἰς ἀνθρώπους ἀδικήμασιν συμμιᾶναι καὶ τὸ θεῖον, ὑφʼ ἡλίῳ τοὺς νεκροὺς μυδῶντας ἀπέλειπον."},{"number":383,"text":"τοῖς δὲ θάπτουσί τινα τῶν προσηκόντων ὃ καὶ τοῖς αὐτομολοῦσιν ἐπιτίμιον θάνατος ἦν, καὶ δεῖσθαι παραχρῆμα ταφῆς ἔδει τὸν ἑτέρῳ χαριζόμενον."},{"number":384,"text":"καθόλου τε εἰπεῖν, οὐδὲν οὕτως ἀπολώλει χρηστὸν πάθος ἐν ταῖς τότε συμφοραῖς ὡς ἔλεος· ἃ γὰρ ἐχρῆν οἰκτείρειν, ταῦτα παρώξυνε τοὺς ἀλιτηρίους, καὶ ἀπὸ μὲν τῶν ζώντων ἐπὶ τοὺς ἀνῃρημένους, ἀπὸ δὲ τῶν νεκρῶν ἐπὶ τοὺς ζῶντας τὰς ὀργὰς μετέφερον·"},{"number":385,"text":"καὶ διʼ ὑπερβολὴν δέους ὁ περιὼν τοὺς προληφθέντας ὡς ἀναπαυσαμένους ἐμακάριζεν οἵ τε ἐν τοῖς δεσμωτηρίοις αἰκιζόμενοι κατὰ σύγκρισιν καὶ τοὺς ἀτάφους ἀπέφαινον εὐδαίμονας."},{"number":386,"text":"κατεπατεῖτο μὲν οὖν πᾶς αὐτοῖς θεσμὸς ἀνθρώπων, ἐγελᾶτο δὲ τὰ θεῖα, καὶ τοὺς τῶν προφητῶν χρησμοὺς ὥσπερ ἀγυρτικὰς λογοποιίας ἐχλεύαζον."},{"number":387,"text":"πολλὰ δʼ οὗτοι περὶ ἀρετῆς καὶ κακίας προεθέσπισαν, ἃ παραβάντες οἱ ζηλωταὶ καὶ τὴν κατὰ τῆς πατρίδος προφητείαν τέλους ἠξίωσαν."},{"number":388,"text":"ἦν γὰρ δή τις παλαιὸς λόγος ἀνδρῶν † ἔνθα τότε τὴν πόλιν ἁλώσεσθαι καὶ καταφλέξεσθαι τὸ ἁγιώτατον νόμῳ πολέμου, στάσις ἐὰν κατασκήψῃ καὶ χεῖρες οἰκεῖαι προμιάνωσι τὸ τοῦ θεοῦ τέμενος· οἷς οὐκ ἀπιστήσαντες οἱ ζηλωταὶ διακόνους αὑτοὺς ἐπέδοσαν."}],"7":[{"number":389,"text":"Ἤδη δὲ Ἰωάννῃ τυραννιῶντι τὸ πρὸς τοὺς ὁμοίους ἰσότιμον ἠδοξεῖτο, καὶ κατʼ ὀλίγους προσποιούμενος τῶν πονηροτέρων ἀφηνίαζε τοῦ συντάγματος."},{"number":390,"text":"ἀεὶ δὲ τοῖς μὲν τῶν ἄλλων δόγμασιν ἀπειθῶν, τὰ δὲ αὑτοῦ προστάσσων δεσποτικώτερον, δῆλος ἦν μοναρχίας ἀντιποιούμενος."},{"number":391,"text":"εἶκον δʼ αὐτῷ τινὲς μὲν δέει, τινὲς δὲ κατʼ εὔνοιαν, δεινὸς γὰρ ἦν ἀπάτῃ καὶ λόγῳ προσαγαγέσθαι, πολλοὶ δὲ πρὸς ἀσφαλείας ἡγούμενοι τῆς αὑτῶν τὰς αἰτίας ἤδη τῶν τολμωμένων ἐφʼ ἕνα καὶ μὴ πολλοὺς ἀναφέρεσθαι."},{"number":392,"text":"τό γε μὴν δραστήριον αὐτοῦ κατά τε χεῖρα καὶ κατὰ γνώμην δορυφόρους εἶχεν οὐκ ὀλίγους."},{"number":393,"text":"πολλὴ δὲ μοῖρα τῶν ἀντικαθισταμένων ἀπελείπετο, παρʼ οἷς ἴσχυε μὲν καὶ φθόνος δεινὸν ἡγουμένων ὑποτετάχθαι τὸ πρὶν ἰσοτίμῳ, τὸ πλέον δʼ εὐλάβεια τῆς μοναρχίας ἀπέτρεπεν·"},{"number":394,"text":"οὔτε γὰρ καταλύσειν ῥᾳδίως ἤλπιζον αὐτὸν ἅπαξ κρατήσαντα, καὶ καθʼ αὑτῶν πρόφασιν ἕξειν τὸ τὴν ἀρχὴν ἀντιπρᾶξαι· προῃρεῖτο δʼ οὖν πολεμῶν ἕκαστος ὁτιοῦν παθεῖν ἢ δουλεύσας ἑκουσίως ἐν ἀνδραπόδου μοίρᾳ παραπολέσθαι."},{"number":395,"text":"διαιρεῖται μὲν οὖν ἡ στάσις ἐκ τούτων, καὶ τοῖς ἐναντιωθεῖσιν Ἰωάννης ἀντεβασίλευσεν."},{"number":396,"text":"ἀλλὰ τὰ μὲν πρὸς ἀλλήλους αὐτοῖς διὰ φυλακῆς ἦν, καὶ οὐδὲν ἢ μικρὸν εἴ ποτε διηκροβολίζοντο τοῖς ὅπλοις, ἤριζον δὲ κατὰ τοῦ δήμου καὶ πότεροι πλείονα λείαν ἄξουσιν ἀντεφιλονείκουν."},{"number":397,"text":"ἐπεὶ δὲ ἡ πόλις τρισὶ τοῖς μεγίστοις κακοῖς ἐχειμάζετο, πολέμῳ καὶ τυραννίδι καὶ στάσει, κατὰ σύγκρισιν μετριώτερον ἦν τοῖς δημοτικοῖς ὁ πόλεμος· ἀμέλει διαδιδράσκοντες ἐκ τῶν οἰκείων ἔφευγον πρὸς τοὺς ἀλλοφύλους καὶ παρὰ Ῥωμαίοις ἧς ἀπήλπισαν ἐν τοῖς ἰδίοις σωτηρίας ἠξιοῦντο."},{"number":398,"text":"Τέταρτον δὲ ἄλλο κακὸν ἐκινεῖτο πρὸς τὴν τοῦ ἔθνους κατάλυσιν."},{"number":399,"text":"φρούριον ἦν οὐ πόρρω Ἱεροσολύμων καρτερώτατον, ὑπὸ τῶν ἀρχαίων βασιλέων εἴς τε ὑπέκθεσιν κτήσεως ἐν πολέμου ῥοπαῖς καὶ σωμάτων ἀσφάλειαν κατεσκευασμένον, ὃ ἐκαλεῖτο Μασάδα."},{"number":400,"text":"τοῦτο κατειληφότες οἱ προσαγορευόμενοι σικάριοι τέως μὲν τὰς πλησίον χώρας κατέτρεχον οὐδὲν πλέον τῶν ἐπιτηδείων ποριζόμενοι·"},{"number":401,"text":"δέει γὰρ ἀνεστέλλοντο τῆς πλείονος ἁρπαγῆς· ὡς [δὲ] τὴν Ῥωμαίων στρατιὰν ἠρεμοῦσαν, στάσει δὲ καὶ τυραννίδι ἰδίᾳ τοὺς ἐν Ἱεροσολύμοις Ἰουδαίους ἐπύθοντο διῃρημένους, ἁδροτέρων ἥπτοντο τολμημάτων."},{"number":402,"text":"καὶ κατὰ τὴν ἑορτὴν τῶν ἀζύμων, ἣν ἄγουσιν Ἰουδαῖοι σωτήρια ἐξ οὗ τῆς ὑπʼ Αἰγυπτίοις δουλείας ἀνεθέντες εἰς τὴν πάτριον γῆν κατῆλθον, νύκτωρ τοὺς ἐμποδὼν ὄντας διαλαθόντες πολίχνην τινὰ κατατρέχουσιν καλουμένην Ἐνγαδδί,"},{"number":403,"text":"ἐν ᾗ τὸ μὲν ἀμύνεσθαι δυνάμενον πρὶν ὅπλων ἅψασθαι καὶ συνελθεῖν φθάσαντες ἐσκέδασαν καὶ τῆς πόλεως ἐξέβαλον, τὸ δὲ φυγεῖν ἧττον ὄν, γύναιά τε καὶ παῖδας, ὑπὲρ ἑπτακοσίους ἀναιροῦσιν."},{"number":404,"text":"ἔπειτα τούς τε οἴκους ἐξεσκευασμένοι καὶ τῶν καρπῶν τοὺς ἀκμαιοτάτους ἁρπάσαντες ἀνήνεγκαν εἰς τὴν Μασάδαν."},{"number":405,"text":"καὶ οἱ μὲν ἐλῄζοντο πάσας τὰς περὶ τὸ φρούριον κώμας καὶ τὴν χώραν ἐπόρθουν ἅπασαν προσδιαφθειρομένων αὐτοῖς καθʼ ἡμέραν ἑκασταχόθεν οὐκ ὀλίγων·"},{"number":406,"text":"ἐκινεῖτο δὲ καὶ κατὰ τὰ ἄλλα τῆς Ἰουδαίας κλίματα τὸ τέως ἠρεμοῦν τὸ λῃστρικόν, καθάπερ δὲ ἐν σώματι τοῦ κυριωτάτου φλεγμαίνοντος πάντα τὰ μέλη συνενόσει·"},{"number":407,"text":"διὰ γοῦν τὴν ἐν τῇ μητροπόλει στάσιν καὶ ταραχὴν ἄδειαν ἔσχον οἱ κατὰ τὴν χώραν πονηροὶ τῶν ἁρπαγῶν καὶ τὰς οἰκείας ἕκαστος κώμας ἁρπάζοντες ἔπειτα εἰς τὴν ἐρημίαν ἀφίσταντο."},{"number":408,"text":"συναθροιζόμενοί τε καὶ συνομνύμενοι κατὰ λόχους στρατιᾶς μὲν ὀλιγώτεροι πλείους δὲ λῃστηρίου προσέπιπτον ἱεροῖς καὶ πόλεσιν,"},{"number":409,"text":"καὶ κακοῦσθαι μὲν συνέβαινεν ἐφʼ οὓς ὁρμήσειαν ὡς ἐν πολέμῳ καταληφθέντας, φθάνεσθαι δὲ τὰς ἀμύνας ὡς λῃστῶν ἅμα ταῖς ἁρπαγαῖς ἀποδιδρασκόντων. οὐδὲν δὲ μέρος ἦν τῆς Ἰουδαίας, ὃ μὴ τῇ προανεχούσῃ πόλει συναπώλλυτο."},{"number":410,"text":"Ταῦτα Οὐεσπασιανῷ παρὰ τῶν αὐτομόλων διηγγέλλετο. καίπερ γὰρ φρουρούντων τὰς ἐξόδους τῶν στασιαστῶν ἁπάσας καὶ διαφθειρόντων τοὺς ὁπωσοῦν προσιόντας, ὅμως ἦσαν οἳ διελάνθανον καὶ καταφεύγοντες εἰς τοὺς Ῥωμαίους τὸν στρατηγὸν ἐνῆγον ἀμῦναι τῇ πόλει καὶ τὰ τοῦ δήμου περισῶσαι λείψανα·"},{"number":411,"text":"διὰ γὰρ τὴν πρὸς Ῥωμαίους εὔνοιαν ἀνῃρῆσθαί τε τοὺς πολλοὺς καὶ κινδυνεύειν τοὺς περιόντας."},{"number":412,"text":"ὁ δὲ οἰκτείρων ἤδη τὰς συμφορὰς αὐτῶν τὸ μὲν δοκεῖν ἐκπολιορκήσων ἐφίσταται τὰ Ἱεροσόλυμα, τὸ δὲ ἀληθὲς ἀπαλλάξων πολιορκίας."},{"number":413,"text":"ἔδει μὲν προκαταστρέψασθαι τὰ λειπόμενα καὶ μηδὲν ἔξωθεν ἐμπόδιον τῇ πολιορκίᾳ καταλιπεῖν· ἐλθὼν οὖν ἐπὶ τὰ Γάδαρα μητρόπολιν τῆς Περαίας καρτερὰν τετράδι Δύστρου μηνὸς εἴσεισιν εἰς τὴν πόλιν·"},{"number":414,"text":"καὶ γὰρ ἔτυχον οἱ δυνατοὶ λάθρα τῶν στασιωδῶν πρεσβευσάμενοι πρὸς αὐτὸν περὶ παραδόσεως πόθῳ τε εἰρήνης καὶ διὰ τὰς οὐσίας· πολλοὶ δὲ τὰ Γάδαρα κατῴκουν πλούσιοι."},{"number":415,"text":"τούτων τὴν πρεσβείαν ἠγνοήκεσαν οἱ διάφοροι, πλησίον δὲ ἤδη ὄντος Οὐεσπασιανοῦ διεπύθοντο, καὶ κατασχεῖν μὲν αὐτοὶ τὴν πόλιν ἀπέγνωσαν δύνασθαι τῶν τε ἔνδον ἐχθρῶν πλήθει λειπόμενοι καὶ Ῥωμαίους ὁρῶντες οὐ μακρὰν τῆς πόλεως, φεύγειν δὲ κρίνοντες ἠδόξουν ἀναιμωτὶ καὶ μηδεμίαν παρὰ τῶν αἰτίων εἰσπραξάμενοι τιμωρίαν."},{"number":416,"text":"συλλαβόντες δὴ τὸν Δόλεσον, οὗτος γὰρ ἦν οὐ μόνον ἀξιώματι καὶ γένει τῆς πόλεως πρῶτος, ἀλλʼ ἐδόκει καὶ τῆς πρεσβείας αἴτιος, κτείνουσί τε αὐτὸν καὶ διʼ ὑπερβολὴν ὀργῆς νεκρὸν αἰκισάμενοι διέδρασαν ἐκ τῆς πόλεως."},{"number":417,"text":"ἐπιούσης δὲ ἤδη τῆς Ῥωμαϊκῆς δυνάμεως ὅ τε δῆμος τῶν Γαδαρέων μετʼ εὐφημίας τὸν Οὐεσπασιανὸν εἰσδεξάμενοι δεξιὰς παρʼ αὐτοῦ πίστεως ἔλαβον καὶ φρουρὰν ἱππέων τε καὶ πεζῶν πρὸς τὰς τῶν φυγάδων καταδρομάς·"},{"number":418,"text":"τὸ γὰρ τεῖχος αὐτοὶ πρὶν ἀξιῶσαι Ῥωμαίους καθεῖλον, ὅπως εἴη πίστις αὐτοῖς τοῦ τὴν εἰρήνην ἀγαπᾶν τὸ μηδὲ βουληθέντας δύνασθαι πολεμεῖν."},{"number":419,"text":"Οὐεσπασιανὸς δὲ ἐπὶ μὲν τοὺς διαδράντας ἐκ τῶν Γαδάρων Πλάκιδον σὺν ἱππεῦσιν πεντακοσίοις καὶ πεζοῖς τρισχιλίοις πέμπει, αὐτὸς δὲ μετὰ τῆς ἄλλης στρατιᾶς ὑπέστρεψεν εἰς Καισάρειαν."},{"number":420,"text":"οἱ δὲ φυγάδες ὡς αἰφνίδιον τοὺς διώκοντας ἱππεῖς ἐθεάσαντο, πρὶν εἰς χεῖρας ἐλθεῖν εἴς τινα κώμην συνειλοῦνται Βηθενναβρὶν προσαγορευομένην·"},{"number":421,"text":"ἐν ᾗ νέων πλῆθος οὐκ ὀλίγον εὑρόντες καὶ τοὺς μὲν ἑκόντας τοὺς δὲ βίᾳ καθοπλίσαντες εἰκαίως, προπηδῶσιν ἐπὶ τοὺς περὶ τὸν Πλάκιδον."},{"number":422,"text":"οἱ δὲ πρὸς μὲν τὴν πρώτην ἐμβολὴν ὀλίγον εἶξαν ἅμα καὶ προκαλέσασθαι τεχνιτεύοντες αὐτοὺς ἀπὸ τοῦ τείχους πορρωτέρω,"},{"number":423,"text":"λαβόντες δʼ εἰς ἐπιτήδειον περιήλαυνόν τε καὶ κατηκόντιζον, καὶ τοὺς μὲν φυγάδας αὐτῶν οἱ ἱππεῖς ὑπετέμνοντο, τὰς συμπλοκὰς δὲ τὸ πεζὸν εὐτόνως διέφθειρον."},{"number":424,"text":"οὐ μέντοι πλέον τι τόλμης ἐπιδεικνύμενοι Ἰουδαῖοι διεφθείροντο· πεπυκνωμένοις γὰρ τοῖς Ῥωμαίοις προσπίπτοντες καὶ ταῖς πανοπλίαις ὥσπερ τετειχισμένοις, αὐτοὶ μὲν οὐχ εὕρισκον βέλους παράδυσιν οὐδʼ ηὐτόνουν ῥῆξαι τὴν φάλαγγα,"},{"number":425,"text":"περιεπείροντο δὲ τοῖς ἐκείνων βέλεσι καὶ τοῖς ἀγριωτάτοις παραπλήσιοι θηρίοις ὥρμων ἐπὶ τὸν σίδηρον, διεφθείροντο δʼ οἱ μὲν κατὰ στόμα παιόμενοι τοῖς ξίφεσιν, οἱ δὲ ὑπὸ τῶν ἱππέων σκεδαννύμενοι."},{"number":426,"text":"Σπουδὴ γὰρ ἦν τῷ Πλακίδῳ τὰς ἐπὶ τὴν κώμην ὁρμὰς αὐτῶν διακλείειν."},{"number":427,"text":"καὶ συνεχῶς παρελαύνων κατʼ ἐκεῖνο τὸ μέρος, ἔπειτα ἐπιστρέφων ἅμα καὶ τοῖς βέλεσι χρώμενος εὐστόχως ἀνῄρει τοὺς πλησιάζοντας καὶ δέει τοὺς πόρρωθεν ἀνέστρεφεν, μέχρι βίᾳ διεκπεσόντες οἱ γενναιότατοι πρὸς τὸ τεῖχος διέφευγον."},{"number":428,"text":"ἀπορία δʼ εἶχε τοὺς φύλακας· οὔτε γὰρ ἀποκλεῖσαι τοὺς ἀπὸ τῶν Γαδάρων ὑπέμενον διὰ τοὺς σφετέρους καὶ δεξάμενοι συναπολεῖσθαι προσεδόκων."},{"number":429,"text":"ὃ δὴ καὶ συνέβη· συνωσθέντων γὰρ αὐτῶν εἰς τὸ τεῖχος παρʼ ὀλίγον μὲν οἱ τῶν Ῥωμαίων ἱππεῖς συνεισέπεσον, οὐ μὴν ἀλλὰ καὶ φθασάντων ἀποκλεῖσαι τὰς πύλας προσβαλὼν ὁ Πλάκιδος καὶ μέχρι δείλης γενναίως ἀγωνισάμενος τοῦ τείχους καὶ τῶν ἐν τῇ κώμῃ ἐκράτει."},{"number":430,"text":"τὰ μὲν οὖν ἀργὰ πλήθη διεφθείρετο, φυγὴ δὲ ἦν τῶν δυνατωτέρων, τὰς δʼ οἰκίας οἱ στρατιῶται διήρπασαν καὶ τὴν κώμην ἐνέπρησαν."},{"number":431,"text":"οἱ δὲ διαδράντες ἐξ αὐτῆς τοὺς κατὰ τὴν χώραν συνανέστησαν, καὶ τὰς μὲν αὐτῶν συμφορὰς ἐξαίροντες ἐπὶ μεῖζον, τῶν δὲ Ῥωμαίων τὴν στρατιὰν πᾶσαν ἐπιέναι λέγοντες πάντας πανταχόθεν ἐξέσεισαν τῷ δέει, γενόμενοί τε παμπληθεῖς ἔφευγον ἐπὶ Ἱεριχοῦντος·"},{"number":432,"text":"αὕτη γὰρ ἔτι μόνη τὰς ἐλπίδας αὐτῶν ἔθαλπε τῆς σωτηρίας καρτερὰ πλήθει γε οἰκητόρων."},{"number":433,"text":"Πλάκιδος δὲ τοῖς ἱππεῦσι καὶ ταῖς προαγούσαις εὐπραγίαις τεθαρρηκὼς εἵπετο, καὶ μέχρι μὲν Ἰορδάνου τοὺς ἀεὶ καταλαμβανομένους ἀνῄρει, συνελάσας δὲ πρὸς τὸν ποταμὸν πᾶν τὸ πλῆθος εἰργομένους ὑπὸ τοῦ ῥεύματος, τραφὲν γὰρ ὑπʼ ὄμβρων ἄβατον ἦν, ἀντικρὺ παρετάσσετο."},{"number":434,"text":"παρώξυνε δʼ ἡ ἀνάγκη πρὸς μάχην τοὺς φυγῆς τόπον οὐκ ἔχοντας, καὶ ταῖς ὄχθαις ἐπὶ μήκιστον παρεκτείναντες σφᾶς αὐτοὺς ἐδέχοντο τὰ βέλη καὶ τὰς τῶν ἱππέων ἐμβολάς, οἳ πολλοὺς αὐτῶν παίοντες εἰς τὸ ῥεῦμα κατέβαλον."},{"number":435,"text":"καὶ τὸ μὲν ἐν χερσὶν αὐτῶν διαφθαρὲν μύριοι πεντακισχίλιοι, τὸ δὲ βιασθὲν ἐμπηδῆσαι εἰς τὸν Ἰορδάνην πλῆθος ἑκουσίως ἄπειρον ἦν."},{"number":436,"text":"ἑάλωσαν δὲ περὶ δισχιλίους καὶ διακοσίους λεία τε παμπληθὴς ὄνων τε καὶ προβάτων καὶ καμήλων καὶ βοῶν."},{"number":437,"text":"Ἰουδαίοις μὲν οὖν οὐδὲν ἐλάττων ἥδε ἡ πληγὴ προσπεσοῦσα καὶ μείζων ἔδοξεν ἑαυτῆς διὰ τὸ μὴ μόνον τὴν χώραν ἅπασαν διʼ ἧς ἔφευγον πληρωθῆναι φόνου μηδὲ νεκροῖς διαβατὸν γενέσθαι τὸν Ἰορδάνην, ἐμπλησθῆναι δὲ τῶν σωμάτων καὶ τὴν Ἀσφαλτικὴν λίμνην, εἰς ἣν παμπληθεῖς ὑπὸ τοῦ ποταμοῦ κατεσύρησαν."},{"number":438,"text":"Πλάκιδος δὲ δεξιᾷ τύχῃ χρώμενος ὥρμησεν ἐπὶ τὰς πέριξ πολίχνας τε καὶ κώμας, καταλαμβανόμενός τε Ἄβιλα καὶ Ἰουλιάδα καὶ Βησιμὼ τάς τε μέχρι [τῆς] Ἀσφαλτίτιδος πάσας ἐγκαθίστησιν ἑκάστῃ τοὺς ἐπιτηδείους τῶν αὐτομόλων."},{"number":439,"text":"ἔπειτα σκάφεσιν ἐπιβήσας τοὺς στρατιώτας αἱρεῖ τοὺς εἰς τὴν λίμνην καταφεύγοντας. καὶ τὰ μὲν κατὰ τὴν Περαίαν προσεχώρησεν ἢ ἑάλω πάντα μέχρι Μαχαιροῦντος."}],"8":[{"number":440,"text":"Ἐν δὲ τούτῳ τὸ περὶ τὴν Γαλατίαν ἀγγέλλεται κίνημα καὶ Οὐίνδιξ ἅμα τοῖς δυνατοῖς τῶν ἐπιχωρίων ἀφεστὼς Νέρωνος, περὶ ὧν ἐν ἀκριβεστέροις ἀναγέγραπται."},{"number":441,"text":"Οὐεσπασιανὸν δʼ ἐπήγειρεν εἰς τὴν ὁρμὴν τοῦ πολέμου τὰ ἠγγελμένα προορώμενον ἤδη τοὺς μέλλοντας ἐμφυλίους πολέμους καὶ τὸν ὅλης κίνδυνον τῆς ἡγεμονίας, ἐν ᾧ προειρηνεύσας τὰ κατὰ τὴν ἀνατολὴν ἐπικουφίσειν ᾤετο τοὺς κατὰ τὴν Ἰταλίαν φόβους."},{"number":442,"text":"ἕως μὲν οὖν ἐπεῖχεν ὁ χειμὼν τὰς ὑπηγμένας διησφαλίζετο κώμας τε καὶ πολίχνας φρουραῖς, δεκαδάρχας μὲν κώμαις ἐγκαθιστάς, ἑκατοντάρχας δὲ πόλεσι· πολλὰ δὲ ἀνῴκιζε καὶ τῶν πεπορθημένων."},{"number":443,"text":"ὑπὸ δὲ τὴν ἀρχὴν τοῦ ἔαρος ἀναλαβὼν τὸ πλέον τῆς δυνάμεως ἤγαγεν ἀπὸ τῆς Καισαρείας ἐπὶ Ἀντιπατρίδος, ἔνθα δυσὶν ἡμέραις καταστησάμενος τὴν πόλιν τῇ τρίτῃ προῄει πορθῶν καὶ καίων τὰς πέριξ πάσας."},{"number":444,"text":"καταστρεψάμενος δὲ τὰ περὶ τὴν Θαμνὰ τοπαρχίαν ἐπὶ Λύδδων καὶ Ἰαμνείας ἐχώρει καὶ προκεχειρωμέναις ἑκατέραις ἐγκαταστήσας οἰκήτορας τῶν προσκεχωρηκότων ἱκανοὺς εἰς Ἀμμαοῦντα ἀφικνεῖται."},{"number":445,"text":"καταλαβόμενος δὲ τὰς ἐπὶ τὴν μητρόπολιν αὐτῶν εἰσβολὰς στρατόπεδόν τε τειχίζει καὶ τὸ πέμπτον ἐν αὐτῇ τάγμα καταλιπὼν πρόεισι μετὰ τῆς ἄλλης δυνάμεως ἐπὶ τὴν Βεθλεπτηνφῶν τοπαρχίαν."},{"number":446,"text":"πυρὶ δὲ αὐτήν τε καὶ τὴν γειτνιῶσαν ἀνελὼν καὶ τὰ πέριξ τῆς Ἰδουμαίας φρούρια τοῖς ἐπικαίροις τόποις ἐπετείχισε·"},{"number":447,"text":"καταλαβόμενος δὲ δύο κώμας τὰς μεσαιτάτας τῆς Ἰδουμαίας, Βήταβριν καὶ Καφάρτοβαν, κτείνει μὲν ὑπὲρ μυρίους,"},{"number":448,"text":"αἰχμαλωτίζεται δὲ ὑπὲρ χιλίους, καὶ τὸ λοιπὸν πλῆθος ἐξελάσας ἐγκαθίστησιν τῆς οἰκείας δυνάμεως οὐκ ὀλίγην, οἳ κατατρέχοντες ἐπόρθουν ἅπασαν τὴν ὀρεινήν."},{"number":449,"text":"αὐτὸς δὲ μετὰ τῆς λοιπῆς δυνάμεως ὑπέστρεψεν εἰς Ἀμμαοῦν, ὅθεν διὰ τῆς Σαμαρείτιδος καὶ παρὰ τὴν Νέαν πόλιν καλουμένην, Μαβαρθὰ δʼ ὑπὸ τῶν ἐπιχωρίων, καταβὰς εἰς Κορέαν δευτέρᾳ Δαισίου μηνὸς στρατοπεδεύεται."},{"number":450,"text":"τῇ δʼ ἑξῆς εἰς Ἱεριχοῦντα ἀφικνεῖται, καθʼ ἣν αὐτῷ συμμίσγει Τραϊανὸς εἷς τῶν ἡγεμόνων τὴν ἐκ τῆς Περαίας ἄγων δύναμιν ἤδη τῶν ὑπὲρ τὸν Ἰορδάνην κεχειρωμένων."},{"number":451,"text":"Τὸ μὲν οὖν πολὺ πλῆθος ἐκ τῆς Ἱεριχοῦς φθάσαν τὴν ἔφοδον αὐτῶν εἰς τὴν ἄντικρυς Ἱεροσολύμων ὀρεινὴν διαπεφεύγει, καταλειφθὲν δὲ οὐκ ὀλίγον διαφθείρεται."},{"number":452,"text":"τὴν δὲ πόλιν ἔρημον κατειλήφεσαν, ἥτις ἵδρυται μὲν ἐν πεδίῳ, ψιλὸν δὲ ὑπέρκειται αὐτῇ καὶ ἄκαρπον ὄρος μήκιστον·"},{"number":453,"text":"κατὰ γὰρ τὸ βόρειον κλίμα μέχρι τῆς Σκυθοπολιτῶν γῆς ἐκτείνεται, κατὰ δὲ τὸ μεσημβρινὸν μέχρι τῆς Σοδομιτῶν χώρας καὶ τῶν περάτων τῆς Ἀσφαλτίτιδος. ἔστιν δὲ ἀνώμαλόν τε πᾶν καὶ ἀοίκητον διὰ τὴν ἀγονίαν."},{"number":454,"text":"ἀντίκειται δὲ τούτῳ τὸ περὶ τὸν Ἰορδάνην ὄρος ἀρχόμενον ἀπὸ Ἰουλιάδος καὶ τῶν βορείων κλιμάτων, παρατεῖνον δὲ εἰς μεσημβρίαν ἕως Σομόρων, ἥπερ ὁρίζει τὴν Πέτραν τῆς Ἀραβίας. ἐν τούτῳ δʼ ἐστὶ καὶ τὸ Σιδηροῦν καλούμενον ὄρος μηκυνόμενον μέχρι τῆς Μωαβίτιδος."},{"number":455,"text":"ἡ μέση δὲ τῶν δύο ὀρέων χώρα τὸ μέγα πεδίον καλεῖται, ἀπὸ κώμης Γινναβρὶν διῆκον μέχρι τῆς Ἀσφαλτίτιδος."},{"number":456,"text":"ἔστι δὲ αὐτοῦ μῆκος μὲν σταδίων χιλίων διακοσίων, εὖρος δʼ εἴκοσι καὶ ἑκατόν, καὶ μέσον ὑπὸ τοῦ Ἰορδάνου τέμνεται λίμνας τε ἔχει τήν τε Ἀσφαλτῖτιν καὶ τὴν Τιβεριέων φύσιν ἐναντίας· ἡ μὲν γὰρ ἁλμυρώδης καὶ ἄγονος, ἡ Τιβεριέων δὲ γλυκεῖα καὶ γόνιμος."},{"number":457,"text":"ἐκπυροῦται δὲ ὥρᾳ θέρους τὸ πεδίον καὶ διʼ ὑπερβολὴν αὐχμοῦ περιέχει νοσώδη τὸν ἀέρα·"},{"number":458,"text":"πᾶν γὰρ ἄνυδρον πλὴν τοῦ Ἰορδάνου, παρὸ καὶ τοὺς μὲν ἐπὶ ταῖς ὄχθαις φοινικῶνας εὐθαλεστέρους καὶ πολυφορωτέρους εἶναι συμβέβηκεν, ἧττον δὲ τοὺς πόρρω κεχωρισμένους."},{"number":459,"text":"Παρὰ μέντοι τὴν Ἱεριχοῦν ἐστι πηγὴ δαψιλής τε καὶ πρὸς ἀρδείας λιπαρωτάτη παρὰ τὴν παλαιὰν ἀναβλύζουσα πόλιν, ἣν Ἰησοῦς ὁ Ναυῆ παῖς στρατηγὸς Ἑβραίων πρώτην εἷλε γῆς Χαναναίων δορίκτητον."},{"number":460,"text":"ταύτην τὴν πηγὴν λόγος ἔχει κατʼ ἀρχὰς οὐ μόνον γῆς καὶ δένδρων καρποὺς ἀπαμβλύνειν, ἀλλὰ καὶ γυναικῶν γονάς, καθόλου τε πᾶσιν εἶναι νοσώδη τε καὶ φθαρτικήν, ἐξημερωθῆναι δὲ καὶ γενέσθαι τοὐναντίον ὑγιεινοτάτην τε καὶ γονιμωτάτην ὑπὸ Ἐλισσαίου τοῦ προφήτου· γνώριμος δʼ ἦν οὗτος Ἠλία καὶ διάδοχος·"},{"number":461,"text":"ὃς ἐπιξενωθεὶς τοῖς κατὰ τὴν Ἱεριχοῦν, περισσὸν δή τι φιλοφρονησαμένων αὐτὸν τῶν ἀνθρώπων αὐτούς τε ἀμείβεται καὶ τὴν χώραν αἰωνίῳ χάριτι."},{"number":462,"text":"προελθὼν γὰρ ἐπὶ τὴν πηγὴν καὶ καταβαλὼν εἰς τὸ ῥεῦμα πλῆρες ἁλῶν ἀγγεῖον κεράμου, ἔπειτα εἰς οὐρανὸν δεξιὰν ἀνατείνας δικαίαν κἀπὶ γῆς σπονδὰς μειλικτηρίους χεόμενος, τὴν μὲν ᾐτεῖτο μαλάξαι τὸ ῥεῦμα καὶ γλυκυτέρας φλέβας ἀνοῖξαι,"},{"number":463,"text":"τὸν δὲ ἐγκεράσασθαι τῷ ῥεύματι γονιμωτέρους [τε] ἀέρας δοῦναί τε ἅμα καὶ καρπῶν εὐθηνίαν τοῖς ἐπιχωρίοις καὶ τέκνων διαδοχήν, μηδʼ ἐπιλιπεῖν αὐτοῖς τὸ τούτων γεννητικὸν ὕδωρ, ἕως μένουσι δίκαιοι."},{"number":464,"text":"ταύταις ταῖς εὐχαῖς πολλὰ προσχειρουργήσας ἐξ ἐπιστήμης ἔτρεψε τὴν πηγήν, καὶ τὸ πρὶν ὀρφανίας αὐτοῖς καὶ λιμοῦ παραίτιον ὕδωρ ἔκτοτε εὐτεκνίας καὶ κόρου χορηγὸν κατέστη."},{"number":465,"text":"τοσαύτην γοῦν ἐν ταῖς ἀρδείαις ἔχει δύναμιν ὡς, εἰ καὶ μόνον ἐφάψαιτο τῆς χώρας, νοστιμώτερον εἶναι τῶν μέχρι κόρου χρονιζόντων."},{"number":466,"text":"παρὸ καὶ τῶν [μὲν] δαψιλεστέρως χρωμένων ἡ ὄνησίς ἐστιν ὀλίγη, τούτου δὲ τοῦ ὀλίγου χορηγία δαψιλής."},{"number":467,"text":"ἄρδει γοῦν πλέονα τῶν ἄλλων ἁπάντων, καὶ πεδίον μὲν ἔπεισιν ἑβδομήκοντα σταδίων μῆκος εὖρος δʼ εἴκοσιν, ἐκτρέφει δʼ ἐν αὐτῷ παραδείσους καλλίστους τε καὶ πυκνοτάτους."},{"number":468,"text":"τῶν δὲ φοινίκων ἐπαρδομένων γένη πολλὰ ταῖς γεύσεσι καὶ ταῖς παρηγορίαις διάφορα· τούτων οἱ πιότεροι πατούμενοι καὶ μέλι δαψιλὲς ἀνιᾶσιν οὐ πολλῷ τοῦ λοιποῦ χεῖρον."},{"number":469,"text":"καὶ μελιττοτρόφος δὲ ἡ χώρα· φέρει δὲ καὶ ὀποβάλσαμον, ὃ δὴ τιμιώτατον τῶν τῇδε καρπῶν, κύπρον τε καὶ μυροβάλανον, ὡς οὐκ ἂν ἁμαρτεῖν τινα εἰπόντα θεῖον εἶναι τὸ χωρίον, ἐν ᾧ δαψιλῆ τὰ σπανιώτατα καὶ κάλλιστα γεννᾶται."},{"number":470,"text":"τῶν μὲν γὰρ ἄλλων αὐτῷ καρπῶν ἕνεκεν οὐκ ἂν ῥᾳδίως τι παραβληθείη κλίμα τῆς οἰκουμένης· οὕτως τὸ καταβληθὲν πολύχουν ἀναδίδωσιν."},{"number":471,"text":"αἴτιόν μοι δοκεῖ τὸ θερμὸν τῶν ἀέρων καὶ τὸ τῶν ὑδάτων εὔτονον, τῶν μὲν προκαλουμένων τὰ φυόμενα καὶ διαχεόντων, τῆς δὲ ἰκμάδος ῥιζούσης ἕκαστον ἰσχυρῶς καὶ χορηγούσης τὴν ἐν θέρει δύναμιν· περικαὲς δέ ἐστιν οὕτως τὸ χωρίον, ὡς μηδένα ῥᾳδίως προϊέναι."},{"number":472,"text":"τὸ δὲ ὕδωρ πρὸ ἀνατολῆς ἀντλούμενον, ἔπειτα ἐξαιθριασθὲν γίνεται ψυχρότατον καὶ τὴν ἐναντίαν πρὸς τὸ περιέχον φύσιν λαμβάνει, χειμῶνος δὲ ἀνάπαλιν χλιαίνεται καὶ τοῖς ἐμβαίνουσι γίνεται προσηνέστατον."},{"number":473,"text":"ἔστι δὲ καὶ τὸ περιέχον οὕτως εὔκρατον, ὡς λινοῦν ἀμφιέννυσθαι τοὺς ἐπιχωρίους νιφομένης τῆς ἄλλης Ἰουδαίας."},{"number":474,"text":"ἀπέχει δὲ ἀπὸ Ἱεροσολύμων μὲν σταδίους ἑκατὸν πεντήκοντα, τοῦ δὲ Ἰορδάνου ἑξήκοντα, καὶ τὸ μὲν μέχρι Ἱεροσολύμων αὐτῆς ἔρημον καὶ πετρῶδες, τὸ δὲ μέχρι τοῦ Ἰορδάνου καὶ τῆς Ἀσφαλτίτιδος χθαμαλώτερον μέν, ἔρημον δὲ ὁμοίως καὶ ἄκαρπον."},{"number":475,"text":"ἀλλὰ γὰρ τὰ μὲν περὶ Ἱεριχοῦν εὐδαιμονεστάτην οὖσαν ἀποχρώντως δεδήλωται."},{"number":476,"text":"Ἄξιον δὲ ἀφηγήσασθαι καὶ τὴν φύσιν τῆς Ἀσφαλτίτιδος λίμνης, ἥτις ἐστὶ μέν, ὡς ἔφην, πικρὰ καὶ ἄγονος, ὑπὸ δὲ κουφότητος καὶ τὰ βαρύτατα τῶν εἰς αὐτὴν ῥιφέντων ἀναφέρει, καταδῦναι δʼ εἰς τὸν βυθὸν οὐδὲ ἐπιτηδεύσαντα ῥᾴδιον."},{"number":477,"text":"ἀφικόμενος γοῦν καθʼ ἱστορίαν ἐπʼ αὐτὴν Οὐεσπασιανὸς ἐκέλευσέ τινας τῶν νεῖν οὐκ ἐπισταμένων δεθέντας ὀπίσω τὰς χεῖρας ῥιφῆναι κατὰ τοῦ βυθοῦ, καὶ συνέβη πάντας ἐπινήξασθαι καθάπερ ὑπὸ πνεύματος ἄνω βιαζομένους."},{"number":478,"text":"ἔστι δʼ ἐπὶ τούτῳ καὶ ἡ τῆς χρόας μεταβολὴ θαυμάσιος· τρὶς γὰρ ἑκάστης ἡμέρας τὴν ἐπιφάνειαν ἀλλάσσεται καὶ πρὸς τὰς ἡλιακὰς ἀκτῖνας ἀνταυγεῖ ποικίλως."},{"number":479,"text":"τῆς μέντοι ἀσφάλτου κατὰ πολλὰ μέρη βώλους μελαίνας ἀναδίδωσιν· αἱ δʼ ἐπινήχονται τό τε σχῆμα καὶ τὸ μέγεθος ταύροις ἀκεφάλοις παραπλήσιαι."},{"number":480,"text":"προσελαύνοντες δὲ οἱ τῆς λίμνης ἐργάται καὶ δρασσόμενοι τοῦ συνεστῶτος ἕλκουσιν εἰς τὰ σκάφη, πληρώσασι δὲ ἀποκόπτειν οὐ ῥᾴδιον, ἀλλὰ διʼ εὐτονίαν προσήρτηται τῷ μηρύματι τὸ σκάφος, ἕως ἂν ἐμμηνίῳ γυναικῶν αἵματι καὶ οὔρῳ διαλύσωσιν αὐτήν, οἷς μόνοις εἴκει."},{"number":481,"text":"καὶ χρήσιμος δὲ οὐ μόνον εἰς ἁρμονίας νεῶν ἀλλὰ καὶ πρὸς ἄκεσιν σωμάτων· εἰς πολλὰ γοῦν τῶν φαρμάκων παραμίσγεται."},{"number":482,"text":"ταύτης τῆς λίμνης μῆκος μὲν ὀγδοήκοντα καὶ πεντακόσιοι στάδιοι, καθὸ δὴ μέχρι Ζοάρων τῆς Ἀραβίας ἐκτείνεται, εὖρος δὲ πεντήκοντα καὶ ἑκατόν."},{"number":483,"text":"γειτνιᾷ δʼ ἡ Σοδομῖτις αὐτῇ, πάλαι μὲν εὐδαίμων γῆ καρπῶν τε ἕνεκεν καὶ τῆς κατὰ πόλιν περιουσίας, νῦν δὲ κεκαυμένη πᾶσα."},{"number":484,"text":"φασὶ δὲ ὡς διʼ ἀσέβειαν οἰκητόρων κεραυνοῖς καταφλεγῆναι· ἔστι γοῦν ἔτι λείψανα τοῦ θείου πυρός, καὶ πέντε μὲν πόλεων ἰδεῖν σκιάς, ἔτι δὲ κἀν τοῖς καρποῖς σποδιὰν ἀναγεννωμένην, οἳ χροιὰν μὲν ἔχουσι τῶν ἐδωδίμων ὁμοίαν, δρεψαμένων δὲ χερσὶν εἰς καπνὸν διαλύονται καὶ τέφραν."},{"number":485,"text":"τὰ μὲν δὴ περὶ τὴν Σοδομῖτιν μυθευόμενα τοιαύτην ἔχει πίστιν ἀπὸ τῆς ὄψεως."}],"9":[{"number":486,"text":"Ὁ δὲ Οὐεσπασιανὸς πανταχόθεν περιτειχίζων τοὺς ἐν τοῖς Ἱεροσολύμοις ἔν τε τῇ Ἱεριχοῖ καὶ ἐν Ἀδίδοις ἐγείρει στρατόπεδα καὶ φρουροὺς ἀμφοτέραις ἐγκαθίστησιν ἔκ τε τοῦ Ῥωμαϊκοῦ καὶ συμμαχικοῦ συντάγματος."},{"number":487,"text":"πέμπει δὲ καὶ εἰς Γέρασα Λούκιον Ἄννιον παραδοὺς μοῖραν ἱππέων καὶ συχνοὺς πεζούς."},{"number":488,"text":"ὁ μὲν οὖν ἐξ ἐφόδου τὴν πόλιν ἑλὼν ἀποκτείνει μὲν χιλίους τῶν νέων, ὅσοι μὴ διαφυγεῖν ἔφθασαν, γενεὰς δὲ ᾐχμαλωτίσατο καὶ τὰς κτήσεις διαρπάσαι τοῖς στρατιώταις ἐπέτρεψεν· ἔπειτα τὰς οἰκίας ἐμπρήσας ἐπὶ τὰς πέριξ κώμας ἐχώρει."},{"number":489,"text":"φυγαὶ δʼ ἦσαν τῶν δυνατῶν καὶ φθοραὶ τῶν ἀσθενεστέρων, τὸ καταλειφθὲν δὲ πᾶν ἐνεπίμπρατο."},{"number":490,"text":"καὶ διειληφότος τοῦ πολέμου τήν τε ὀρεινὴν ὅλην καὶ τὴν πεδιάδα πάσας οἱ ἐν τοῖς Ἱεροσολύμοις τὰς ἐξόδους ἀφῄρηντο· τοὺς μέν γε αὐτομολεῖν προαιρουμένους οἱ ζηλωταὶ παρεφυλάσσοντο, τοὺς δὲ οὔπω τὰ Ῥωμαίων φρονοῦντας εἶργεν ἡ στρατιὰ πανταχόθεν τὴν πόλιν περιέχουσα."},{"number":491,"text":"Οὐεσπασιανῷ δʼ εἰς Καισάρειαν ἐπιστρέψαντι καὶ παρασκευαζομένῳ μετὰ πάσης τῆς δυνάμεως ἐπʼ αὐτῶν τῶν Ἱεροσολύμων ἐξελαύνειν ἀγγέλλεται Νέρων ἀνῃρημένος, τρία καὶ δέκα βασιλεύσας ἔτη καὶ ἡμέρας ὀκτώ."},{"number":492,"text":"περὶ οὗ λέγειν ὃν τρόπον εἰς τὴν ἀρχὴν ἐξύβρισεν πιστεύσας τὰ πράγματα τοῖς πονηροτάτοις, Νυμφιδίῳ καὶ Τιγελλίνῳ,"},{"number":493,"text":"τοῖς τε ἀναξίοις τῶν ἐξελευθέρων, καὶ ὡς ὑπὸ τούτων ἐπιβουλευθεὶς κατελείφθη μὲν ὑπὸ τῶν φυλάκων ἁπάντων, διαδρὰς δὲ σὺν τέτρασι τῶν πιστῶν ἀπελευθέρων ἐν τοῖς προαστείοις ἑαυτὸν ἀνεῖλεν, καὶ ὡς οἱ καταλύσαντες αὐτὸν μετʼ οὐ πολὺν χρόνον δίκας ἔδοσαν,"},{"number":494,"text":"τόν τε κατὰ τὴν Γαλατίαν πόλεμον ὡς ἐτελεύτησε, καὶ πῶς Γάλβας ἀποδειχθεὶς αὐτοκράτωρ εἰς Ῥώμην ἐπανῆλθεν ἐκ τῆς Ἱσπανίας, καὶ ὡς ὑπὸ τῶν στρατιωτῶν αἰτιαθεὶς ἐπὶ ταπεινοφροσύνῃ ἐδολοφονήθη κατὰ μέσην τὴν Ῥωμαίων ἀγορὸν ἀπεδείχθη τε αὐτοκράτωρ Ὄθων·"},{"number":495,"text":"τήν τε τούτου στρατείαν ἐπὶ τοὺς Οὐιτελλίου στρατηγοὺς καὶ κατάλυσιν, ἔπειτα τοὺς κατὰ Οὐιτέλλιον ταράχους καὶ τὴν περὶ τὸ Καπετώλιον συμβολήν, ὅπως τε Ἀντώνιος Πρῖμος καὶ Μουκιανὸς διαφθείραντες Οὐιτέλλιον καὶ τὰ Γερμανικὰ τάγματα κατέστειλαν τὸν ἐμφύλιον πόλεμον."},{"number":496,"text":"πάντα ταῦτα διεξιέναι μὲν ἐπʼ ἀκριβὲς παρῃτησάμην, ἐπειδὴ διʼ ὄχλου πᾶσίν ἐστιν καὶ πολλοῖς Ἑλλήνων τε καὶ Ῥωμαίων ἀναγέγραπται, συναφείας δὲ ἕνεκεν τῶν πραγμάτων καὶ τοῦ μὴ διηρτῆσθαι τὴν ἱστορίαν κεφαλαιωδῶς ἕκαστον ἐπισημαίνομαι."},{"number":497,"text":"Οὐεσπασιανὸς τοίνυν τὸ μὲν πρῶτον ἀνεβάλλετο τὴν τῶν Ἱεροσολύμων στρατείαν, καραδοκῶν πρὸς τίνα ῥέψει τὸ κρατεῖν μετὰ Νέρωνα·"},{"number":498,"text":"αὖθις δὲ Γάλβαν ἀκούσας αὐτοκράτορα, πρὶν ἐπιστεῖλαί τι περὶ τοῦ πολέμου κἀκεῖνον, οὐκ ἐπεχείρει, πέμπει δὲ πρὸς αὐτὸν καὶ τὸν υἱὸν Τίτον ἀσπασόμενόν τε καὶ ληψόμενον τὰς περὶ Ἰουδαίων ἐντολάς. διὰ δὲ τὰς αὐτὰς αἰτίας ἅμα Τίτῳ καὶ Ἀγρίππας ὁ βασιλεὺς πρὸς Γάλβαν ἔπλει."},{"number":499,"text":"καὶ διὰ τῆς Ἀχαΐας, χειμῶνος γὰρ ἦν ὥρα, μακραῖς ναυσὶ περιπλεόντων φθάνει Γάλβας ἀναιρεθεὶς μετὰ μῆνας ἑπτὰ καὶ ἴσας ἡμέρας· ἐξ οὗ καὶ τὴν ἡγεμονίαν παρέλαβεν Ὄθων ἀντιποιούμενος τῶν πραγμάτων."},{"number":500,"text":"ὁ μὲν οὖν Ἀγρίππας εἰς τὴν Ῥώμην ἀφικέσθαι διέγνω μηδὲν ὀρρωδήσας πρὸς τὴν μεταβολήν·"},{"number":501,"text":"Τίτος δὲ κατὰ δαιμόνιον ὁρμὴν ἀπὸ τῆς Ἑλλάδος εἰς τὴν Συρίαν ἀνέπλει καὶ κατὰ τάχος εἰς Καισάρειαν ἀφικνεῖται πρὸς τὸν πατέρα."},{"number":502,"text":"καὶ οἱ μὲν μετέωροι περὶ τῶν ὅλων ὄντες ὡς ἂν σαλευομένης τῆς Ῥωμαίων ἡγεμονίας ὑπερεώρων τὴν ἐπὶ Ἰουδαίους στρατείαν, καὶ διὰ τὸν περὶ τῆς πατρίδος φόβον τὴν ἐπὶ τοὺς ἀλλοφύλους ὁρμὴν ἄωρον ἐνόμιζον."},{"number":503,"text":"Ἐπανίσταται δὲ ἄλλος τοῖς Ἱεροσολύμοις πόλεμος. υἱὸς ἦν Γιώρα Σίμων τις, Γερασηνὸς τὸ γένος, νεανίας πανουργίᾳ μὲν ἡττώμενος Ἰωάννου τοῦ προκατέχοντος ἤδη τὴν πόλιν, ἀλκῇ δὲ σώματος καὶ τόλμῃ διαφέρων,"},{"number":504,"text":"διʼ ἣν καὶ ὑπὸ Ἀνάνου τοῦ ἀρχιερέως φυγαδευθεὶς ἐξ ἧς εἶχε τοπαρχίας Ἀκραβετηνῆς πρὸς τοὺς κατειληφότας τὴν Μασάδαν λῃστὰς παραγίνεται."},{"number":505,"text":"τὸ μὲν οὖν πρῶτον ἦν αὐτοῖς διʼ ὑποψίας· εἰς τὸ κατωτέρω γοῦν φρούριον ἐπέτρεψαν αὐτῷ παρελθεῖν ἅμα ταῖς γυναιξίν, ἃς ἄγων ἧκεν, αὐτοὶ τὸ ὑψηλότερον οἰκοῦντες·"},{"number":506,"text":"αὖθις δὲ διὰ συγγένειαν ἠθῶν καὶ ὅτι πιστὸς ἐδόκει, συμπροενόμευε γοῦν αὐτοῖς ἐξιὼν καὶ συνεπόρθει τὰ περὶ τὴν Μασάδαν ."},{"number":507,"text":"οὐ μὴν ἐπὶ τὰ μείζω παρακαλῶν ἔπεισεν· οἱ μὲν γὰρ ἐν ἔθει ὄντες τῷ φρουρίῳ,"},{"number":508,"text":"καθάπερ φωλεοῦ χωρίζεσθαι μακρὰν ἐδεδοίκεσαν, ὁ δὲ τυραννιῶν καὶ μεγάλων ἐφιέμενος ἐπειδὴ καὶ τὴν Ἀνάνου τελευτὴν ἤκουσεν, εἰς τὴν ὀρεινὴν ἀφίσταται, καὶ προκηρύξας δούλοις μὲν ἐλευθερίαν, γέρας δὲ ἐλευθέροις τοὺς πανταχόθεν πονηροὺς συνήθροιζεν."},{"number":509,"text":"Ὡς δʼ ἦν αὐτῷ καρτερὸν ἤδη τὸ σύνταγμα, τὰς ἀνὰ τὴν ὀρεινὴν κώμας κατέτρεχεν, ἀεὶ δὲ προσγινομένων πλειόνων ἐθάρρει καταβαίνειν εἰς τὰ χθαμαλώτερα."},{"number":510,"text":"κἀπειδὴ πόλεσιν ἤδη φοβερὸς ἦν, πολλοὶ πρὸς τὴν ἰσχὺν καὶ τὴν εὔροιαν τῶν κατορθωμάτων ἐφθείροντο δυνατοί, καὶ οὐκέτι ἦν δούλων μόνων οὐδὲ λῃστῶν στρατός, ἀλλὰ καὶ δημοτικῶν οὐκ ὀλίγων ὡς πρὸς βασιλέα πειθαρχεῖν."},{"number":511,"text":"κατέτρεχε δὲ τήν τε Ἀκραβετηνὴν τοπαρχίαν καὶ τὰ μέχρι τῆς μεγάλης Ἰδουμαίας· κατὰ γὰρ κώμην τινὰ καλουμένην Ἀῒν τεῖχος κατασκευάσας ὥσπερ φρουρίῳ πρὸς ἀσφάλειαν ἐχρῆτο,"},{"number":512,"text":"κατὰ δὲ τὴν φάραγγα προσαγορευομένην Φερεταὶ πολλὰ μὲν ἀνευρύνας σπήλαια, πολλὰ δʼ εὑρὼν ἕτοιμα ταμιείοις ἐχρῆτο θησαυρῶν καὶ τῆς λείας ἐκδοχείοις."},{"number":513,"text":"ἀνετίθει δὲ καὶ τοὺς ἁρπαζομένους εἰς αὐτὰ καρπούς, οἵ τε πολλοὶ τῶν λόχων δίαιταν εἶχον ἐν ἐκείνοις· δῆλος δʼ ἦν τό τε σύνταγμα προγυμνάζων καὶ τὰς παρασκευὰς κατὰ τῶν Ἱεροσολύμων."},{"number":514,"text":"Ὅθεν οἱ ζηλωταὶ δείσαντες αὐτοῦ τὴν ἐπιβουλὴν καὶ προλαβεῖν βουλόμενοι τὸν κατʼ αὐτῶν τρεφόμενον ἐξίασι μετὰ τῶν ὅπλων οἱ πλείους· ὑπαντιάζει δὲ Σίμων, καὶ παραταξάμενος συχνοὺς μὲν αὐτῶν ἀναιρεῖ, συνελαύνει δὲ τοὺς λοιποὺς εἰς τὴν πόλιν."},{"number":515,"text":"οὔπω δὲ θαρρῶν τῇ δυνάμει τοῦ μὲν τοῖς τείχεσιν προσβάλλειν ἀπετράπη, χειρώσασθαι δὲ πρότερον τὴν Ἰδουμαίαν ἐπεβάλετο· καὶ δὴ δισμυρίους ἔχων ὁπλίτας ἤλαυνεν ἐπὶ τοὺς ὅρους αὐτῆς."},{"number":516,"text":"οἱ δὲ ἄρχοντες τῆς Ἰδουμαίας κατὰ τάχος ἀθροίσαντες ἐκ τῆς χώρας τὸ μαχιμώτατον περὶ πεντακισχιλίους καὶ δισμυρίους, τοὺς δὲ πολλοὺς ἐάσαντες φρουρεῖν τὰ σφέτερα διὰ τὰς τῶν ἐν Μασάδᾳ σικαρίων καταδρομάς, ἐδέχοντο τὸν Σίμωνα πρὸς τοῖς ὅροις."},{"number":517,"text":"ἔνθα συμβαλὼν αὐτοῖς καὶ διʼ ὅλης πολεμήσας ἡμέρας, οὔτε νενικηκὼς οὔτε νενικημένος διεκρίθη, καὶ ὁ μὲν εἰς τὴν Ναΐν, οἱ δὲ Ἰδουμαῖοι διελύθησαν ἐπʼ οἴκου."},{"number":518,"text":"καὶ μετʼ οὐ πολὺ Σίμων μείζονι δυνάμει πάλιν εἰς τὴν χώραν αὐτῶν ὥρμητο, στρατοπεδευσάμενος δὲ κατά τινα κώμην, Θεκουὲ καλεῖται, πρὸς τοὺς ἐν Ἡρωδείῳ φρουρούς, ὅπερ ἦν πλησίον, Ἐλεάζαρόν τινα τῶν ἑταίρων ἔπεμψε πείσοντα παραδοῦναι τὸ ἔρυμα."},{"number":519,"text":"τοῦτον οἱ φύλακες προθύμως ἐδέξαντο τὴν αἰτίαν ἀγνοοῦντες διʼ ἣν ἥκοι, φθεγξάμενον δὲ περὶ παραδόσεως ἐδίωκον σπασάμενοι τὰ ξίφη, μέχρι φυγῆς τόπον οὐκ ἔχων ἔρριψεν ἀπὸ τοῦ τείχους ἑαυτὸν εἰς τὴν ὑποκειμένην φάραγγα."},{"number":520,"text":"καὶ ὁ μὲν αὐτίκα τελευτᾷ, τοῖς δʼ Ἰδουμαίοις ἤδη κατορρωδοῦσι τὴν ἰσχὺν τοῦ Σίμωνος ἔδοξε πρὸ τοῦ συμβαλεῖν κατασκέψασθαι τὴν στρατιὰν τῶν πολεμίων."},{"number":521,"text":"Εἰς τοῦτο δὲ ὑπηρέτην αὑτὸν ἑτοίμως ἐπεδίδου Ἰάκωβος, εἷς τῶν ἡγεμόνων, προδοσίαν ἐνθυμούμενος."},{"number":522,"text":"ὁρμήσας γοῦν ἀπὸ τῆς Ἀλούρου, κατὰ γὰρ ταύτην συνήθροιστο τὴν κώμην τότε τῶν Ἰδουμαίων τὸ στράτευμα,"},{"number":523,"text":"παραγίνεται πρὸς Σίμωνα, καὶ πρώτην αὐτῷ παραδώσειν συντίθεται τὴν αὐτοῦ πατρίδα, λαβὼν ὅρκους ὡς ἀεὶ τίμιος ὢν διατελέσει, συνεργήσειν δὲ ὑπέσχετο καὶ περὶ τῆς ὅλης Ἰδουμαίας."},{"number":524,"text":"ἐφʼ οἷς ἑστιαθεὶς φιλοφρόνως ὑπὸ τοῦ Σίμωνος καὶ λαμπραῖς ἐπαρθεὶς ὑποσχέσεσιν, ἐπειδήπερ εἰς τοὺς σφετέρους ὑπέστρεψε, τὸ μὲν πρῶτον πολλαπλασίονα τὴν στρατιὰν ἐψεύδετο τοῦ Σίμωνος,"},{"number":525,"text":"ἔπειτα δεξιούμενος τούς τε ἡγεμόνας καὶ κατʼ ὀλίγους πᾶν τὸ πλῆθος ἐνῆγεν ὥστε δέξασθαι τὸν Σίμωνα καὶ παραδοῦναι δίχα μάχης αὐτῷ τὴν τῶν ὅλων ἀρχήν."},{"number":526,"text":"ἅμα δὲ ταῦτα διαπραττόμενος καὶ Σίμωνα διʼ ἀγγέλων ἐκάλει σκεδάσειν ὑπισχνούμενος τοὺς Ἰδουμαίους· ὃ δὴ παρέσχεν."},{"number":527,"text":"ὡς γὰρ ἦν ἤδη πλησίον ἡ στρατιά, πρῶτος ἀναπηδήσας ἐπὶ τὸν ἵππον μετὰ τῶν συνδιεφθαρμένων ἔφευγε."},{"number":528,"text":"πτοία δʼ ἐμπίπτει παντὶ τῷ πλήθει, καὶ πρὶν εἰς χεῖρας ἐλθεῖν λυθέντες ἐκ τῆς τάξεως ἀνεχώρουν ἕκαστοι πρὸς τὰ ἴδια."},{"number":529,"text":"Σίμων δὲ παρὰ δόξαν εἰς τὴν Ἰδουμαίαν εἰσήλασεν ἀναιμωτὶ καὶ προσβαλὼν ἀδοκήτως πρώτην αἱρεῖ τὴν πολίχνην Χεβρών, ἐν ᾗ πλείστης ἐκράτησε λείας, πάμπολυν δὲ διήρπασε καρπόν."},{"number":530,"text":"ὡς δέ φασιν οἱ ἐπιχώριοι τὴν Χεβρὼν οὐ μόνον τῶν τῇδε πόλεων ἀλλὰ καὶ τῆς ἐν Αἰγύπτῳ Μέμφεως ἀρχαιοτέραν· δισχίλια γοῦν αὐτῇ καὶ τριακόσια ἔτη συναριθμεῖται."},{"number":531,"text":"μυθεύουσι δὲ αὐτὴν καὶ οἰκητήριον Ἀβράμου τοῦ Ἰουδαίων προγόνου γεγονέναι μετὰ τὴν ἐκ τῆς Μεσοποταμίας ἀπανάστασιν, τούς τε παῖδας αὐτοῦ λέγουσι καταβῆναι εἰς Αἴγυπτον ἔνθεν·"},{"number":532,"text":"ὧν καὶ τὰ μνημεῖα μέχρι νῦν ἐν τῇδε τῇ πολίχνῃ δείκνυται πάνυ καλῆς μαρμάρου καὶ φιλοτίμως εἰργασμένα."},{"number":533,"text":"δείκνυται δʼ ἀπὸ σταδίων ἓξ τοῦ ἄστεος τερέβινθος μεγίστη, καὶ φασὶ τὸ δένδρον ἀπὸ τῆς κτίσεως μέχρι νῦν διαμένειν."},{"number":534,"text":"ἔνθεν ὁ Σίμων ἐχώρει διὰ πάσης τῆς Ἰδουμαίας, οὐ μόνον κώμας καὶ πόλεις πορθῶν, λυμαινόμενος δὲ καὶ τὴν χώραν· δίχα γὰρ τῶν ὁπλιτῶν τέσσαρες αὐτῷ συνείποντο μυριάδες, ὡς μηδὲ τῶν ἐπιτηδείων ἐξαρκούντων πρὸς τὸ πλῆθος."},{"number":535,"text":"προσῆν δὲ ταῖς χρείαις ὠμότης τε αὐτοῦ καὶ πρὸς τὸ γένος ὀργή, διʼ ἃ μᾶλλον ἐξερημοῦσθαι συνέβαινε τὴν Ἰδουμαίαν."},{"number":536,"text":"καθάπερ δὲ ὑπὸ τῶν ἀκρίδων κατόπιν ὕλην ἔστιν ἰδεῖν ἐψιλωμένην πᾶσαν, οὕτω τὸ κατὰ νώτου τῆς Σίμωνος στρατιᾶς ἐρημία κατελείπετο·"},{"number":537,"text":"καὶ τὰ μὲν ἐμπιπρῶντες τὰ δὲ κατασκάπτοντες, πᾶν δὲ τὸ πεφυκὸς ἀνὰ τὴν χώραν ἢ συμπατοῦντες ἠφάνιζον ἢ νεμόμενοι καὶ τὴν ἐνεργὸν ὑπὸ τῆς πορείας σκληροτέραν ἐποίουν τῆς ἀκάρπου, καθόλου τε εἰπεῖν, οὐδὲ σημεῖόν τι κατελείπετο τοῖς πορθουμένοις τοῦ γεγονέναι."},{"number":538,"text":"Ταῦτα πάλιν τοὺς ζηλωτὰς ἐπήγειρεν, καὶ φανερῶς μὲν ἀντιπαρατάξασθαι κατέδεισαν, προλοχίσαντες δʼ ἐν ταῖς παρόδοις ἁρπάζουσι τοῦ Σίμωνος τὴν γυναῖκα καὶ τῆς περὶ αὐτὴν θεραπείας συχνούς."},{"number":539,"text":"ἔπειτα ὡς αὐτὸν αἰχμαλωτισάμενοι τὸν Σίμωνα γεγηθότες εἰς τὴν πόλιν ὑπέστρεψαν καὶ ὅσον οὐδέπω προσεδόκων καταθέμενον τὰ ὅπλα περὶ τῆς γυναικὸς ἱκετεύσειν."},{"number":540,"text":"τὸν δὲ οὐκ ἔλεος εἰσῆλθεν ἀλλʼ ὀργὴ περὶ τῆς ἡρπασμένης, καὶ πρὸς τὸ τεῖχος τῶν Ἱεροσολύμων ἐλθὼν καθάπερ τὰ τρωθέντα τῶν θηρίων, ἐπειδὴ τοὺς τρώσαντας οὐ κατέλαβεν, ἐφʼ οὓς εὗρε τὸν θυμὸν ἠφίει."},{"number":541,"text":"ὅσοι γοῦν λαχανείας ἕνεκεν ἢ φρυγανισμοῦ προεληλύθεσαν ἔξω πυλῶν ἀνόπλους καὶ γέροντας συλλαμβάνων ᾐκίζετο καὶ διέφθειρεν, διʼ ὑπερβολὴν ἀγανακτήσεως μονονουχὶ καὶ νεκρῶν γευόμενος τῶν σωμάτων."},{"number":542,"text":"πολλοὺς δὲ καὶ χειροκοπήσας εἰσέπεμπε καταπλήξασθαι τοὺς ἐχθροὺς ἅμα καὶ διαστῆσαι τὸν δῆμον ἐπιχειρῶν πρὸς τοὺς αἰτίους."},{"number":543,"text":"ἐντέταλτο δʼ αὐτοῖς λέγειν, ὅτι Σίμων θεὸν ὄμνυσι τὸν πάντων ἔφορον, εἰ μὴ θᾶττον ἀποδώσουσιν αὐτῷ τὴν γυναῖκα, ῥήξας τὸ τεῖχος τοιαῦτα διαθήσειν πάντας τοὺς κατὰ τὴν πόλιν, μηδεμιᾶς φεισάμενος ἡλικίας μηδὲ ἀπὸ τῶν ἀναιτίων διακρίνας τοὺς αἰτίους."},{"number":544,"text":"τούτοις οὐ μόνον ὁ δῆμος ἀλλὰ καὶ οἱ ζηλωταὶ καταπλαγέντες ἀποπέμπουσιν αὐτῷ τὴν γυναῖκα· καὶ τότε μὲν ἐκμειλιχθεὶς ὀλίγον ἀνεπαύσατο τοῦ συνεχοῦς φόνου."},{"number":545,"text":"Οὐ μόνον δὲ κατὰ τὴν Ἰουδαίαν στάσις ἦν καὶ πόλεμος ἐμφύλιος, ἀλλὰ κἀπὶ τῆς Ἰταλίας."},{"number":546,"text":"ἀνῄρητο μὲν γὰρ κατὰ μέσην τὴν Ῥωμαίων ἀγορὰν Γάλβας, ἀποδεδειγμένος δὲ αὐτοκράτωρ Ὄθων ἐπολέμει Οὐιτελλίῳ βασιλειῶντι· τοῦτον γὰρ ᾕρητο τὰ κατὰ Γερμανίαν τάγματα."},{"number":547,"text":"καὶ γενομένης συμβολῆς κατὰ Φρηγδίακον τῆς Γαλατίας πρός τε Οὐάλεντα καὶ Καικίνναν τοὺς Οὐιτελλίου στρατηγούς, τῇ πρώτῃ μὲν ἡμέρᾳ περιῆν Ὄθων, τῇ δὲ δευτέρᾳ τὸ Οὐιτελλίου στρατιωτικόν·"},{"number":548,"text":"καὶ πολλοῦ φόνου γενομένου διεχρήσατο μὲν Ὄθων αὑτὸν ἐν Βριξέλλῳ τὴν ἧτταν πυθόμενος ἡμέρας δύο καὶ τρεῖς μῆνας κρατήσας τῶν πραγμάτων,"},{"number":549,"text":"προσεχώρησε δὲ τοῖς Οὐιτελλίου στρατηγοῖς ἡ στρατιά, καὶ κατέβαινεν αὐτὸς εἰς τὴν Ῥώμην μετὰ τῆς δυνάμεως."},{"number":550,"text":"ἐν δὲ τούτῳ καὶ Οὐεσπασιανὸς ἀναστὰς ἐκ τῆς Καισαρείας πέμπτῃ Δαισίου μηνὸς ὥρμησεν ἐπὶ τὰ μηδέπω κατεστραμμένα τῶν τῆς Ἰουδαίας χωρίων."},{"number":551,"text":"ἀναβὰς δὲ εἰς τὴν ὀρεινὴν αἱρεῖ δύο τοπαρχίας, τήν τε Γοφνιτικὴν καὶ τὴν Ἀκραβετηνὴν καλουμένην, μεθʼ ἃς Βήθηγά τε καὶ Ἐφραὶμ πολίχνια, οἷς φρουροὺς ἐγκαταστήσας μέχρι Ἱεροσολύμων ἱππάζετο· φθορὰ δʼ ἦν πολλῶν καταλαμβανομένων καὶ συχνοὺς ᾐχμαλωτίζετο."},{"number":552,"text":"Κερεάλιος δὲ αὐτῷ τῶν ἡγεμόνων μοῖραν ἱππέων καὶ πεζῶν ἀναλαβὼν τὴν ἄνω καλουμένην Ἰδουμαίαν ἐπόρθει, καὶ Κάφεθρα μὲν ψευδοπολίχνιον ἐξ ἐφόδου λαβὼν ἐμπίπρησιν, ἑτέραν δὲ καλουμένην Χαραβὶν προσβαλὼν ἐπολιόρκει."},{"number":553,"text":"πάνυ δʼ ἦν ἰσχυρὸν τὸ τεῖχος, καὶ τρίψεσθαι προσδοκῶντι πλείω χρόνον αἰφνιδίως ἀνοίγουσιν οἱ ἔνδον τὰς πύλας καὶ μεθʼ ἱκετηριῶν προελθόντες ἑαυτοὺς παρέδοσαν."},{"number":554,"text":"Κερεάλιος δὲ τούτους παραστησάμενος ἐπὶ Χεβρὼν ἑτέρας πόλεως ἀρχαιοτάτης ἐχώρει· κεῖται δʼ, ὡς ἔφην, αὕτη κατὰ τὴν ὀρεινὴν οὐ πόρρω Ἱεροσολύμων· βιασάμενος δὲ τὰς εἰσόδους τὸ μὲν ἐγκαταληφθὲν πλῆθος ἡβηδὸν ἀναιρεῖ, τὸ δʼ ἄστυ καταπίμπρησι."},{"number":555,"text":"καὶ πάντων ἤδη κεχειρωμένων πλὴν Ἡρωδείου καὶ Μασάδας καὶ Μαχαιροῦντος, ταῦτα δʼ ὑπὸ τῶν λῃστῶν κατείληπτο, σκοπὸς ἤδη τὰ Ἱεροσόλυμα προύκειτο Ῥωμαίοις."},{"number":556,"text":"Ὁ δὲ Σίμων ὡς ἐρρύσατο παρὰ τῶν ζηλωτῶν τὴν γυναῖκα, πάλιν ἐπὶ τὰ λείψανα τῆς Ἰδουμαίας ὑπέστρεψεν, καὶ περιελαύνων πανταχόθεν τὸ ἔθνος εἰς Ἱεροσόλυμα τοὺς πολλοὺς φεύγειν συνηνάγκασεν."},{"number":557,"text":"εἵπετο δὲ καὶ αὐτὸς ἐπὶ τὴν πόλιν καὶ κυκλωσάμενος αὖθις τὸ τεῖχος ὅντινα λάβοι τῶν προϊόντων κατὰ τὴν χώραν ἐργατῶν διέφθειρεν."},{"number":558,"text":"ἦν δὲ τῷ δήμῳ Σίμων μὲν ἔξωθεν Ῥωμαίων φοβερώτερος, οἱ ζηλωταὶ δʼ ἔνδον ἑκατέρων χαλεπώτεροι, κἀν τούτοις ἐπινοίᾳ κακῶν καὶ τόλμῃ τὸ σύνταγμα τῶν Γαλιλαίων διέφερεν·"},{"number":559,"text":"τόν τε γὰρ Ἰωάννην παρήγαγον εἰς ἰσχὺν οὗτοι, κἀκεῖνος αὐτοὺς ἐξ ἧς περιεποιήσατο δυναστείας ἠμείβετο πάντα ἐπιτρέπων δρᾶν ὧν ἕκαστος ἐπεθύμει."},{"number":560,"text":"πόθοι δʼ ἦσαν ἁρπαγῆς ἀπλήρωτοι καὶ τῶν πλουσίων οἴκων ἔρευνα φόνος τε ἀνδρῶν καὶ γυναικῶν ὕβρεις ἐπαίζοντο,"},{"number":561,"text":"μεθʼ αἵματός τε τὰ συληθέντα κατέπινον καὶ μετʼ ἀδείας ἐνεθηλυπάθουν τῷ κόρῳ, κόμας συνθετιζόμενοι καὶ γυναικείας ἐσθῆτας ἀναλαμβάνοντες, καταντλούμενοι δὲ μύροις καὶ πρὸς εὐπρέπειαν ὑπογράφοντες ὀφθαλμούς."},{"number":562,"text":"οὐ μόνον δὲ κόσμον, ἀλλὰ καὶ πάθη γυναικῶν ἐμιμοῦντο καὶ διʼ ὑπερβολὴν ἀσελγείας ἀθεμίτους. ἐπενόησαν ἔρωτας· ἐνηλινδοῦντο δʼ ὡς πορνείῳ τῇ πόλει καὶ πᾶσαν ἀκαθάρτοις ἐμίαναν ἔργοις."},{"number":563,"text":"γυναικιζόμενοι δὲ τὰς ὄψεις ἐφόνων ταῖς δεξιαῖς θρυπτόμενοί τε τοῖς βαδίσμασιν ἐπιόντες ἐξαπίνης ἐγίνοντο πολεμισταὶ τά τε ξίφη προφέροντες ἀπὸ τῶν βεβαμμένων χλανιδίων τὸν προστυχόντα διήλαυνον."},{"number":564,"text":"τοὺς ἀποδιδράσκοντας δὲ Ἰωάννην Σίμων φονικώτερον ἐξεδέχετο, καὶ διαφυγών τις τὸν ἐντὸς τείχους τύραννον ὑπὸ τοῦ πρὸ πυλῶν διεφθείρετο."},{"number":565,"text":"πᾶσα δὲ φυγῆς ὁδὸς τοῖς αὐτομολεῖν πρὸς Ῥωμαίους βουλομένοις ἀπεκέκοπτο."},{"number":566,"text":"Διεστασιάζετο δὲ πρὸς τὸν Ἰωάννην ἡ δύναμις, καὶ πᾶν ὅσον [ἦν] Ἰδουμαίων ἐν αὐτῇ χωρισθὲν ἐπεχείρει τῷ τυράννῳ φθόνῳ τε τῆς ἰσχύος αὐτοῦ καὶ μίσει τῆς ὠμότητος."},{"number":567,"text":"συμβαλόντες δὲ ἀναιροῦσί τε πολλοὺς τῶν ζηλωτῶν καὶ συνελαύνουσι τοὺς λοιποὺς εἰς τὴν βασιλικὴν αὐλὴν κατασκευασθεῖσαν ὑπὸ Γραπτῆς·"},{"number":568,"text":"συγγενὴς δὲ ἦν αὕτη τοῦ τῶν Ἀδιαβηνῶν βασιλέως Ἰζᾶ· συνεισπίπτουσι δὲ οἱ Ἰδουμαῖοι, κἀκεῖθεν εἰς τὸ ἱερὸν ἐξώσαντες τοὺς ζηλωτὰς ἐφʼ ἁρπαγὴν ἐτράποντο τῶν Ἰωάννου χρημάτων·"},{"number":569,"text":"κατὰ γὰρ τὴν προειρημένην αὐλὴν αὐτός τε † ὢν ἐκεῖ καὶ τὰ λάφυρα τῆς τυραννίδος κατέθετο."},{"number":570,"text":"ἐν δὲ τούτῳ τὸ κατὰ τὴν πόλιν ἐσκεδασμένον πλῆθος τῶν ζηλωτῶν εἰς τὸ ἱερὸν πρὸς τοὺς διαπεφευγότας ἠθροίσθη, καὶ κατάγειν αὐτοὺς παρεσκευάσατο Ἰωάννης ἐπί τε τὸν δῆμον καὶ τοὺς Ἰδουμαίους."},{"number":571,"text":"τοῖς δὲ οὐχ οὕτω τὴν ἔφοδον αὐτῶν καταδεῖσαι παρέστη μαχιμωτέροις οὖσιν ὡς τὴν ἀπόνοιαν, μὴ νύκτωρ ἐκ τοῦ ἱεροῦ παρεισδύντες αὐτούς τε διαφθείρωσι καὶ τὸ ἄστυ καταπιμπρῶσι."},{"number":572,"text":"συνελθόντες οὖν μετὰ τῶν ἀρχιερέων ἐβουλεύοντο, τίνα χρὴ τρόπον φυλάξασθαι τὴν ἐπίθεσιν."},{"number":573,"text":"θεὸς δὲ ἄρα τὰς γνώμας αὐτῶν εἰς κακὸν ἔτρεψε, καὶ χαλεπώτερον ἀπωλείας ἐπενόησαν τὸ πρὸς σωτηρίαν φάρμακον· ἵνα γοῦν καταλύσωσιν Ἰωάννην, ἔκριναν δέχεσθαι Σίμωνα καὶ μετὰ ἱκετηριῶν δεύτερον εἰσαγαγεῖν ἑαυτοῖς τύραννον."},{"number":574,"text":"ἐπεραίνετο δʼ ἡ βουλή, καὶ τὸν ἀρχιερέα Ματθίαν πέμψαντες ἐδέοντο Σίμωνι εἰσελθεῖν ὃν πολλὰ ἔδεισαν· συμπαρεκάλουν δὲ οἱ ἐκ τῶν Ἱεροσολύμων τοὺς ζηλωτὰς φεύγοντες πόθῳ τῶν οἴκων καὶ τῶν κτημάτων."},{"number":575,"text":"ὁ δʼ αὐτοῖς ὑπερηφάνως κατανεύσας τὸ δεσπόζειν εἰσέρχεται μὲν ὡς ἀπαλλάξων τῶν ζηλωτῶν τὴν πόλιν σωτὴρ ὑπὸ τοῦ δήμου καὶ κηδεμὼν εὐφημούμενος,"},{"number":576,"text":"παρελθὼν δὲ μετὰ τῆς δυνάμεως ἐσκόπει τὰ περὶ τῆς ἑαυτοῦ δυναστείας καὶ τοὺς καλέσαντας οὐχ ἧττον ἐχθροὺς ἐνόμιζεν ἢ καθʼ ὧν ἐκέκλητο."},{"number":577,"text":"Σίμων μὲν οὕτως ἐνιαυτῷ τρίτῳ τοῦ πολέμου Ξανθικῷ μηνὶ Ἱεροσολύμων ἐγκρατὴς γίνεται· Ἰωάννης δὲ καὶ τὸ τῶν ζηλωτῶν πλῆθος εἰργόμενοι τῶν ἐξόδων τοῦ ἱεροῦ καὶ τὰ τῆς πόλεως ἀπολωλεκότες, παραχρῆμα γὰρ τὰ ἐκείνων οἱ περὶ τὸν Σίμωνα διήρπασαν, ἐν ἀπόρῳ τὴν σωτηρίαν εἶχον."},{"number":578,"text":"προσέβαλλε δὲ τῷ ἱερῷ Σίμων τοῦ δήμου βοηθοῦντος, κἀκεῖνοι καταστάντες ἐπὶ τῶν στοῶν καὶ τῶν ἐπάλξεων ἠμύνοντο τὰς προσβολάς."},{"number":579,"text":"συχνοὶ δʼ ἔπιπτον τῶν περὶ Σίμωνα καὶ πολλοὶ τραυματίαι κατεφέροντο· ῥᾳδίως γὰρ ἐξ ὑπερδεξίου τὰς βολὰς οἱ ζηλωταὶ καὶ οὐκ ἀστόχους ἐποιοῦντο."},{"number":580,"text":"πλεονεκτοῦντες δὲ τῷ τόπῳ καὶ πύργους ἔτι προσκατεσκεύασαν τέσσαρας μεγίστους, ὡς ἀφʼ ὑψηλοτέρων ποιοῖντο τὰς ἀφέσεις, τὸν μὲν κατὰ τὴν ἀνατολικὴν καὶ βόρειον γωνίαν,"},{"number":581,"text":"τὸν δὲ τοῦ ξυστοῦ καθύπερθεν, τὸν δὲ τρίτον κατὰ γωνίαν ἄλλην ἀντικρὺ τῆς κάτω πόλεως·"},{"number":582,"text":"ὁ δὲ λοιπὸς ὑπὲρ τὴν κορυφὴν κατεσκεύαστο τῶν παστοφορίων, ἔνθα τῶν ἱερέων εἷς ἐξ ἔθους ἱστάμενος ἑκάστην ἑβδομάδα εἰσιοῦσαν προεσήμαινε σάλπιγγι δείλης καὶ τελεσθεῖσαν αὖθις περὶ ἑσπέραν, ὅτε μὲν ἀνέργειαν τῷ λαῷ καταγγέλλων, ὅτε δʼ ἔργων ἔχεσθαι."},{"number":583,"text":"διέστησαν δʼ ἐπὶ τῶν πύργων ὀξυβελεῖς τε καὶ λιθοβόλους μηχανὰς τούς τε τοξότας καὶ σφενδονήτας."},{"number":584,"text":"ἔνθα δὴ τὰς μὲν προσβολὰς ὀκνηροτέρας ἐποιεῖτο ὁ Σίμων μαλακιζομένων αὐτῷ τῶν πλειόνων, ἀντεῖχε δʼ ὅμως περιουσίᾳ δυνάμεως· τὰ δὲ ἀπὸ τῶν ὀργάνων βέλη πορρωτέρω φερόμενα πολλοὺς τῶν μαχομένων ἀνῄρει."}],"10":[{"number":585,"text":"Κατὰ δὲ τὸν αὐτὸν καιρὸν περιέσχε καὶ τὴν Ῥώμην πάθη χαλεπά."},{"number":586,"text":"παρῆν μὲν γὰρ ἀπὸ Γερμανίας Οὐιτέλλιος ἅμα τῷ στρατιωτικῷ πολὺ πλῆθος ἐπισυρόμενος ἕτερον, μὴ χωρούμενος δὲ τοῖς ἀποδεδειγμένοις εἰς τοὺς στρατιώτας περιβόλοις ὅλην ἐποιήσατο τὴν Ῥώμην στρατόπεδον καὶ πᾶσαν οἰκίαν ὁπλιτῶν ἐπλήρωσεν."},{"number":587,"text":"οἱ δὲ ἀήθεσιν ὀφθαλμοῖς τὸν Ῥωμαίων πλοῦτον θεασάμενοι καὶ περιλαμφθέντες πάντοθεν ἀργύρῳ τε καὶ χρυσῷ τὰς ἐπιθυμίας μόλις κατεῖχον, ὥστε μὴ ἐφʼ ἁρπαγὰς τρέπεσθαί τε καὶ τοὺς ἐμποδὼν γινομένους ἀναιρεῖν. καὶ τὰ μὲν κατὰ τὴν Ἰταλίαν ἐν τούτοις ἦν."},{"number":588,"text":"Οὐεσπασιανὸς δὲ ὡς τὰ πλησίον Ἱεροσολύμων καταστρεψάμενος ὑπέστρεψεν εἰς Καισάρειαν, ἀκούει τὰς κατὰ τὴν Ῥώμην ταραχὰς καὶ Οὐιτέλλιον αὐτοκράτορα."},{"number":589,"text":"τοῦτο αὐτὸν καίπερ ἄρχεσθαι καθάπερ ἄρχειν καλῶς ἐπιστάμενον εἰς ἀγανάκτησιν προήγαγεν, καὶ τὸν μὲν ὡς ἐρήμου καταμανέντα τῆς ἡγεμονίας ἠδόξει δεσπότην,"},{"number":590,"text":"περιαλγήσας δὲ τῷ πάθει καρτερεῖν τὴν βάσανον οὐχ οἷός τε ἦν καὶ τῆς πατρίδος πορθουμένης ἑτέροις προσευσχολεῖν πολέμοις."},{"number":591,"text":"ἀλλʼ ὅσον ὁ θυμὸς ἤπειγεν ἐπὶ τὴν ἄμυναν, τοσοῦτον εἶργεν ἔννοια τοῦ διαστήματος· πολλὰ γὰρ φθάσαι πανουργήσασαν τὴν τύχην πρὶν αὐτὸν εἰς τὴν Ἰταλίαν περαιωθῆναι καὶ ταῦτα χειμῶνος ὥρᾳ πλέοντα· σφαδάζουσαν ἤδη κατεῖχεν τὴν ὀργήν."},{"number":592,"text":"Συνιόντες δὲ οἵ τε ἡγεμόνες καὶ στρατιῶται καθʼ ἑταιρίαν φανερῶς ἤδη μεταβολὴν ἐβουλεύοντο καὶ διαγανακτοῦντες ἐβόων, ὡς οἱ μὲν ἐπὶ τῆς Ῥώμης στρατιῶται τρυφῶντες καὶ μηδʼ ἀκούειν πολέμου φήμην ὑπομένοντες διαχειροτονοῦσιν οἷς βούλονται τὴν ἡγεμονίαν καὶ πρὸς ἐλπίδα λημμάτων ἀποδεικνύουσιν αὐτοκράτορας,"},{"number":593,"text":"αὐτοὶ δὲ διὰ τοσούτων κεχωρηκότες πόνων καὶ γηρῶντες ὑπὸ τοῖς κράνεσιν ἑτέροις χαρίζονται τὴν ἐξουσίαν καὶ ταῦτα τὸν ἀξιώτερον ἄρχειν παρʼ αὑτοῖς ἔχοντες."},{"number":594,"text":"ᾧ τίνα δικαιοτέραν ποτὲ τῆς εἰς αὐτοὺς εὐνοίας ἀποδώσειν ἀμοιβήν, εἰ τὴν νῦν καταπροοῖντο; τοσούτῳ δʼ εἶναι Οὐεσπασιανὸν ἡγεμονεύειν Οὐιτελλίου δικαιότερον, ὅσῳ καὶ αὐτοὺς τῶν ἐκεῖνον ἀποδειξάντων·"},{"number":595,"text":"οὐ γὰρ δὴ μικροτέρους τῶν ἀπὸ Γερμανίας διενηνοχέναι πολέμους οὐδὲ τῶν ἐκεῖθεν καταγαγόντων τὸν τύραννον ἡττῆσθαι τοῖς ὅπλοις."},{"number":596,"text":"ἀγῶνος δὲ ἐνδεήσειν οὐδέν· οὐ γὰρ τὴν σύγκλητον ἢ τὸν Ῥωμαίων δῆμον ἀνέξεσθαι τῆς Οὐιτελλίου λαγνείας ἀντὶ τῆς Οὐεσπασιανοῦ σωφροσύνης, οὐδʼ ἀντὶ μὲν ἡγεμόνος ἀγαθοῦ τύραννον ὠμότατον, ἄπαιδα δὲ ἀντὶ πατρὸς αἱρήσεσθαι προστάτην· μέγιστον γὰρ δὴ πρὸς ἀσφάλειαν εἰρήνης εἶναι τὰς γνησίους τῶν βασιλέων διαδοχάς."},{"number":597,"text":"εἴτε οὖν ἐμπειρίᾳ γήρως προσήκει τὸ ἄρχειν, Οὐεσπασιανὸν αὐτοὺς ἔχειν, εἴτε νεότητος ἀλκῇ, Τίτον· κραθήσεσθαι γὰρ τῆς παρʼ ἀμφοῖν ἡλικίας τὸ ὠφέλιμον."},{"number":598,"text":"χορηγήσειν δὲ οὐ μόνον αὐτοὶ τὴν ἰσχὺν τοῖς ἀποδειχθεῖσι τρία τάγματα καὶ τὰς παρὰ τῶν βασιλέων συμμαχίας ἔχοντες συνετηρήσαμεν τά τε πρὸς ἕω πάντα καὶ τῆς Εὐρώπης ὅσα τῶν ἀπὸ Οὐιτελλίου φόβων κεχώρισται, καὶ τοὺς ἐπὶ τῆς Ἰταλίας δὲ συμμάχους,"},{"number":599,"text":"ἀδελφὸν Οὐεσπασιανοῦ καὶ παῖδα ἕτερον, ὧν τῷ μὲν προσθήσεσθαι πολλοὺς τῶν ἐν ἀξιώματι νέων, τὸν δὲ καὶ τὴν τῆς πόλεως φυλακὴν πεπιστεῦσθαι, μέρος οὐκ ὀλίγον εἰς ἐπιβολὴν ἡγεμονίας."},{"number":600,"text":"καθόλου τε ἂν βραδύνωσιν αὐτοί, τάχα τὴν σύγκλητον ἀποδείξειν τὸν ὑπὸ τῶν συντετηρηκότων στρατιωτῶν ἀτιμούμενον."},{"number":601,"text":"Τοιαῦτα κατὰ συστροφὰς οἱ στρατιῶται διελάλουν· ἔπειτα συναθροισθέντες καὶ παρακροτήσαντες ἀλλήλους ἀναγορεύουσι τὸν Οὐεσπασιανὸν αὐτοκράτορα καὶ σώζειν τὴν κινδυνεύουσαν ἡγεμονίαν παρεκάλουν."},{"number":602,"text":"τῷ δὲ φροντὶς μὲν ἦν πάλαι περὶ τῶν ὅλων, οὔτι γε μὴν αὐτὸς ἄρχειν προῄρητο, τοῖς μὲν ἔργοις ἑαυτὸν ἄξιον ἡγούμενος, προκρίνων δὲ τῶν ἐν λαμπρότητι κινδύνων τὴν ἐν ἰδιώταις ἀσφάλειαν."},{"number":603,"text":"ἀρνουμένῳ δὲ μᾶλλον οἱ ἡγεμόνες ἐπέκειντο καὶ περιχυθέντες οἱ στρατιῶται ξιφήρεις ἀναιρεῖν αὐτὸν ἠπείλουν, εἰ μὴ βούλοιτο ζῆν ἀξίως."},{"number":604,"text":"πολλὰ δὲ πρὸς αὐτοὺς διατεινάμενος ἐξ ὧν διωθεῖτο τὴν ἀρχὴν τελευταῖον, ὡς οὐκ ἔπειθεν, εἴκει τοῖς ὀνομάσασι."},{"number":605,"text":"Προτρεπομένων δʼ αὐτὸν ἤδη Μουκιανοῦ τε καὶ τῶν ἄλλων ἡγεμόνων ὡς αὐτοκράτορα καὶ τῆς ἄλλης στρατιᾶς ἄγειν ἐπὶ πᾶν τὸ ἀντίπαλον, ὁ δὲ πρῶτον τῶν ἐπʼ Ἀλεξανδρείας εἴχετο πραγμάτων, εἰδὼς πλεῖστον τῆς ἡγεμονίας μέρος τὴν Αἴγυπτον οὖσαν διὰ τὴν τοῦ σίτου χορηγίαν,"},{"number":606,"text":"ἧς κρατήσας εἰ παρέλκοι καὶ βίᾳ καθαιρήσειν ἤλπιζεν Οὐιτέλλιον, οὐ γὰρ ἀνέξεσθαι πείνης ἐπὶ Ῥώμης τὸ πλῆθος, τὰ δύο τε ἐπὶ τῆς Ἀλεξανδρείας τάγματα προσποιήσασθαι βουλόμενος."},{"number":607,"text":"ἐνεθυμεῖτο δὲ καὶ πρόβλημα τὴν χώραν ἔχειν τῶν ἀπὸ τῆς τύχης ἀδήλων· ἔστι γὰρ κατά τε γῆν δυσέμβολος καὶ τὰ πρὸς θαλάσσης ἀλίμενος,"},{"number":608,"text":"κατὰ μὲν ἑσπέραν προβεβλημένη τὰ ἄνυδρα τῆς Λιβύης, κατὰ δὲ μεσημβρίαν τὴν διορίζουσαν ἀπὸ Αἰθιόπων τὴν Συήνην καὶ τοὺς ἀπλώτους τοῦ ποταμοῦ καταράκτας, ἀπὸ δὲ τῆς ἀνατολῆς τὴν ἐρυθρὰν θάλασσαν ἀναχεομένην μέχρι Κοπτοῦ."},{"number":609,"text":"βόρειον δὲ τεῖχος αὐτῇ ἥ τε μέχρι Συρίας γῆ καὶ τὸ καλούμενον Αἰγύπτιον πέλαγος, πᾶν ἄπορον ὅρμων."},{"number":610,"text":"τετείχισται μὲν οὕτως ἡ Αἴγυπτος πάντοθεν· τὸ μεταξὺ δὲ Πηλουσίου καὶ Συήνης μῆκος αὐτῆς σταδίων δισχιλίων, ὅ τε ἀπὸ τῆς Πλινθίνης ἀνάπλους εἰς τὸ Πηλούσιον σταδίων τρισχιλίων ἑξακοσίων."},{"number":611,"text":"ὁ δὲ Νεῖλος ἀναπλεῖται μέχρι τῆς Ἐλεφάντων καλουμένης πόλεως, ὑπὲρ ἣν εἴργουσι προσωτέρω χωρεῖν οὓς προειρήκαμεν καταράκτας."},{"number":612,"text":"δυσπρόσιτος δὲ λιμὴν ναυσὶ καὶ κατʼ εἰρήνην Ἀλεξανδρείας· στενός τε γὰρ εἴσπλους καὶ πέτραις ὑφάλοις τὸν ἐπʼ εὐθὺ καμπτόμενος δρόμον."},{"number":613,"text":"καὶ τὸ μὲν ἀριστερὸν αὐτοῦ μέρος πέφρακται χειροκμήτοις σκέλεσιν, ἐν δεξιᾷ δὲ ἡ προσαγορευομένη Φάρος νῆσος πρόκειται, πύργον ἔχουσα μέγιστον ἐκπυρσεύοντα τοῖς καταπλέουσιν ἐπὶ τριακοσίους σταδίους, ὡς ἐν νυκτὶ πόρρωθεν ὁρμίζοιντο πρὸς τὴν δυσχέρειαν τοῦ κατάπλου."},{"number":614,"text":"περὶ ταύτην τὴν νῆσον καταβέβληται χειροποίητα τείχη μέγιστα, προσαρασσόμενον δὲ τούτοις τὸ πέλαγος καὶ τοῖς ἄντικρυς ἕρκεσιν ἀμφαγνυμένον ἐκτραχύνει τὸν πόρον καὶ σφαλερὰν διὰ στενοῦ τὴν εἴσοδον ἀπεργάζεται."},{"number":615,"text":"ὁ μέντοι γε λιμὴν ἀσφαλέστατος ἔνδον καὶ τριάκοντα σταδίων τὸ μέγεθος, εἰς ὃν τά τε λείποντα τῇ χώρᾳ πρὸς εὐδαιμονίαν κατάγεται καὶ τὰ περισσεύοντα τῶν ἐπιχωρίων ἀγαθῶν εἰς πᾶσαν χωρίζεται τὴν οἰκουμένην."},{"number":616,"text":"Ἐφίετο μὲν οὖν εἰκότως τῶν ταύτῃ πραγμάτων Οὐεσπασιανὸς εἰς βεβαίωσιν τῆς ὅλης ἡγεμονίας, ἐπιστέλλει δʼ εὐθὺς τῷ διέποντι τὴν Αἴγυπτον καὶ τὴν Ἀλεξάνδρειαν Τιβερίῳ Ἀλεξάνδρῳ, δηλῶν τὸ τῆς στρατιᾶς πρόθυμον, καὶ ὡς αὐτὸς ὑποδὺς ἀναγκαίως τὸ βάρος τῆς ἡγεμονίας συνεργὸν αὐτὸν καὶ βοηθὸν προσλαμβάνοι."},{"number":617,"text":"παραναγνοὺς δὲ τὴν ἐπιστολὴν Ἀλέξανδρος προθύμως τά τε τάγματα καὶ τὸ πλῆθος εἰς αὐτὸν ὥρκωσεν. ἑκάτεροι δὲ ἀσμένως ὑπήκουσαν τὴν ἀρετὴν τἀνδρὸς ἐκ τῆς ἐγγὺς στρατηγίας εἰδότες."},{"number":618,"text":"καὶ ὁ μὲν πεπιστευμένος ἤδη τὰ περὶ τὴν ἀρχὴν προπαρεσκεύαζεν αὐτῷ καὶ τὰ πρὸς τὴν ἄφιξιν, τάχιον δʼ ἐπινοίας διήγγελλον αἱ φῆμαι τὸν ἐπὶ τῆς ἀνατολῆς αὐτοκράτορα, καὶ πᾶσα μὲν πόλις ἑώρταζεν εὐαγγέλια [δὲ] καὶ θυσίας ὑπὲρ αὐτοῦ ἐπετέλει."},{"number":619,"text":"τὰ δὲ κατὰ Μυσίαν καὶ Παννονίαν τάγματα, μικρῷ πρόσθεν κεκινημένα πρὸς τὴν Οὐιτελλίου τόλμαν, μείζονι χαρᾷ Οὐεσπασιανῷ τὴν ἡγεμονίαν ὤμνυον."},{"number":620,"text":"ὁ δʼ ἀναζεύξας ἀπὸ Καισαρείας εἰς Βηρυτὸν παρῆν, ἔνθα πολλαὶ μὲν ἀπὸ τῆς Συρίας αὐτῷ, πολλαὶ δὲ κἀπὸ τῶν ἄλλων ἐπαρχιῶν πρεσβεῖαι συνήντων, στεφάνους παρʼ ἑκάστης πόλεως καὶ συγχαρτικὰ προσφέρουσαι ψηφίσματα."},{"number":621,"text":"παρῆν δὲ καὶ Μουκιανὸς ὁ τῆς ἐπαρχίας ἡγεμὼν τὸ πρόθυμον τῶν δήμων καὶ τοὺς κατὰ πόλιν ὅρκους ἀπαγγέλλων."},{"number":622,"text":"Προχωρούσης δὲ πανταχοῦ κατὰ νοῦν τῆς τύχης καὶ τῶν πραγμάτων συννενευκότων ἐκ τοῦ πλείστου μέρους, ἤδη παρίστατο τῷ Οὐεσπασιανῷ νοεῖν, ὡς οὐ δίχα δαιμονίου προνοίας ἅψαιτο τῆς ἀρχῆς, ἀλλὰ δικαία τις εἱμαρμένη περιαγάγοι τὸ κρατεῖν τῶν ὅλων ἐπʼ αὐτόν·"},{"number":623,"text":"ἀναμιμνήσκεται γὰρ τά τε ἄλλα σημεῖα, πολλὰ δʼ αὐτῷ γεγόνει πανταχοῦ προφαίνοντα τὴν ἡγεμονίαν, καὶ τὰς τοῦ Ἰωσήπου φωνάς, ὃς αὐτὸν ἔτι ζῶντος Νέρωνος αὐτοκράτορα προσειπεῖν ἐθάρσησεν."},{"number":624,"text":"ἐξεπέπληκτο δὲ τὸν ἄνδρα δεσμώτην ἔτι ὄντα παρʼ αὐτῷ, καὶ προσκαλεσάμενος Μουκιανὸν ἅμα τοῖς ἄλλοις ἡγεμόσι καὶ φίλοις πρῶτον μὲν αὐτοῦ τὸ δραστήριον ἐκδιηγεῖτο καὶ ὅσα περὶ τοῖς Ἰωταπάτοις διʼ αὐτὸν ἔκαμον,"},{"number":625,"text":"ἔπειτα τὰς μαντείας, ἃς αὐτὸς μὲν ὑπώπτευσε τότε πλάσματα τοῦ δέους, ἀποδειχθῆναι δὲ ὑπὸ τοῦ χρόνου καὶ τῶν πραγμάτων θείας."},{"number":626,"text":"αἰσχρὸν οὖν, ἔφη, τὸν προθεσπίσαντά μοι τὴν ἀρχὴν καὶ διάκονον τῆς τοῦ θεοῦ φωνῆς ἔτι αἰχμαλώτου τάξιν ἢ δεσμώτου τύχην ὑπομένειν καὶ καλέσας τὸν Ἰώσηπον λυθῆναι κελεύει."},{"number":627,"text":"τοῖς μὲν οὖν ἡγεμόσιν ἐκ τῆς εἰς τὸν ἀλλόφυλον ἀμοιβῆς λαμπρὰ καὶ περὶ αὑτῶν ἐλπίζειν παρέστη, συνὼν δὲ τῷ πατρὶ Τίτος"},{"number":628,"text":"δίκαιον, ὦ πάτερ, ἔφη, τοῦ Ἰωσήπου καὶ τὸ ὄνειδος ἀφαιρεθῆναι σὺν τῷ σιδήρῳ· γενήσεται γὰρ ὅμοιος τῷ μὴ δεθέντι τὴν ἀρχήν, ἂν αὐτοῦ μὴ λύσωμεν ἀλλὰ κόψωμεν τὰ δεσμά. τοῦτο γὰρ ἐπὶ τῶν μὴ δεόντως δεθέντων πράττεται."},{"number":629,"text":"συνεδόκει ταῦτα, καὶ παρελθών τις πελέκει διέκοψε τὴν ἅλυσιν. ὁ δὲ Ἰώσηπος εἰληφὼς περὶ τῶν προειρημένων γέρας τὴν ἐπιτιμίαν ἤδη καὶ περὶ τῶν μελλόντων ἀξιόπιστος ἦν."}],"11":[{"number":630,"text":"Οὐεσπασιανὸς δὲ ταῖς πρεσβείαις χρηματίσας καὶ καταστησάμενος ἑκάστοις τὰς ἀρχὰς δικαίως καὶ διὰ τῶν ἀξίων εἰς Ἀντιόχειαν ἀφικνεῖται."},{"number":631,"text":"καὶ βουλευόμενος, ποῖ τρέπεσθαι, προυργιαίτερα τῆς εἰς Ἀλεξάνδρειαν ὁρμῆς τὰ κατὰ τὴν Ῥώμην ἔκρινε, τὴν μὲν βέβαιον οὖσαν ὁρῶν, τὰ δʼ ὑπὸ Οὐιτελλίου ταρασσόμενα."},{"number":632,"text":"πέμπει δὴ Μουκιανὸν εἰς τὴν Ἰταλίαν παραδοὺς ἱππέων τε καὶ πεζῶν συχνὴν δύναμιν. ὁ δὲ διὰ τὴν τοῦ χειμῶνος ἀκμὴν δείσας τὸ πλεῖν πεζῇ τὴν στρατιὰν ἦγε διὰ Καππαδοκίας καὶ Φρυγίας."},{"number":633,"text":"Ἐν δὲ τούτῳ καὶ Ἀντώνιος Πρῖμος ἀναλαβὼν τὸ τρίτον τάγμα τῶν κατὰ Μυσίαν, ἔτυχεν δʼ ἡγεμονεύων αὐτόθι, Οὐιτελλίῳ παραταξόμενος ἠπείγετο."},{"number":634,"text":"Οὐιτέλλιος δὲ αὐτῷ συναντήσοντα μετὰ πολλῆς δυνάμεως Καικίναν Ἀλιηνὸν ἐκπέμπει, μέγα θαρρῶν τἀνδρὶ διὰ τὴν ἐπʼ Ὄθωνι νίκην. ὁ δὲ ἀπὸ τῆς Ῥώμης ἐλαύνων διὰ τάχους περὶ Κρέμωνα τῆς Γαλατίας τὸν Ἀντώνιον καταλαμβάνει· μεθόριος δʼ ἐστὶν ἡ πόλις αὕτη τῆς Ἰταλίας."},{"number":635,"text":"κατιδὼν δὲ ἐνταῦθα τὸ πλῆθος τῶν πολεμίων καὶ τὴν εὐταξίαν, συμβαλεῖν μὲν οὐκ ἐθάρρει, σφαλερὰν δὲ τὴν ἀναχώρησιν λογιζόμενος προδοσίαν ἐβουλεύετο."},{"number":636,"text":"συναγαγὼν δὲ τοὺς ὑπʼ αὐτὸν ἑκατοντάρχας καὶ χιλιάρχους ἐνῆγεν μεταβῆναι πρὸς τὸν Ἀντώνιον, ταπεινῶν μὲν τὰ Οὐιτελλίου πράγματα, τὴν Οὐεσπασιανοῦ δʼ ἰσχὺν ἐπαίρων,"},{"number":637,"text":"καὶ παρʼ ᾧ μὲν εἶναι λέγων μόνον τῆς ἀρχῆς ὄνομα, παρʼ ᾧ δὲ τὴν δύναμιν, καὶ αὐτοὺς δὲ ἄμεινον προλαβόντας τὴν ἀνάγκην ποιῆσαι χάριν καὶ μέλλοντας ἡττᾶσθαι τοῖς ὅπλοις ταῖς γνώμαις τὸν κίνδυνον φθάσαι·"},{"number":638,"text":"Οὐεσπασιανὸν μὲν γὰρ ἱκανὸν εἶναι καὶ χωρὶς αὐτῶν προσκτήσασθαι καὶ τὰ λείποντα, Οὐιτέλλιον δʼ οὐδὲ σὺν αὐτοῖς τηρῆσαι τὰ ὄντα."},{"number":639,"text":"Πολλὰ τοιαῦτα λέγων ἔπεισε καὶ πρὸς τὸν Ἀντώνιον αὐτομολεῖ μετὰ τῆς δυνάμεως."},{"number":640,"text":"τῆς δʼ αὐτῆς νυκτὸς ἐμπίπτει μετάνοια τοῖς στρατιώταις καὶ δέος τοῦ προπέμψαντος, εἰ κρείσσων γένοιτο· σπασάμενοι δὲ τὰ ξίφη τὸν Καικίναν ὥρμησαν ἀνελεῖν, κἂν ἐπράχθη τὸ ἔργον αὐτοῖς, εἰ μὴ προσπίπτοντες οἱ χιλίαρχοι καθικέτευσαν αὐτούς."},{"number":641,"text":"οἱ δὲ τοῦ μὲν κτείνειν ἀπέσχοντο, δήσαντες δὲ τὸν προδότην οἷοί τε ἦσαν πέμπειν Οὐιτελλίῳ. ταῦτʼ ἀκούσας ὁ Πρῖμος αὐτίκα τοὺς σφετέρους ἀνίστησι καὶ μετὰ τῶν ὅπλων ἦγεν ἐπὶ τοὺς ἀποστάντας."},{"number":642,"text":"οἱ δὲ παραταξάμενοι πρὸς ὀλίγον μὲν ἀντέσχον, αὖθις δὲ τραπέντες ἔφευγον εἰς τὴν Κρέμωνα. τοὺς δὲ ἱππεῖς ἀναλαβὼν Πρῖμος ὑποτέμνεται τὰς εἰσόδους αὐτῶν, καὶ τὸ μὲν πολὺ πλῆθος κυκλωσάμενος πρὸ τῆς πόλεως διαφθείρει, τῷ δὲ λοιπῷ συνεισπεσὼν διαρπάσαι τὸ ἄστυ τοῖς στρατιώταις ἐφῆκεν."},{"number":643,"text":"ἔνθα δὴ πολλοὶ μὲν τῶν ξένων ἔμποροι, πολλοὶ δὲ τῶν ἐπιχωρίων ἀπώλοντο, πᾶσα δὲ καὶ ἡ Οὐιτελλίου στρατιά, μυριάδες ἀνδρῶν τρεῖς καὶ διακόσιοι· τῶν δʼ ἀπὸ τῆς Μυσίας Ἀντώνιος τετρακισχιλίους ἀποβάλλει καὶ πεντακοσίους."},{"number":644,"text":"λύσας δὲ τὸν Καικίναν πέμπει πρὸς Οὐεσπασιανὸν ἀγγελοῦντα τὰ πεπραγμένα. καὶ ὃς ἐλθὼν ἀπεδέχθη τε ὑπʼ αὐτοῦ καὶ τὰ τῆς προδοσίας ὀνείδη ταῖς παρʼ ἐλπίδα τιμαῖς ἐπεκάλυψεν."},{"number":645,"text":"Ἀνεθάρσει δὲ ἤδη καὶ κατὰ τὴν Ῥώμην Σαβῖνος, ὡς πλησίον Ἀντώνιος ὢν ἀπηγγέλλετο, καὶ συναθροίσας τὰ τῶν νυκτοφυλάκων στρατιωτῶν τάγματα νύκτωρ καταλαμβάνει τὸ Καπετώλιον."},{"number":646,"text":"μεθʼ ἡμέραν δʼ αὐτῷ πολλοὶ τῶν ἐπισήμων προσεγένοντο καὶ Δομετιανὸς ὁ τἀδελφοῦ παῖς, μεγίστη μοῖρα τῶν εἰς τὸ κρατεῖν ἐλπίδων."},{"number":647,"text":"Οὐιτελλίῳ δὲ Πρίμου μὲν ἐλάττων φροντὶς ἦν, τεθύμωτο δʼ ἐπὶ τοὺς συναποστάντας τῷ Σαβίνῳ, καὶ διὰ τὴν ἔμφυτον ὠμότητα διψῶν αἵματος εὐγενοῦς τοῦ στρατιωτικοῦ τὴν συγκατελθοῦσαν αὐτῷ δύναμιν ἐπαφίησι τῷ Καπετωλίῳ."},{"number":648,"text":"πολλὰ μὲν οὖν ἔκ τε ταύτης καὶ τῶν ἀπὸ τοῦ ἱεροῦ μαχομένων ἐτολμήθη, τέλος δὲ τῷ πλήθει περιόντες οἱ ἀπὸ τῆς Γερμανίας ἐκράτησαν τοῦ λόφου."},{"number":649,"text":"καὶ Δομετιανὸς μὲν σὺν πολλοῖς τῶν ἐν τέλει Ῥωμαίων δαιμονιώτερον διασώζεται, τὸ δὲ λοιπὸν πλῆθος ἅπαν κατεκόπη, καὶ Σαβῖνος ἀναχθεὶς ἐπὶ Οὐιτέλλιον ἀναιρεῖται διαρπάσαντές τε οἱ στρατιῶται τὰ ἀναθήματα τὸν ναὸν ἐνέπρησαν."},{"number":650,"text":"καὶ μετὰ μίαν ἡμέραν εἰσελαύνει μὲν Ἀντώνιος μετὰ τῆς δυνάμεως, ὑπήντων δʼ οἱ Οὐιτελλίου καὶ τριχῆ κατὰ τὴν πόλιν συμβαλόντες ἀπώλοντο πάντες."},{"number":651,"text":"προέρχεται δὲ μεθύων ἐκ τοῦ βασιλείου Οὐιτέλλιος καὶ δαψιλέστερον ὥσπερ ἐν ἐσχάτοις τῆς ἀσώτου τραπέζης κεκορεσμένος."},{"number":652,"text":"συρεὶς δὲ διὰ τοῦ πλήθους καὶ παντοδαπαῖς αἰκίαις ἐξυβρισθεὶς ἐπὶ μέσης τῆς Ῥώμης ἀποσφάττεται, μῆνας ὀκτὼ κρατήσας καὶ ἡμέρας πέντε, ὃν εἰ συνέβη πλείω βιῶσαι χρόνον, ἐπιλιπεῖν ἂν αὐτοῦ τῇ λαγνείᾳ τὴν ἡγεμονίαν οἶμαι."},{"number":653,"text":"τῶν δʼ ἄλλων νεκρῶν ὑπὲρ πέντε μυριάδες ἠριθμήθησαν."},{"number":654,"text":"ταῦτα μὲν τρίτῃ μηνὸς Ἀπελλαίου πέπρακτο, τῇ δʼ ὑστεραίᾳ Μουκιανὸς εἴσεισι μετὰ τῆς στρατιᾶς, καὶ τοὺς σὺν Ἀντωνίῳ παύσας τοῦ κτείνειν, ἔτι γὰρ ἐξερευνώμενοι τὰς οἰκίας πολλοὺς μὲν τῶν Οὐιτελλίου στρατιωτῶν πολλοὺς δὲ τῶν δημοτικῶν ὡς ἐκείνου ἀνῄρουν φθάνοντες τῷ θυμῷ τὴν ἀκριβῆ διάκρισιν, προαγαγὼν δὲ τὸν Δομετιανὸν συνίστησι τῷ πλήθει μέχρι τῆς τοῦ πατρὸς ἀφίξεως ἡγεμόνα."},{"number":655,"text":"ὁ δὲ δῆμος ἀπηλλαγμένος ἤδη τῶν φόβων αὐτοκράτορα Οὐεσπασιανὸν εὐφήμει, καὶ ἅμα τήν τε τούτου βεβαίωσιν ἑώρταζε καὶ τὴν Οὐιτελλίου κατάλυσιν."},{"number":656,"text":"Εἰς δὲ τὴν Ἀλεξάνδρειαν ἀφιγμένῳ τῷ Οὐεσπασιανῷ τὰ ἀπὸ τῆς Ῥώμης εὐαγγέλια ἧκε καὶ πρέσβεις ἐκ πάσης τῆς ἰδίας οἰκουμένης συνηδόμενοι· μεγίστη τε οὖσα μετὰ τὴν Ῥώμην ἡ πόλις στενοτέρα τοῦ πλήθους ἠλέγχετο."},{"number":657,"text":"κεκυρωμένης δὲ ἤδη τῆς ἀρχῆς ἁπάσης καὶ σεσωσμένων παρʼ ἐλπίδα Ῥωμαίοις τῶν πραγμάτων Οὐεσπασιανὸς ἐπὶ τὰ λείψανα τῆς Ἰουδαίας τὸν λογισμὸν ἐπέστρεφεν."},{"number":658,"text":"αὐτὸς μέντοι γε εἰς τὴν Ῥώμην ὥρμητο λήξαντος τοῦ χειμῶνος ἀνάγεσθαι καὶ τάχος τὰ κατὰ τὴν Ἀλεξάνδρειαν διῴκει, τὸν δὲ υἱὸν Τίτον μετὰ τῆς ἐκκρίτου δυνάμεως ἀπέστειλεν ἐξαιρήσοντα τὰ Ἱεροσόλυμα."},{"number":659,"text":"ὁ δὲ προελθὼν πεζῇ μέχρι Νικοπόλεως, εἴκοσι δὲ αὕτη διέχει τῆς Ἀλεξανδρείας σταδίους, κἀκεῖθεν ἐπιβήσας τὴν στρατιὰν μακρῶν πλοίων ἀναπλεῖ διὰ τοῦ Νείλου κατὰ τὸν Μενδήσιον νομὸν μέχρι πόλεως Θμούεως."},{"number":660,"text":"ἐκεῖθεν δʼ ἀποβὰς ὁδεύει καὶ κατὰ πολίχνην Τάνιν αὐλίζεται. δεύτερος αὐτῷ σταθμὸς Ἡρακλέους πόλις καὶ τρίτος Πηλούσιον γίνεται."},{"number":661,"text":"δυσὶ δʼ ἡμέραις ἐνταῦθα τὴν στρατιὰν ἀναλαβὼν τῇ τρίτῃ διέξεισι τὰς ἐμβολὰς τοῦ Πηλουσίου, καὶ προελθὼν σταθμὸν ἕνα διὰ τῆς ἐρήμου πρὸς τῷ τοῦ Κασίου Διὸς ἱερῷ στρατοπεδεύεται, τῇ δʼ ὑστεραίᾳ κατὰ τὴν Ὀστρακίνην· οὗτος ὁ σταθμὸς ἦν ἄνυδρος, ἐπεισάκτοις δὲ ὕδασιν οἱ ἐπιχώριοι χρῶνται."},{"number":662,"text":"μετὰ ταῦτα πρὸς Ῥινοκουρούροις ἀναπαύεται, κἀκεῖθεν εἰς Ῥάφειαν προελθὼν σταθμὸν τέταρτον, ἔστι δʼ ἡ πόλις αὕτη Συρίας ἀρχή,"},{"number":663,"text":"τὸ πέμπτον ἐν Γάζῃ τίθεται στρατόπεδον, μεθʼ ἣν εἰς Ἀσκάλωνα κἀκεῖθεν εἰς Ἰάμνειαν, ἔπειτα εἰς Ἰόππην κἀξ Ἰόππης εἰς Καισάρειαν ἀφικνεῖται διεγνωκὼς αὐτόθι τὰς ἄλλας δυνάμεις ἀθροίζειν."}]},"count":663};})();